select l.id, 'posicao-da-lingua', 14, '{"title":"Posicao da lingua","body":"| Som | Lingua |\r\n|---|---|\r\n| `g/ch` | parte de tras sobe para a garganta |\r\n| `u` | lingua a frente, labios redondos |\r\n| `ng` | parte de tras toca zona mole |\r\n| `t` final | ponta toca atras dos dentes |"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
