select l.id, 'sons-de-garganta', 15, '{"title":"Sons de garganta","body":"Treino:\r\n\r\n```text\r\ng\r\ngr\r\ngrijp\r\nbegrijp\r\nik begrijp\r\nik begrijp het niet\r\n```\r\n\r\nRegras:\r\n\r\n- nao deve magoar\r\n- nao vem da frente da boca\r\n- deve soar como friccao\r\n- deve ser reconhecivel"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
