insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A0-05', 'Numeros 0-100', 'reconhecer vocabulario essencial em audio lento e natural', 4, 'published', 35
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A0'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar e ajustar a fala ate se aproximar do neerlandes natural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Esta licao prepara o aluno para numeros, precos, telefone, senha de atendimento e idade. O foco e transformar linguagem basica em acao real, com audicao, pronuncia fisica, repeticao, shadowing e resposta oral.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nPessoa nativa fala em ritmo natural.\r\nAluno identifica palavras-chave e responde: Mijn nummer is zevenentwintig.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- reconhecer vocabulario essencial em audio lento e natural\r\n- usar frases praticas em contexto real\r\n- treinar pronuncia pelo audio nativo\r\n- fazer shadowing por blocos\r\n- responder oralmente sem bloquear\r\n- completar exercicios escritos e auditivos\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nMijn nummer is zevenentwintig.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nMijn nummer is zevenentwintig.\r\nDat kost vijf euro.\r\nIk ben dertig jaar.\r\nKunt u het nummer herhalen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `nul`\r\n\r\nTraducao PT: zero  \r\nTraducao EN: zero  \r\nAudio nativo: `audio/A0-05/words/nul.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `nul`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnul\r\nnul em bloco\r\nnul em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `nul` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `nul` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `een`\r\n\r\nTraducao PT: um/uma  \r\nTraducao EN: one  \r\nAudio nativo: `audio/A0-05/words/een.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `een`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\neen\r\neen em bloco\r\neen em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `een` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `een` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `vijf`\r\n\r\nTraducao PT: cinco  \r\nTraducao EN: five  \r\nAudio nativo: `audio/A0-05/words/vijf.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vijf`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvijf\r\nvijf em bloco\r\nvijf em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `vijf` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vijf` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `tien`\r\n\r\nTraducao PT: dez  \r\nTraducao EN: ten  \r\nAudio nativo: `audio/A0-05/words/tien.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `tien`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntien\r\ntien em bloco\r\ntien em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `tien` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `tien` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `twintig`\r\n\r\nTraducao PT: vinte  \r\nTraducao EN: twenty  \r\nAudio nativo: `audio/A0-05/words/twintig.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `twintig`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntwintig\r\ntwintig em bloco\r\ntwintig em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `twintig` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `twintig` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `honderd`\r\n\r\nTraducao PT: cem  \r\nTraducao EN: hundred  \r\nAudio nativo: `audio/A0-05/words/honderd.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `honderd`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhonderd\r\nhonderd em bloco\r\nhonderd em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `honderd` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `honderd` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-05';
