select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Gramatica minima: `Sujeito + verbo + informacao` e perguntas formais com `Kunt u + verbo...?`. O objetivo A0 e compreender e responder, nao explicar regras longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-05';
