insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A0-06', 'Dias, meses e datas', 'reconhecer vocabulario essencial em audio lento e natural', 5, 'published', 35
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A0'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar e ajustar a fala ate se aproximar do neerlandes natural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Esta licao prepara o aluno para marcacoes, agenda, medico, trabalho, escola e gemeente. O foco e transformar linguagem basica em acao real, com audicao, pronuncia fisica, repeticao, shadowing e resposta oral.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nPessoa nativa fala em ritmo natural.\r\nAluno identifica palavras-chave e responde: Ik heb een afspraak op maandag.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- reconhecer vocabulario essencial em audio lento e natural\r\n- usar frases praticas em contexto real\r\n- treinar pronuncia pelo audio nativo\r\n- fazer shadowing por blocos\r\n- responder oralmente sem bloquear\r\n- completar exercicios escritos e auditivos\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk heb een afspraak op maandag.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk heb een afspraak op maandag.\r\nWelke dag is het?\r\nVandaag is het vrijdag.\r\nKunt u de datum herhalen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `vandaag`\r\n\r\nTraducao PT: hoje  \r\nTraducao EN: today  \r\nAudio nativo: `audio/A0-06/words/vandaag.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vandaag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvandaag\r\nvandaag em bloco\r\nvandaag em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `vandaag` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vandaag` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `morgen`\r\n\r\nTraducao PT: amanha  \r\nTraducao EN: tomorrow  \r\nAudio nativo: `audio/A0-06/words/morgen.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `morgen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmorgen\r\nmorgen em bloco\r\nmorgen em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `morgen` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `morgen` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `maandag`\r\n\r\nTraducao PT: segunda-feira  \r\nTraducao EN: Monday  \r\nAudio nativo: `audio/A0-06/words/maandag.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `maandag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmaandag\r\nmaandag em bloco\r\nmaandag em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `maandag` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `maandag` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `week`\r\n\r\nTraducao PT: semana  \r\nTraducao EN: week  \r\nAudio nativo: `audio/A0-06/words/week.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `week`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nweek\r\nweek em bloco\r\nweek em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `week` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `week` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `maand`\r\n\r\nTraducao PT: mes  \r\nTraducao EN: month  \r\nAudio nativo: `audio/A0-06/words/maand.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `maand`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmaand\r\nmaand em bloco\r\nmaand em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `maand` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `maand` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `afspraak`\r\n\r\nTraducao PT: marcacao  \r\nTraducao EN: appointment  \r\nAudio nativo: `audio/A0-06/words/afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspraak\r\nafspraak em bloco\r\nafspraak em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `afspraak` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspraak` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-06';
