insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A0-07', 'Frases de sobrevivencia', 'reconhecer vocabulario essencial em audio lento e natural', 6, 'published', 35
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A0'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar e ajustar a fala ate se aproximar do neerlandes natural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Esta licao prepara o aluno para lojas, transportes, trabalho, telefone, medico e gemeente. O foco e transformar linguagem basica em acao real, com audicao, pronuncia fisica, repeticao, shadowing e resposta oral.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nPessoa nativa fala em ritmo natural.\r\nAluno identifica palavras-chave e responde: Sorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- reconhecer vocabulario essencial em audio lento e natural\r\n- usar frases praticas em contexto real\r\n- treinar pronuncia pelo audio nativo\r\n- fazer shadowing por blocos\r\n- responder oralmente sem bloquear\r\n- completar exercicios escritos e auditivos\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nSorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nKunt u mij helpen?\r\nIk begrijp het niet.\r\nKunt u langzaam spreken?\r\nIk heb hulp nodig.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `alstublieft`\r\n\r\nTraducao PT: por favor / aqui tem  \r\nTraducao EN: please / here you are  \r\nAudio nativo: `audio/A0-07/words/alstublieft.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `alstublieft`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nalstublieft\r\nalstublieft em bloco\r\nalstublieft em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `alstublieft` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `alstublieft` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `sorry`\r\n\r\nTraducao PT: desculpe  \r\nTraducao EN: sorry  \r\nAudio nativo: `audio/A0-07/words/sorry.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `sorry`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nsorry\r\nsorry em bloco\r\nsorry em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `sorry` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `sorry` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `langzaam`\r\n\r\nTraducao PT: devagar  \r\nTraducao EN: slowly  \r\nAudio nativo: `audio/A0-07/words/langzaam.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `langzaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nlangzaam\r\nlangzaam em bloco\r\nlangzaam em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `langzaam` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `langzaam` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `helpen`\r\n\r\nTraducao PT: ajudar  \r\nTraducao EN: help  \r\nAudio nativo: `audio/A0-07/words/helpen.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `helpen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhelpen\r\nhelpen em bloco\r\nhelpen em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `helpen` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `helpen` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `wachten`\r\n\r\nTraducao PT: esperar  \r\nTraducao EN: wait  \r\nAudio nativo: `audio/A0-07/words/wachten.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `wachten`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwachten\r\nwachten em bloco\r\nwachten em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `wachten` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `wachten` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `nodig`\r\n\r\nTraducao PT: necessario  \r\nTraducao EN: needed  \r\nAudio nativo: `audio/A0-07/words/nodig.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `nodig`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnodig\r\nnodig em bloco\r\nnodig em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `nodig` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `nodig` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"`hebben`, `begrijpen`, `kunnen`, `spreken` aparecem em frases praticas. O aluno aprende uso real antes de tabelas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Gramatica minima: `Sujeito + verbo + informacao` e perguntas formais com `Kunt u + verbo...?`. O objetivo A0 e compreender e responder, nao explicar regras longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Kunt u mij helpen?`\r\n\r\nTraducao PT: Pode ajudar-me?  \r\nTraducao EN: Can you help me?  \r\nAudio nativo: `audio/A0-07/phrases/kunt-u-mij-helpen.native.nl.mp3`\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nRitmo:\r\n\r\nTreinar primeiro por blocos, depois frase inteira. A palavra-chave recebe mais energia; palavras funcionais podem ficar mais leves em fala natural.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u mij helpen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir palavra por palavra e perder ritmo.\r\n- EN: usar ritmo ingles e alongar vogais.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u mij helpen?\r\nKunt u mij helpen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Gravar a propria voz e comparar ritmo, finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escolhe a frase ouvida entre tres opcoes, identifica palavras-chave e depois completa uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio lento e natural e consegue usa-la no roleplay sem ler.\r\n\r\n### Frase 2\r\n\r\nFrase: `Ik begrijp het niet.`\r\n\r\nTraducao PT: Nao entendo.  \r\nTraducao EN: I do not understand it.  \r\nAudio nativo: `audio/A0-07/phrases/ik-begrijp-het-niet.native.nl.mp3`\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk begrijp het niet.\r\n```\r\n\r\nRitmo:\r\n\r\nTreinar primeiro por blocos, depois frase inteira. A palavra-chave recebe mais energia; palavras funcionais podem ficar mais leves em fala natural.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk begrijp het niet.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk begrijp het niet.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIk begrijp ''t niet.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik begrijp het niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir palavra por palavra e perder ritmo.\r\n- EN: usar ritmo ingles e alongar vogais.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk begrijp het niet.\r\nIk begrijp het niet.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Gravar a propria voz e comparar ritmo, finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escolhe a frase ouvida entre tres opcoes, identifica palavras-chave e depois completa uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio lento e natural e consegue usa-la no roleplay sem ler.\r\n\r\n### Frase 3\r\n\r\nFrase: `Kunt u langzaam spreken?`\r\n\r\nTraducao PT: Pode falar devagar?  \r\nTraducao EN: Can you speak slowly?  \r\nAudio nativo: `audio/A0-07/phrases/kunt-u-langzaam-spreken.native.nl.mp3`\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nRitmo:\r\n\r\nTreinar primeiro por blocos, depois frase inteira. A palavra-chave recebe mais energia; palavras funcionais podem ficar mais leves em fala natural.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u langzaam spreken?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir palavra por palavra e perder ritmo.\r\n- EN: usar ritmo ingles e alongar vogais.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\nKunt u langzaam spreken?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Gravar a propria voz e comparar ritmo, finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escolhe a frase ouvida entre tres opcoes, identifica palavras-chave e depois completa uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio lento e natural e consegue usa-la no roleplay sem ler.\r\n\r\n### Frase 4\r\n\r\nFrase: `Ik heb hulp nodig.`\r\n\r\nTraducao PT: Preciso de ajuda.  \r\nTraducao EN: I need help.  \r\nAudio nativo: `audio/A0-07/phrases/ik-heb-hulp-nodig.native.nl.mp3`\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk heb hulp nodig.\r\n```\r\n\r\nRitmo:\r\n\r\nTreinar primeiro por blocos, depois frase inteira. A palavra-chave recebe mais energia; palavras funcionais podem ficar mais leves em fala natural.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk heb hulp nodig.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk heb hulp nodig.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIk heb hulp nodig.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik heb hulp nodig.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir palavra por palavra e perder ritmo.\r\n- EN: usar ritmo ingles e alongar vogais.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk heb hulp nodig.\r\nIk heb hulp nodig.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Gravar a propria voz e comparar ritmo, finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escolhe a frase ouvida entre tres opcoes, identifica palavras-chave e depois completa uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio lento e natural e consegue usa-la no roleplay sem ler."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases.\r\n- Confirmar vogais longas, curtas e ditongos com audio nativo.\r\n- Nao transformar `u` em you nem `ij` em mine forte."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda significado e naturalidade.\r\n\r\n### Sons de garganta quando aparecem\r\n\r\nUsar friccao leve atras da boca, sem dor e sem transformar em `r` portugues.\r\n\r\n### Reducoes naturais\r\n\r\nSo usar depois de entender a forma lenta. Primeiro clareza, depois velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui` quando aparecer.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina em tres camadas: palavra isolada, bloco sonoro e frase natural. Em perguntas, a entoacao sobe ligeiramente. Em respostas, a entoacao desce e fecha."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nKunt u mij helpen?\r\nIk begrijp het niet.\r\nKunt u langzaam spreken?\r\nIk heb hulp nodig.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: falar cada palavra claramente.\r\nNatural: juntar blocos frequentes.\r\nReduzida: aceitar reducoes como ''t e ''n quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra em bloco.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n\r\n```text\r\nSorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto.\r\n7. Gravar e comparar com audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar frase.\r\n4. Escrever uma resposta curta para situacao real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Mini roleplay com dados ficticios."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Kunt u mij helpen?\r\nAluno: Sorry, ik begrijp het niet. Kunt u dat herhalen?\r\nPessoa: Ik begrijp het niet.\r\nAluno: Dank u wel.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Que frase foi usada para pedir ajuda?\r\n- Que palavra-chave indica o tema da licao?\r\n- O aluno conseguiu manter a interacao?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Servico publico\r\n\r\nO aluno usa as frases da licao com funcionario formal.\r\n\r\n### Roleplay 2 - Loja ou telefone\r\n\r\nO aluno reconhece palavras-chave, pede repeticao e responde.\r\n\r\n### Roleplay 3 - Vida diaria\r\n\r\nO aluno aplica a frase final de sobrevivencia sem ler."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Bloquear em vez de pedir repeticao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. O aluno deve fazer shadowing?\r\n\r\n```text\r\nA. Sim\r\nB. Nao\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender, o aluno deve:\r\n\r\n```text\r\nA. bloquear\r\nB. pedir repeticao ou ajuda\r\nC. fingir que entendeu\r\n```\r\n\r\nResposta: B\r\n\r\n5. A frase final deve ser usada em:\r\n\r\n```text\r\nA. roleplay oral\r\nB. apenas leitura\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nalstublieft - por favor / aqui tem - please / here you are\r\nsorry - desculpe - sorry\r\nlangzaam - devagar - slowly\r\nhelpen - ajudar - help\r\nwachten - esperar - wait\r\nnodig - necessario - needed\r\nKunt u mij helpen? - Pode ajudar-me? - Can you help me?\r\nIk begrijp het niet. - Nao entendo. - I do not understand it.\r\nKunt u langzaam spreken? - Pode falar devagar? - Can you speak slowly?\r\nIk heb hulp nodig. - Preciso de ajuda. - I need help.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- gravar a resposta oral final"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a frase final em contexto real\r\n- fazer shadowing de pelo menos 3 frases\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nSorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'alstublieft', 'por favor / aqui tem', 'please / here you are', 'Na palavra `alstublieft`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 1 from lessons l where l.code = 'A0-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'sorry', 'desculpe', 'sorry', 'Na palavra `sorry`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 2 from lessons l where l.code = 'A0-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'langzaam', 'devagar', 'slowly', 'Na palavra `langzaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 3 from lessons l where l.code = 'A0-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'helpen', 'ajudar', 'help', 'Na palavra `helpen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 4 from lessons l where l.code = 'A0-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'wachten', 'esperar', 'wait', 'Na palavra `wachten`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 5 from lessons l where l.code = 'A0-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'nodig', 'necessario', 'needed', 'Na palavra `nodig`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 6 from lessons l where l.code = 'A0-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u mij helpen?', 'Pode ajudar-me?', 'Can you help me?', 'Kunt u mij helpen?', 'Kunt u mij helpen?', 'Kunt u mij helpen?', 'Kunt u mij helpen?', 'Na frase `Kunt u mij helpen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A0-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik begrijp het niet.', 'Nao entendo.', 'I do not understand it.', 'Ik begrijp het niet.', 'Ik begrijp het niet.', 'Ik begrijp het niet.', 'Ik begrijp ''t niet.', 'Na frase `Ik begrijp het niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A0-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u langzaam spreken?', 'Pode falar devagar?', 'Can you speak slowly?', 'Kunt u langzaam spreken?', 'Kunt u langzaam spreken?', 'Kunt u langzaam spreken?', 'Kunt u langzaam spreken?', 'Na frase `Kunt u langzaam spreken?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A0-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik heb hulp nodig.', 'Preciso de ajuda.', 'I need help.', 'Ik heb hulp nodig.', 'Ik heb hulp nodig.', 'Ik heb hulp nodig.', 'Ik heb hulp nodig.', 'Na frase `Ik heb hulp nodig.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A0-07';
