insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-04', 'Presente regular', 'entender raiz verbal', 3, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"O aluno precisa falar do que faz agora: trabalhar, morar, falar, aprender, pagar, comprar. O presente regular permite criar centenas de frases reais sem memorizar apenas expressoes.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nCollega: Waar werkt u?\r\nAluno: Ik werk in Rotterdam. Ik leer Nederlands.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- entender raiz verbal\r\n- usar `ik werk`, `u werkt`, `hij werkt`\r\n- distinguir infinitivo e presente\r\n- falar de trabalho e estudo\r\n- reconhecer `t` final em fala\r\n- criar frases A1 novas\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk werk vandaag. Ik leer Nederlands. Ik betaal met pin.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk werk vandaag.\r\nU werkt morgen.\r\nHij leert Nederlands.\r\nWij wonen in Utrecht.\r\nIk betaal met pin.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `werken`\r\n\r\nTraducao PT: trabalhar  \r\nTraducao EN: to work  \r\nAudio nativo: `audio/A1-04/words/werken.native.nl.mp3`  \r\nAproximacao inicial PT: `WER-kuh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `werken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer verken com v forte.\r\n- EN: dizer working.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk werk vandaag.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwerken\r\nwerken em bloco\r\nIk werk vandaag.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `werken` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `werken` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `leren`\r\n\r\nTraducao PT: aprender  \r\nTraducao EN: to learn  \r\nAudio nativo: `audio/A1-04/words/leren.native.nl.mp3`  \r\nAproximacao inicial PT: `LE-ren`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `leren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ler em portugues.\r\n- EN: dizer learn.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk leer Nederlands.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nleren\r\nleren em bloco\r\nIk leer Nederlands.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `leren` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `leren` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `wonen`\r\n\r\nTraducao PT: morar/viver  \r\nTraducao EN: to live  \r\nAudio nativo: `audio/A1-04/words/wonen.native.nl.mp3`  \r\nAproximacao inicial PT: `VOO-nuh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `wonen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer vonen.\r\n- EN: dizer won.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk woon hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwonen\r\nwonen em bloco\r\nIk woon hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `wonen` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `wonen` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `betalen`\r\n\r\nTraducao PT: pagar  \r\nTraducao EN: to pay  \r\nAudio nativo: `audio/A1-04/words/betalen.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-TAA-len`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `betalen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer betalen como portugues.\r\n- EN: dizer pay.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk betaal met pin.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbetalen\r\nbetalen em bloco\r\nIk betaal met pin.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `betalen` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `betalen` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `kopen`\r\n\r\nTraducao PT: comprar  \r\nTraducao EN: to buy  \r\nAudio nativo: `audio/A1-04/words/kopen.native.nl.mp3`  \r\nAproximacao inicial PT: `KOO-pen`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kopen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer copem.\r\n- EN: dizer cope.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk koop brood.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkopen\r\nkopen em bloco\r\nIk koop brood.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kopen` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kopen` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `maken`\r\n\r\nTraducao PT: fazer/criar  \r\nTraducao EN: to make  \r\nAudio nativo: `audio/A1-04/words/maken.native.nl.mp3`  \r\nAproximacao inicial PT: `MAA-ken`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `maken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer maken com e final forte.\r\n- EN: dizer make.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk maak koffie.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmaken\r\nmaken em bloco\r\nIk maak koffie.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `maken` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `maken` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `luisteren`\r\n\r\nTraducao PT: ouvir/escutar  \r\nTraducao EN: to listen  \r\nAudio nativo: `audio/A1-04/words/luisteren.native.nl.mp3`  \r\nAproximacao inicial PT: `LUI-ster-en`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `luisteren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer loister.\r\n- EN: dizer listen.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk luister naar audio.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nluisteren\r\nluisteren em bloco\r\nIk luister naar audio.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `luisteren` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `luisteren` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `herhalen`\r\n\r\nTraducao PT: repetir  \r\nTraducao EN: to repeat  \r\nAudio nativo: `audio/A1-04/words/herhalen.native.nl.mp3`  \r\nAproximacao inicial PT: `her-HAA-len`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `herhalen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: dizer repeat.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk herhaal de zin.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nherhalen\r\nherhalen em bloco\r\nIk herhaal de zin.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `herhalen` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `herhalen` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em frases reais. O aluno treina primeiro reconhecimento auditivo, depois producao oral, e so depois variacao escrita."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Presente regular basico: infinitivo `werken`; raiz `werk`; `ik werk`; `jij/u/hij/zij werkt`; `wij/jullie/zij werken`. O foco e uso oral e reconhecimento do `t` final, nao teoria completa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik werk vandaag.`\r\n\r\nTraducao PT: Eu trabalho hoje.  \r\nTraducao EN: I work today.  \r\nAudio nativo: `audio/A1-04/phrases/ik-werk-vandaag.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nFalar do dia.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk werk / vandaag.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk werk vandaag.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk werk vandaag.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Werk vandaag.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik werk vandaag.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer werke.\r\n- EN: dizer work today.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk werk / vandaag.\r\nIk werk vandaag.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 2\r\n\r\nFrase: `U werkt morgen.`\r\n\r\nTraducao PT: O senhor trabalha amanha.  \r\nTraducao EN: You work tomorrow.  \r\nAudio nativo: `audio/A1-04/phrases/u-werkt-morgen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPergunta/resposta formal.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nU werkt / morgen.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nU werkt morgen.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nU werkt morgen.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nU werkt morgen.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `U werkt morgen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: perder t final.\r\n- EN: usar you.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nU werkt / morgen.\r\nU werkt morgen.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 3\r\n\r\nFrase: `Hij leert Nederlands.`\r\n\r\nTraducao PT: Ele aprende neerlandes.  \r\nTraducao EN: He learns Dutch.  \r\nAudio nativo: `audio/A1-04/phrases/hij-leert-nederlands.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nFalar de outra pessoa.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nHij leert / Nederlands.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nHij leert Nederlands.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nHij leert Nederlands.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nHij leert Nederlands.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Hij leert Nederlands.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: dizer learns Dutch rhythm.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nHij leert / Nederlands.\r\nHij leert Nederlands.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 4\r\n\r\nFrase: `Wij wonen in Utrecht.`\r\n\r\nTraducao PT: Nos moramos em Utrecht.  \r\nTraducao EN: We live in Utrecht.  \r\nAudio nativo: `audio/A1-04/phrases/wij-wonen-in-utrecht.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDizer morada/cidade.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWij wonen / in Utrecht.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWij wonen in Utrecht.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWe wonen in Utrecht.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWe wonen in Utrecht.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Wij wonen in Utrecht.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer utrecht portugues.\r\n- EN: dizer we live.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWij wonen / in Utrecht.\r\nWij wonen in Utrecht.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 5\r\n\r\nFrase: `Ik betaal met pin.`\r\n\r\nTraducao PT: Eu pago com cartao.  \r\nTraducao EN: I pay by card.  \r\nAudio nativo: `audio/A1-04/phrases/ik-betaal-met-pin.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nCompras.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk betaal / met pin.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk betaal met pin.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk betaal met pin.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Betaal met pin.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik betaal met pin.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer betale.\r\n- EN: dizer pay by pin em ingles.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk betaal / met pin.\r\nIk betaal met pin.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter vogais longas e curtas diferentes.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar palavras neerlandesas em cognatos ingleses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto e essencial para o aluno ser entendido.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e, as vezes, significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`. O aluno deve reconhecer antes de tentar usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Perguntas sobem ligeiramente; respostas descem e fecham."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk werk / vandaag.\r\nU werkt / morgen.\r\nHij leert / Nederlands.\r\nWij wonen / in Utrecht.\r\nIk betaal / met pin.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes.\r\nReduzida: reconhecer ''t, ''n, ''k e ligacoes quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n\r\n```text\r\nIk werk vandaag. Ik leer Nederlands. Ik betaal met pin.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder com informacao propria.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: apresentar-se, pedir ajuda, confirmar informacao, comprar, falar de familia ou pedir direcao.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Substituir uma informacao por dados pessoais.\r\n5. Escrever uma resposta curta para uma situacao real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Ik werk vandaag.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: U werkt morgen.\r\nAluno: Dank u wel. Ik werk vandaag. Ik leer Nederlands. Ik betaal met pin.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi a primeira pergunta ou frase principal?\r\n- Que informacao o aluno conseguiu dar?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno responde a uma pessoa da gemeente, medico, escola ou trabalho usando as frases da licao.\r\n\r\n### Roleplay 2 - Contexto informal\r\n\r\nO aluno responde a colega, vizinho ou colega de curso usando forma simples e natural.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno nao entende a primeira vez, pede repeticao e completa a tarefa comunicativa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Bloquear em vez de pedir repeticao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. O aluno deve fazer shadowing?\r\n\r\n```text\r\nA. Sim\r\nB. Nao\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender, o aluno deve:\r\n\r\n```text\r\nA. bloquear\r\nB. pedir repeticao ou ajuda\r\nC. fingir que entendeu\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nwerken - trabalhar - to work\r\nleren - aprender - to learn\r\nwonen - morar/viver - to live\r\nbetalen - pagar - to pay\r\nkopen - comprar - to buy\r\nmaken - fazer/criar - to make\r\nluisteren - ouvir/escutar - to listen\r\nherhalen - repetir - to repeat\r\nIk werk vandaag. - Eu trabalho hoje. - I work today.\r\nU werkt morgen. - O senhor trabalha amanha. - You work tomorrow.\r\nHij leert Nederlands. - Ele aprende neerlandes. - He learns Dutch.\r\nWij wonen in Utrecht. - Nos moramos em Utrecht. - We live in Utrecht.\r\nIk betaal met pin. - Eu pago com cartao. - I pay by card.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- gravar a resposta oral final\r\n- responder a uma pergunta nova com a mesma estrutura"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta e natural\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk werk vandaag. Ik leer Nederlands. Ik betaal met pin.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'werken', 'trabalhar', 'to work', 'Na palavra `werken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik werk vandaag.', 1 from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'leren', 'aprender', 'to learn', 'Na palavra `leren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik leer Nederlands.', 2 from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'wonen', 'morar/viver', 'to live', 'Na palavra `wonen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik woon hier.', 3 from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'betalen', 'pagar', 'to pay', 'Na palavra `betalen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik betaal met pin.', 4 from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'kopen', 'comprar', 'to buy', 'Na palavra `kopen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik koop brood.', 5 from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'maken', 'fazer/criar', 'to make', 'Na palavra `maken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik maak koffie.', 6 from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'luisteren', 'ouvir/escutar', 'to listen', 'Na palavra `luisteren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik luister naar audio.', 7 from lessons l where l.code = 'A1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'herhalen', 'repetir', 'to repeat', 'Na palavra `herhalen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik herhaal de zin.', 8 from lessons l where l.code = 'A1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik werk vandaag.', 'Eu trabalho hoje.', 'I work today.', 'Ik werk / vandaag.', 'Ik werk vandaag.', 'Ik werk vandaag.', '''k Werk vandaag.', 'Na frase `Ik werk vandaag.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'U werkt morgen.', 'O senhor trabalha amanha.', 'You work tomorrow.', 'U werkt / morgen.', 'U werkt morgen.', 'U werkt morgen.', 'U werkt morgen.', 'Na frase `U werkt morgen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Hij leert Nederlands.', 'Ele aprende neerlandes.', 'He learns Dutch.', 'Hij leert / Nederlands.', 'Hij leert Nederlands.', 'Hij leert Nederlands.', 'Hij leert Nederlands.', 'Na frase `Hij leert Nederlands.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Wij wonen in Utrecht.', 'Nos moramos em Utrecht.', 'We live in Utrecht.', 'Wij wonen / in Utrecht.', 'Wij wonen in Utrecht.', 'We wonen in Utrecht.', 'We wonen in Utrecht.', 'Na frase `Wij wonen in Utrecht.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik betaal met pin.', 'Eu pago com cartao.', 'I pay by card.', 'Ik betaal / met pin.', 'Ik betaal met pin.', 'Ik betaal met pin.', '''k Betaal met pin.', 'Na frase `Ik betaal met pin.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A1-04';
