select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`Zijn`: ik ben, jij/u bent, hij/zij is, wij zijn. `Hebben`: ik heb, jij/u heeft/hebt, hij/zij heeft, wij hebben. A1 aprende primeiro as formas mais uteis em frases reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-05';
