insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-06', 'Familia e relacoes', 'nomear membros da familia', 5, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Familia aparece em escola, medico, gemeente, trabalho, seguros e conversas sociais. O aluno aprende a falar de pessoas proximas com frases simples.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nCollega: Heeft u familie hier?\r\nAluno: Ja, mijn vrouw woont hier. Mijn kinderen zijn op school.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- nomear membros da familia\r\n- usar `mijn` e `uw`\r\n- dizer estado familiar basico\r\n- responder perguntas simples\r\n- usar singular/plural basico\r\n- falar de familia em contexto formal\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nMijn familie woont hier. Mijn kinderen zijn op school.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nMijn vrouw woont hier.\r\nMijn kinderen zijn op school.\r\nHeeft u familie hier?\r\nMijn moeder woont in Portugal.\r\nIk ben getrouwd.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `familie`\r\n\r\nTraducao PT: familia  \r\nTraducao EN: family  \r\nAudio nativo: `audio/A1-06/words/familie.native.nl.mp3`  \r\nAproximacao inicial PT: `fa-MI-li`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `familie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer familia portugues.\r\n- EN: dizer family.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn familie woont hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nfamilie\r\nfamilie em bloco\r\nMijn familie woont hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `familie` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `familie` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `vrouw`\r\n\r\nTraducao PT: mulher/esposa  \r\nTraducao EN: wife/woman  \r\nAudio nativo: `audio/A1-06/words/vrouw.native.nl.mp3`  \r\nAproximacao inicial PT: `vrau`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vrouw`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer vrou.\r\n- EN: dizer vrow/row.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn vrouw is Nederlands.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvrouw\r\nvrouw em bloco\r\nMijn vrouw is Nederlands.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `vrouw` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vrouw` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `man`\r\n\r\nTraducao PT: homem/marido  \r\nTraducao EN: man/husband  \r\nAudio nativo: `audio/A1-06/words/man.native.nl.mp3`  \r\nAproximacao inicial PT: `man`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `man`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer mane.\r\n- EN: alongar.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn man werkt.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nman\r\nman em bloco\r\nMijn man werkt.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `man` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `man` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `kind`\r\n\r\nTraducao PT: crianca/filho  \r\nTraducao EN: child  \r\nAudio nativo: `audio/A1-06/words/kind.native.nl.mp3`  \r\nAproximacao inicial PT: `kint`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kind`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer kinde.\r\n- EN: dizer kind ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn kind is thuis.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkind\r\nkind em bloco\r\nMijn kind is thuis.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kind` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kind` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `kinderen`\r\n\r\nTraducao PT: criancas/filhos  \r\nTraducao EN: children  \r\nAudio nativo: `audio/A1-06/words/kinderen.native.nl.mp3`  \r\nAproximacao inicial PT: `KIN-duh-ruh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kinderen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer kinderen como portugues.\r\n- EN: dizer children.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn kinderen zijn op school.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkinderen\r\nkinderen em bloco\r\nMijn kinderen zijn op school.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kinderen` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kinderen` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `moeder`\r\n\r\nTraducao PT: mae  \r\nTraducao EN: mother  \r\nAudio nativo: `audio/A1-06/words/moeder.native.nl.mp3`  \r\nAproximacao inicial PT: `MU-der`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `moeder`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer moder.\r\n- EN: dizer mother.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn moeder woont in Portugal.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmoeder\r\nmoeder em bloco\r\nMijn moeder woont in Portugal.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `moeder` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `moeder` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `vader`\r\n\r\nTraducao PT: pai  \r\nTraducao EN: father  \r\nAudio nativo: `audio/A1-06/words/vader.native.nl.mp3`  \r\nAproximacao inicial PT: `VAA-der`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vader`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer vader portugues.\r\n- EN: dizer vader Star Wars.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn vader is thuis.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvader\r\nvader em bloco\r\nMijn vader is thuis.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `vader` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vader` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `partner`\r\n\r\nTraducao PT: companheiro/a  \r\nTraducao EN: partner  \r\nAudio nativo: `audio/A1-06/words/partner.native.nl.mp3`  \r\nAproximacao inicial PT: `PART-ner`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `partner`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer partner portugues.\r\n- EN: usar ingles forte.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn partner werkt vandaag.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\npartner\r\npartner em bloco\r\nMijn partner werkt vandaag.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `partner` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `partner` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em frases reais. O aluno treina primeiro reconhecimento auditivo, depois producao oral, e so depois variacao escrita."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Possessivos basicos: `mijn` meu/minha, `uw` seu/sua formal. Plural lexical em palavras frequentes: `kind` -> `kinderen`. O foco e comunicar, nao todas as regras de plural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Mijn vrouw woont hier.`\r\n\r\nTraducao PT: A minha esposa vive aqui.  \r\nTraducao EN: My wife lives here.  \r\nAudio nativo: `audio/A1-06/phrases/mijn-vrouw-woont-hier.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nFalar da esposa.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMijn vrouw / woont hier.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMijn vrouw woont hier.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nMijn vrouw woont hier.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nM''n vrouw woont hier.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Mijn vrouw woont hier.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer vrou.\r\n- EN: dizer wife lives rhythm.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMijn vrouw / woont hier.\r\nMijn vrouw woont hier.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 2\r\n\r\nFrase: `Mijn kinderen zijn op school.`\r\n\r\nTraducao PT: Os meus filhos estao na escola.  \r\nTraducao EN: My children are at school.  \r\nAudio nativo: `audio/A1-06/phrases/mijn-kinderen-zijn-op-school.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nEscola/vida diaria.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMijn kinderen / zijn op school.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMijn kinderen zijn op school.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nM''n kinderen zijn op school.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nM''n kinderen zijn op school.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Mijn kinderen zijn op school.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer kinders.\r\n- EN: dizer children.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMijn kinderen / zijn op school.\r\nMijn kinderen zijn op school.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 3\r\n\r\nFrase: `Heeft u familie hier?`\r\n\r\nTraducao PT: Tem familia aqui?  \r\nTraducao EN: Do you have family here?  \r\nAudio nativo: `audio/A1-06/phrases/heeft-u-familie-hier.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPergunta social/formal.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nHeeft u / familie hier?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nHeeft u familie hier?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nHeeftu familie hier?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nHeeft u familie hier?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Heeft u familie hier?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: usar you.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nHeeft u / familie hier?\r\nHeeft u familie hier?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 4\r\n\r\nFrase: `Mijn moeder woont in Portugal.`\r\n\r\nTraducao PT: A minha mae vive em Portugal.  \r\nTraducao EN: My mother lives in Portugal.  \r\nAudio nativo: `audio/A1-06/phrases/mijn-moeder-woont-in-portugal.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nFalar de familia longe.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMijn moeder / woont in Portugal.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMijn moeder woont in Portugal.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nM''n moeder woont in Portugal.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nM''n moeder woont in Portugal.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Mijn moeder woont in Portugal.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer mother.\r\n- EN: dizer mother lives.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMijn moeder / woont in Portugal.\r\nMijn moeder woont in Portugal.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 5\r\n\r\nFrase: `Ik ben getrouwd.`\r\n\r\nTraducao PT: Sou casado/a.  \r\nTraducao EN: I am married.  \r\nAudio nativo: `audio/A1-06/phrases/ik-ben-getrouwd.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nEstado civil.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ben / getrouwd.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ben getrouwd.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ben getrouwd.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ben getrouwd.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ben getrouwd.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer getroud sem g.\r\n- EN: dizer married.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ben / getrouwd.\r\nIk ben getrouwd.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter vogais longas e curtas diferentes.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar palavras neerlandesas em cognatos ingleses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto e essencial para o aluno ser entendido.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e, as vezes, significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`. O aluno deve reconhecer antes de tentar usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Perguntas sobem ligeiramente; respostas descem e fecham."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nMijn vrouw / woont hier.\r\nMijn kinderen / zijn op school.\r\nHeeft u / familie hier?\r\nMijn moeder / woont in Portugal.\r\nIk ben / getrouwd.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes.\r\nReduzida: reconhecer ''t, ''n, ''k e ligacoes quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n\r\n```text\r\nMijn familie woont hier. Mijn kinderen zijn op school.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder com informacao propria.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: apresentar-se, pedir ajuda, confirmar informacao, comprar, falar de familia ou pedir direcao.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Substituir uma informacao por dados pessoais.\r\n5. Escrever uma resposta curta para uma situacao real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Mijn vrouw woont hier.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Mijn kinderen zijn op school.\r\nAluno: Dank u wel. Mijn familie woont hier. Mijn kinderen zijn op school.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi a primeira pergunta ou frase principal?\r\n- Que informacao o aluno conseguiu dar?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno responde a uma pessoa da gemeente, medico, escola ou trabalho usando as frases da licao.\r\n\r\n### Roleplay 2 - Contexto informal\r\n\r\nO aluno responde a colega, vizinho ou colega de curso usando forma simples e natural.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno nao entende a primeira vez, pede repeticao e completa a tarefa comunicativa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Bloquear em vez de pedir repeticao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. O aluno deve fazer shadowing?\r\n\r\n```text\r\nA. Sim\r\nB. Nao\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender, o aluno deve:\r\n\r\n```text\r\nA. bloquear\r\nB. pedir repeticao ou ajuda\r\nC. fingir que entendeu\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nfamilie - familia - family\r\nvrouw - mulher/esposa - wife/woman\r\nman - homem/marido - man/husband\r\nkind - crianca/filho - child\r\nkinderen - criancas/filhos - children\r\nmoeder - mae - mother\r\nvader - pai - father\r\npartner - companheiro/a - partner\r\nMijn vrouw woont hier. - A minha esposa vive aqui. - My wife lives here.\r\nMijn kinderen zijn op school. - Os meus filhos estao na escola. - My children are at school.\r\nHeeft u familie hier? - Tem familia aqui? - Do you have family here?\r\nMijn moeder woont in Portugal. - A minha mae vive em Portugal. - My mother lives in Portugal.\r\nIk ben getrouwd. - Sou casado/a. - I am married.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- gravar a resposta oral final\r\n- responder a uma pergunta nova com a mesma estrutura"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta e natural\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nMijn familie woont hier. Mijn kinderen zijn op school.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'familie', 'familia', 'family', 'Na palavra `familie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn familie woont hier.', 1 from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'vrouw', 'mulher/esposa', 'wife/woman', 'Na palavra `vrouw`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn vrouw is Nederlands.', 2 from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'man', 'homem/marido', 'man/husband', 'Na palavra `man`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn man werkt.', 3 from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'kind', 'crianca/filho', 'child', 'Na palavra `kind`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn kind is thuis.', 4 from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'kinderen', 'criancas/filhos', 'children', 'Na palavra `kinderen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn kinderen zijn op school.', 5 from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'moeder', 'mae', 'mother', 'Na palavra `moeder`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn moeder woont in Portugal.', 6 from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'vader', 'pai', 'father', 'Na palavra `vader`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn vader is thuis.', 7 from lessons l where l.code = 'A1-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'partner', 'companheiro/a', 'partner', 'Na palavra `partner`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn partner werkt vandaag.', 8 from lessons l where l.code = 'A1-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Mijn vrouw woont hier.', 'A minha esposa vive aqui.', 'My wife lives here.', 'Mijn vrouw / woont hier.', 'Mijn vrouw woont hier.', 'Mijn vrouw woont hier.', 'M''n vrouw woont hier.', 'Na frase `Mijn vrouw woont hier.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A1-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Mijn kinderen zijn op school.', 'Os meus filhos estao na escola.', 'My children are at school.', 'Mijn kinderen / zijn op school.', 'Mijn kinderen zijn op school.', 'M''n kinderen zijn op school.', 'M''n kinderen zijn op school.', 'Na frase `Mijn kinderen zijn op school.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A1-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Heeft u familie hier?', 'Tem familia aqui?', 'Do you have family here?', 'Heeft u / familie hier?', 'Heeft u familie hier?', 'Heeftu familie hier?', 'Heeft u familie hier?', 'Na frase `Heeft u familie hier?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A1-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Mijn moeder woont in Portugal.', 'A minha mae vive em Portugal.', 'My mother lives in Portugal.', 'Mijn moeder / woont in Portugal.', 'Mijn moeder woont in Portugal.', 'M''n moeder woont in Portugal.', 'M''n moeder woont in Portugal.', 'Na frase `Mijn moeder woont in Portugal.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A1-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ben getrouwd.', 'Sou casado/a.', 'I am married.', 'Ik ben / getrouwd.', 'Ik ben getrouwd.', 'Ik ben getrouwd.', '''k Ben getrouwd.', 'Na frase `Ik ben getrouwd.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A1-06';
