insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-07', 'Casa e rotina', 'dizer onde mora', 6, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Rotina e casa aparecem em conversas com vizinhos, trabalho, escola, medico e servicos. O aluno aprende a dizer onde vive e o que faz num dia normal.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nCollega: Waar woont u?\r\nAluno: Ik woon in Den Haag. Ik sta om zeven uur op.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- dizer onde mora\r\n- nomear partes basicas da casa\r\n- falar de rotina\r\n- usar horas simples\r\n- usar `om` para hora\r\n- descrever um dia normal\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk woon in Den Haag. Ik sta om zeven uur op. Ik ben thuis.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk woon in Den Haag.\r\nIk sta om zeven uur op.\r\nIk werk in de ochtend.\r\nIk ben in de avond thuis.\r\nDe kamer is schoon.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `huis`\r\n\r\nTraducao PT: casa  \r\nTraducao EN: house  \r\nAudio nativo: `audio/A1-07/words/huis.native.nl.mp3`  \r\nAproximacao inicial PT: `ui` audio-first  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `huis`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer raus.\r\n- EN: dizer house.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn huis is klein.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhuis\r\nhuis em bloco\r\nMijn huis is klein.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `huis` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `huis` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `kamer`\r\n\r\nTraducao PT: quarto/divisao  \r\nTraducao EN: room  \r\nAudio nativo: `audio/A1-07/words/kamer.native.nl.mp3`  \r\nAproximacao inicial PT: `KAA-mer`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kamer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer camera.\r\n- EN: dizer camera/room.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe kamer is groot.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkamer\r\nkamer em bloco\r\nDe kamer is groot.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kamer` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kamer` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `keuken`\r\n\r\nTraducao PT: cozinha  \r\nTraducao EN: kitchen  \r\nAudio nativo: `audio/A1-07/words/keuken.native.nl.mp3`  \r\nAproximacao inicial PT: `KUU-ken`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `keuken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer keuken portugues.\r\n- EN: dizer kitchen.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe keuken is schoon.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkeuken\r\nkeuken em bloco\r\nDe keuken is schoon.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `keuken` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `keuken` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `badkamer`\r\n\r\nTraducao PT: casa de banho  \r\nTraducao EN: bathroom  \r\nAudio nativo: `audio/A1-07/words/badkamer.native.nl.mp3`  \r\nAproximacao inicial PT: `BAT-kaa-mer`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `badkamer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer banheiro.\r\n- EN: dizer bathroom.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe badkamer is boven.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbadkamer\r\nbadkamer em bloco\r\nDe badkamer is boven.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `badkamer` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `badkamer` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `ochtend`\r\n\r\nTraducao PT: manha  \r\nTraducao EN: morning  \r\nAudio nativo: `audio/A1-07/words/ochtend.native.nl.mp3`  \r\nAproximacao inicial PT: `OKH-tent`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ochtend`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer octende.\r\n- EN: dizer morning.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIn de ochtend werk ik.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nochtend\r\nochtend em bloco\r\nIn de ochtend werk ik.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `ochtend` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `ochtend` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `avond`\r\n\r\nTraducao PT: noite/fim do dia  \r\nTraducao EN: evening  \r\nAudio nativo: `audio/A1-07/words/avond.native.nl.mp3`  \r\nAproximacao inicial PT: `AA-vont`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `avond`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer avondi.\r\n- EN: dizer evening.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIn de avond ben ik thuis.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\navond\r\navond em bloco\r\nIn de avond ben ik thuis.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `avond` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `avond` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `uur`\r\n\r\nTraducao PT: hora  \r\nTraducao EN: hour  \r\nAudio nativo: `audio/A1-07/words/uur.native.nl.mp3`  \r\nAproximacao inicial PT: `uur`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `uur`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ur portugues.\r\n- EN: dizer hour.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHet is zeven uur.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nuur\r\nuur em bloco\r\nHet is zeven uur.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `uur` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `uur` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `thuis`\r\n\r\nTraducao PT: em casa  \r\nTraducao EN: at home  \r\nAudio nativo: `audio/A1-07/words/thuis.native.nl.mp3`  \r\nAproximacao inicial PT: `tuis/ui` audio-first  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `thuis`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer tuis simples.\r\n- EN: dizer house.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben thuis.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nthuis\r\nthuis em bloco\r\nIk ben thuis.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `thuis` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `thuis` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em frases reais. O aluno treina primeiro reconhecimento auditivo, depois producao oral, e so depois variacao escrita."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`Ik woon in + cidade`. Para horas: `om zeven uur`. Verbos separaveis aparecem lexicalmente em A1: `opstaan` -> `Ik sta ... op`, sem aprofundar regra completa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik woon in Den Haag.`\r\n\r\nTraducao PT: Moro em Haia.  \r\nTraducao EN: I live in The Hague.  \r\nAudio nativo: `audio/A1-07/phrases/ik-woon-in-den-haag.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDizer cidade.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk woon / in Den Haag.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk woon in Den Haag.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk woon in Den Haag.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Woon in Den Haag.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik woon in Den Haag.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer von.\r\n- EN: dizer Hague em ingles.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk woon / in Den Haag.\r\nIk woon in Den Haag.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 2\r\n\r\nFrase: `Ik sta om zeven uur op.`\r\n\r\nTraducao PT: Levanto-me as sete horas.  \r\nTraducao EN: I get up at seven.  \r\nAudio nativo: `audio/A1-07/phrases/ik-sta-om-zeven-uur-op.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nRotina diaria.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk sta / om zeven uur / op.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk sta om zeven uur op.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk sta om zeven uur op.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Sta om zeven uur op.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik sta om zeven uur op.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: omitir op.\r\n- EN: usar get up order.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk sta / om zeven uur / op.\r\nIk sta om zeven uur op.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 3\r\n\r\nFrase: `Ik werk in de ochtend.`\r\n\r\nTraducao PT: Trabalho de manha.  \r\nTraducao EN: I work in the morning.  \r\nAudio nativo: `audio/A1-07/phrases/ik-werk-in-de-ochtend.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nHorario de trabalho.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk werk / in de ochtend.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk werk in de ochtend.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk werk in de ochtend.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Werk in de ochtend.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik werk in de ochtend.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer octende.\r\n- EN: dizer morning.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk werk / in de ochtend.\r\nIk werk in de ochtend.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 4\r\n\r\nFrase: `Ik ben in de avond thuis.`\r\n\r\nTraducao PT: Estou em casa a noite.  \r\nTraducao EN: I am at home in the evening.  \r\nAudio nativo: `audio/A1-07/phrases/ik-ben-in-de-avond-thuis.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nRotina noite.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ben / in de avond / thuis.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ben in de avond thuis.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ben ''s avonds thuis.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ben ''s avonds thuis.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ben in de avond thuis.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer thuis como tuis.\r\n- EN: dizer at home rhythm.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ben / in de avond / thuis.\r\nIk ben in de avond thuis.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 5\r\n\r\nFrase: `De kamer is schoon.`\r\n\r\nTraducao PT: O quarto esta limpo.  \r\nTraducao EN: The room is clean.  \r\nAudio nativo: `audio/A1-07/phrases/de-kamer-is-schoon.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nCasa/arrendamento.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDe kamer / is schoon.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDe kamer is schoon.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDe kamer is schoon.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDe kamer is schoon.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `De kamer is schoon.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer shoon.\r\n- EN: dizer clean.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDe kamer / is schoon.\r\nDe kamer is schoon.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter vogais longas e curtas diferentes.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar palavras neerlandesas em cognatos ingleses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto e essencial para o aluno ser entendido.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e, as vezes, significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`. O aluno deve reconhecer antes de tentar usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Perguntas sobem ligeiramente; respostas descem e fecham."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk woon / in Den Haag.\r\nIk sta / om zeven uur / op.\r\nIk werk / in de ochtend.\r\nIk ben / in de avond / thuis.\r\nDe kamer / is schoon.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes.\r\nReduzida: reconhecer ''t, ''n, ''k e ligacoes quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n\r\n```text\r\nIk woon in Den Haag. Ik sta om zeven uur op. Ik ben thuis.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder com informacao propria.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: apresentar-se, pedir ajuda, confirmar informacao, comprar, falar de familia ou pedir direcao.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Substituir uma informacao por dados pessoais.\r\n5. Escrever uma resposta curta para uma situacao real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Ik woon in Den Haag.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Ik sta om zeven uur op.\r\nAluno: Dank u wel. Ik woon in Den Haag. Ik sta om zeven uur op. Ik ben thuis.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi a primeira pergunta ou frase principal?\r\n- Que informacao o aluno conseguiu dar?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno responde a uma pessoa da gemeente, medico, escola ou trabalho usando as frases da licao.\r\n\r\n### Roleplay 2 - Contexto informal\r\n\r\nO aluno responde a colega, vizinho ou colega de curso usando forma simples e natural.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno nao entende a primeira vez, pede repeticao e completa a tarefa comunicativa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Bloquear em vez de pedir repeticao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. O aluno deve fazer shadowing?\r\n\r\n```text\r\nA. Sim\r\nB. Nao\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender, o aluno deve:\r\n\r\n```text\r\nA. bloquear\r\nB. pedir repeticao ou ajuda\r\nC. fingir que entendeu\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nhuis - casa - house\r\nkamer - quarto/divisao - room\r\nkeuken - cozinha - kitchen\r\nbadkamer - casa de banho - bathroom\r\nochtend - manha - morning\r\navond - noite/fim do dia - evening\r\nuur - hora - hour\r\nthuis - em casa - at home\r\nIk woon in Den Haag. - Moro em Haia. - I live in The Hague.\r\nIk sta om zeven uur op. - Levanto-me as sete horas. - I get up at seven.\r\nIk werk in de ochtend. - Trabalho de manha. - I work in the morning.\r\nIk ben in de avond thuis. - Estou em casa a noite. - I am at home in the evening.\r\nDe kamer is schoon. - O quarto esta limpo. - The room is clean.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- gravar a resposta oral final\r\n- responder a uma pergunta nova com a mesma estrutura"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta e natural\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk woon in Den Haag. Ik sta om zeven uur op. Ik ben thuis.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'huis', 'casa', 'house', 'Na palavra `huis`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn huis is klein.', 1 from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'kamer', 'quarto/divisao', 'room', 'Na palavra `kamer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De kamer is groot.', 2 from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'keuken', 'cozinha', 'kitchen', 'Na palavra `keuken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De keuken is schoon.', 3 from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'badkamer', 'casa de banho', 'bathroom', 'Na palavra `badkamer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De badkamer is boven.', 4 from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'ochtend', 'manha', 'morning', 'Na palavra `ochtend`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'In de ochtend werk ik.', 5 from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'avond', 'noite/fim do dia', 'evening', 'Na palavra `avond`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'In de avond ben ik thuis.', 6 from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'uur', 'hora', 'hour', 'Na palavra `uur`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Het is zeven uur.', 7 from lessons l where l.code = 'A1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'thuis', 'em casa', 'at home', 'Na palavra `thuis`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ben thuis.', 8 from lessons l where l.code = 'A1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik woon in Den Haag.', 'Moro em Haia.', 'I live in The Hague.', 'Ik woon / in Den Haag.', 'Ik woon in Den Haag.', 'Ik woon in Den Haag.', '''k Woon in Den Haag.', 'Na frase `Ik woon in Den Haag.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik sta om zeven uur op.', 'Levanto-me as sete horas.', 'I get up at seven.', 'Ik sta / om zeven uur / op.', 'Ik sta om zeven uur op.', 'Ik sta om zeven uur op.', '''k Sta om zeven uur op.', 'Na frase `Ik sta om zeven uur op.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik werk in de ochtend.', 'Trabalho de manha.', 'I work in the morning.', 'Ik werk / in de ochtend.', 'Ik werk in de ochtend.', 'Ik werk in de ochtend.', '''k Werk in de ochtend.', 'Na frase `Ik werk in de ochtend.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ben in de avond thuis.', 'Estou em casa a noite.', 'I am at home in the evening.', 'Ik ben / in de avond / thuis.', 'Ik ben in de avond thuis.', 'Ik ben ''s avonds thuis.', '''k Ben ''s avonds thuis.', 'Na frase `Ik ben in de avond thuis.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A1-07';
