insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-08', 'Compras basicas', 'pedir produto', 7, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Compras sao uma das situacoes mais frequentes para imigrantes: supermercado, padaria, farmacia e mercado. O aluno precisa entender preco, pedir produto e pagar sem bloquear.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: Goedemiddag. Kan ik u helpen?\r\nAluno: Ja, ik wil brood kopen. Hoeveel kost dat?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- pedir produto\r\n- perguntar preco\r\n- dizer que quer pagar com cartao\r\n- entender `alstublieft`\r\n- usar `ik wil`\r\n- fazer roleplay de loja\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk wil brood kopen. Hoeveel kost dat? Ik betaal met pin.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk wil brood kopen.\r\nHoeveel kost dat?\r\nIk betaal met pin.\r\nHeeft u een bon nodig?\r\nAlstublieft, dank u wel.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `brood`\r\n\r\nTraducao PT: pao  \r\nTraducao EN: bread  \r\nAudio nativo: `audio/A1-08/words/brood.native.nl.mp3`  \r\nAproximacao inicial PT: `broot`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `brood`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer brode.\r\n- EN: dizer bread.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wil brood.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbrood\r\nbrood em bloco\r\nIk wil brood.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `brood` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `brood` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `melk`\r\n\r\nTraducao PT: leite  \r\nTraducao EN: milk  \r\nAudio nativo: `audio/A1-08/words/melk.native.nl.mp3`  \r\nAproximacao inicial PT: `melk`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `melk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer melque.\r\n- EN: dizer milk ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe melk is koud.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmelk\r\nmelk em bloco\r\nDe melk is koud.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `melk` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `melk` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `kaas`\r\n\r\nTraducao PT: queijo  \r\nTraducao EN: cheese  \r\nAudio nativo: `audio/A1-08/words/kaas.native.nl.mp3`  \r\nAproximacao inicial PT: `kaas`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kaas`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer casa.\r\n- EN: dizer cheese.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk koop kaas.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkaas\r\nkaas em bloco\r\nIk koop kaas.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kaas` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kaas` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `prijs`\r\n\r\nTraducao PT: preco  \r\nTraducao EN: price  \r\nAudio nativo: `audio/A1-08/words/prijs.native.nl.mp3`  \r\nAproximacao inicial PT: `preiss`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `prijs`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer pris.\r\n- EN: dizer price.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is de prijs?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nprijs\r\nprijs em bloco\r\nWat is de prijs?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `prijs` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `prijs` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `kassa`\r\n\r\nTraducao PT: caixa  \r\nTraducao EN: checkout  \r\nAudio nativo: `audio/A1-08/words/kassa.native.nl.mp3`  \r\nAproximacao inicial PT: `KAS-sa`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kassa`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer caixa.\r\n- EN: dizer cashier.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ga naar de kassa.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkassa\r\nkassa em bloco\r\nIk ga naar de kassa.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kassa` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kassa` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `pin`\r\n\r\nTraducao PT: cartao/debito  \r\nTraducao EN: debit card/PIN  \r\nAudio nativo: `audio/A1-08/words/pin.native.nl.mp3`  \r\nAproximacao inicial PT: `pin`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `pin`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer pine.\r\n- EN: dizer pin ingles longo.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk betaal met pin.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\npin\r\npin em bloco\r\nIk betaal met pin.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `pin` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `pin` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `contant`\r\n\r\nTraducao PT: dinheiro vivo  \r\nTraducao EN: cash  \r\nAudio nativo: `audio/A1-08/words/contant.native.nl.mp3`  \r\nAproximacao inicial PT: `kon-TANT`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `contant`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer contante.\r\n- EN: dizer cash.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBetaalt u contant?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ncontant\r\ncontant em bloco\r\nBetaalt u contant?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `contant` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `contant` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `bon`\r\n\r\nTraducao PT: recibo/talao  \r\nTraducao EN: receipt  \r\nAudio nativo: `audio/A1-08/words/bon.native.nl.mp3`  \r\nAproximacao inicial PT: `bon`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bon`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bom.\r\n- EN: dizer receipt.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWilt u de bon?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbon\r\nbon em bloco\r\nWilt u de bon?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bon` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bon` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-08';
