select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em frases reais. O aluno treina primeiro reconhecimento auditivo, depois producao oral, e so depois variacao escrita."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-08';
