insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-10', 'Revisao A1', 'fazer apresentacao curta', 9, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"A revisao A1 junta os blocos do nivel numa simulacao real: apresentar-se, falar de familia e rotina, comprar algo e pedir informacao de transporte.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nTutor: Vertel iets over uzelf.\r\nAluno: Ik ben Henrique. Ik woon in Nederland. Ik werk vandaag en ik leer Nederlands.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- fazer apresentacao curta\r\n- usar pronomes e artigos\r\n- usar presente regular\r\n- usar zijn/hebben\r\n- responder sobre familia/casa\r\n- resolver compras/transporte com frases A1\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk ben Henrique. Ik woon in Nederland en ik leer Nederlands.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nVertel iets over uzelf.\r\nIk woon in Nederland en ik werk vandaag.\r\nIk heb het formulier en een kaartje.\r\nMijn gezin woont hier.\r\nKunt u de route herhalen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `uzelf`\r\n\r\nTraducao PT: si proprio  \r\nTraducao EN: yourself  \r\nAudio nativo: `audio/A1-10/words/uzelf.native.nl.mp3`  \r\nAproximacao inicial PT: `uu-ZELF`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `uzelf`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer uzelfe.\r\n- EN: usar yourself rhythm.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nVertel iets over uzelf.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nuzelf\r\nuzelf em bloco\r\nVertel iets over uzelf.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `uzelf` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `uzelf` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `werk`\r\n\r\nTraducao PT: trabalho  \r\nTraducao EN: work  \r\nAudio nativo: `audio/A1-10/words/werk.native.nl.mp3`  \r\nAproximacao inicial PT: `werk`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `werk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer werke.\r\n- EN: dizer work longo.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk werk vandaag.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwerk\r\nwerk em bloco\r\nIk werk vandaag.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `werk` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `werk` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `formulier`\r\n\r\nTraducao PT: formulario  \r\nTraducao EN: form  \r\nAudio nativo: `audio/A1-10/words/formulier.native.nl.mp3`  \r\nAproximacao inicial PT: `for-mu-LIR`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `formulier`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer formulario.\r\n- EN: dizer form.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb het formulier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nformulier\r\nformulier em bloco\r\nIk heb het formulier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `formulier` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `formulier` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `gezin`\r\n\r\nTraducao PT: agregado/familia nuclear  \r\nTraducao EN: household/family  \r\nAudio nativo: `audio/A1-10/words/gezin.native.nl.mp3`  \r\nAproximacao inicial PT: `ghu-ZIN`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `gezin`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar g portugues.\r\n- EN: dizer gezin como guess-in.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn gezin woont hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngezin\r\ngezin em bloco\r\nMijn gezin woont hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `gezin` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `gezin` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `boodschappen`\r\n\r\nTraducao PT: compras  \r\nTraducao EN: groceries  \r\nAudio nativo: `audio/A1-10/words/boodschappen.native.nl.mp3`  \r\nAproximacao inicial PT: `BOOT-skhap-pen`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `boodschappen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer shop.\r\n- EN: dizer shopping.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk doe boodschappen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nboodschappen\r\nboodschappen em bloco\r\nIk doe boodschappen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `boodschappen` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `boodschappen` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `route`\r\n\r\nTraducao PT: rota/caminho  \r\nTraducao EN: route  \r\nAudio nativo: `audio/A1-10/words/route.native.nl.mp3`  \r\nAproximacao inicial PT: `ROO-tuh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `route`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer route portugues.\r\n- EN: dizer route ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is de route?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nroute\r\nroute em bloco\r\nWat is de route?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `route` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `route` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `vandaag`\r\n\r\nTraducao PT: hoje  \r\nTraducao EN: today  \r\nAudio nativo: `audio/A1-10/words/vandaag.native.nl.mp3`  \r\nAproximacao inicial PT: `van-DAAKH`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vandaag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer vandag.\r\n- EN: dizer today.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nVandaag werk ik.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvandaag\r\nvandaag em bloco\r\nVandaag werk ik.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `vandaag` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vandaag` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `morgen`\r\n\r\nTraducao PT: amanha  \r\nTraducao EN: tomorrow  \r\nAudio nativo: `audio/A1-10/words/morgen.native.nl.mp3`  \r\nAproximacao inicial PT: `MOR-ghun`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `morgen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer morgen sem garganta.\r\n- EN: dizer morning.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMorgen ben ik vrij.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmorgen\r\nmorgen em bloco\r\nMorgen ben ik vrij.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `morgen` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `morgen` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-10';
