insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-01', 'Perguntas completas', 'formar perguntas com palavras interrogativas', 0, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"A2 exige que o aluno deixe de depender apenas de frases prontas. Nesta licao aprende a perguntar quem, o que, onde, quando, como e por que em servicos, trabalho e vida diaria.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: U heeft een afspraak.\r\nAluno: Waar moet ik wachten? Hoe lang duurt het?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- formar perguntas com palavras interrogativas\r\n- usar verbo na segunda posicao em perguntas abertas\r\n- distinguir pergunta sim/nao e pergunta aberta\r\n- pedir informacao especifica\r\n- reconhecer perguntas naturais em audio\r\n- responder com informacao curta\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nWaar moet ik wachten? Hoe lang duurt het? Welke documenten heeft u nodig?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nWaar moet ik wachten?\r\nHoe lang duurt het?\r\nWanneer begint de afspraak?\r\nWelke documenten heeft u nodig?\r\nWaarom is dat belangrijk?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `waar`\r\n\r\nTraducao PT: onde  \r\nTraducao EN: where  \r\nAudio nativo: `audio/A2-01/words/waar.native.nl.mp3`  \r\nAproximacao inicial PT: `vaar`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `waar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer uar/var forte.\r\n- EN: dizer where.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWaar woont u?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwaar\r\nwaar em bloco\r\nWaar woont u?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `waar` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `waar` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `wanneer`\r\n\r\nTraducao PT: quando  \r\nTraducao EN: when  \r\nAudio nativo: `audio/A2-01/words/wanneer.native.nl.mp3`  \r\nAproximacao inicial PT: `va-NEER`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `wanneer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer quando mentalmente.\r\n- EN: dizer when.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWanneer begint het?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwanneer\r\nwanneer em bloco\r\nWanneer begint het?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `wanneer` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `wanneer` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `waarom`\r\n\r\nTraducao PT: porque  \r\nTraducao EN: why  \r\nAudio nativo: `audio/A2-01/words/waarom.native.nl.mp3`  \r\nAproximacao inicial PT: `vaa-ROM`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `waarom`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer uarom.\r\n- EN: dizer why.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWaarom is dat?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwaarom\r\nwaarom em bloco\r\nWaarom is dat?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `waarom` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `waarom` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `hoe`\r\n\r\nTraducao PT: como  \r\nTraducao EN: how  \r\nAudio nativo: `audio/A2-01/words/hoe.native.nl.mp3`  \r\nAproximacao inicial PT: `ruu`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `hoe`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: dizer how.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHoe werkt dit?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhoe\r\nhoe em bloco\r\nHoe werkt dit?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `hoe` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `hoe` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `hoelang`\r\n\r\nTraducao PT: quanto tempo  \r\nTraducao EN: how long  \r\nAudio nativo: `audio/A2-01/words/hoelang.native.nl.mp3`  \r\nAproximacao inicial PT: `ruu-LANG`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `hoelang`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: separar demais.\r\n- EN: dizer how long.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHoelang duurt het?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhoelang\r\nhoelang em bloco\r\nHoelang duurt het?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `hoelang` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `hoelang` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `welke`\r\n\r\nTraducao PT: qual  \r\nTraducao EN: which  \r\nAudio nativo: `audio/A2-01/words/welke.native.nl.mp3`  \r\nAproximacao inicial PT: `VEL-kuh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `welke`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer uelke.\r\n- EN: dizer which.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWelke bus is dat?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwelke\r\nwelke em bloco\r\nWelke bus is dat?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `welke` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `welke` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `moet`\r\n\r\nTraducao PT: devo/tem de  \r\nTraducao EN: must/should  \r\nAudio nativo: `audio/A2-01/words/moet.native.nl.mp3`  \r\nAproximacao inicial PT: `mut`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `moet`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer moet como escrito.\r\n- EN: dizer moot.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWaar moet ik wachten?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmoet\r\nmoet em bloco\r\nWaar moet ik wachten?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `moet` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `moet` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `duurt`\r\n\r\nTraducao PT: dura  \r\nTraducao EN: takes/lasts  \r\nAudio nativo: `audio/A2-01/words/duurt.native.nl.mp3`  \r\nAproximacao inicial PT: `duurt`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `duurt`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer dura.\r\n- EN: dizer dirt.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHoe lang duurt het?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nduurt\r\nduurt em bloco\r\nHoe lang duurt het?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `duurt` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `duurt` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-01';
