insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Negacao e essencial para seguranca comunicativa: dizer que nao tem documento, nao entende, nao pode comparecer, nao trabalha num dia, ou que uma informacao esta errada.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: Heeft u een DigiD?\r\nAluno: Nee, ik heb geen DigiD. Ik begrijp het formulier niet.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- usar `niet`\r\n- usar `geen`\r\n- corrigir informacao errada\r\n- negar disponibilidade\r\n- reconhecer negacao em fala natural\r\n- evitar dupla negacao traduzida do portugues\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk heb geen DigiD. Ik begrijp het niet. Dat klopt niet.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk heb geen DigiD.\r\nIk begrijp het niet.\r\nDat klopt niet.\r\nIk ben vandaag niet beschikbaar.\r\nDat is geen probleem.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `niet`\r\n\r\nTraducao PT: nao  \r\nTraducao EN: not  \r\nAudio nativo: `audio/A2-02/words/niet.native.nl.mp3`  \r\nAproximacao inicial PT: `nit`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `niet`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer niete.\r\n- EN: dizer neat.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk begrijp het niet.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nniet\r\nniet em bloco\r\nIk begrijp het niet.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `niet` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `niet` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `geen`\r\n\r\nTraducao PT: nenhum/nao tenho  \r\nTraducao EN: no/not any  \r\nAudio nativo: `audio/A2-02/words/geen.native.nl.mp3`  \r\nAproximacao inicial PT: `gheen` audio-first  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `geen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar g portugues.\r\n- EN: dizer gain.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb geen auto.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngeen\r\ngeen em bloco\r\nIk heb geen auto.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `geen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `geen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `nee`\r\n\r\nTraducao PT: nao  \r\nTraducao EN: no  \r\nAudio nativo: `audio/A2-02/words/nee.native.nl.mp3`  \r\nAproximacao inicial PT: `nee`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `nee`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ne.\r\n- EN: dizer nay.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nNee, dat klopt niet.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnee\r\nnee em bloco\r\nNee, dat klopt niet.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `nee` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `nee` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `klopt`\r\n\r\nTraducao PT: esta correto/bate certo  \r\nTraducao EN: is correct  \r\nAudio nativo: `audio/A2-02/words/klopt.native.nl.mp3`  \r\nAproximacao inicial PT: `klopt`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `klopt`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer kloptu.\r\n- EN: dizer clocked.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDat klopt niet.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nklopt\r\nklopt em bloco\r\nDat klopt niet.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `klopt` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `klopt` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `mogelijk`\r\n\r\nTraducao PT: possivel  \r\nTraducao EN: possible  \r\nAudio nativo: `audio/A2-02/words/mogelijk.native.nl.mp3`  \r\nAproximacao inicial PT: `MOO-ghu-luk`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `mogelijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer mogelik sem g.\r\n- EN: dizer possible.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDat is niet mogelijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmogelijk\r\nmogelijk em bloco\r\nDat is niet mogelijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `mogelijk` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `mogelijk` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `beschikbaar`\r\n\r\nTraducao PT: disponivel  \r\nTraducao EN: available  \r\nAudio nativo: `audio/A2-02/words/beschikbaar.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-SKHI-kbaar`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `beschikbaar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bischikbaar.\r\n- EN: dizer available.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben niet beschikbaar.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbeschikbaar\r\nbeschikbaar em bloco\r\nIk ben niet beschikbaar.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `beschikbaar` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `beschikbaar` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `afspraak`\r\n\r\nTraducao PT: marcacao  \r\nTraducao EN: appointment  \r\nAudio nativo: `audio/A2-02/words/afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: `AF-spraak`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer afspraak com e.\r\n- EN: say appointment.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb geen afspraak.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspraak\r\nafspraak em bloco\r\nIk heb geen afspraak.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afspraak` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspraak` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `probleem`\r\n\r\nTraducao PT: problema  \r\nTraducao EN: problem  \r\nAudio nativo: `audio/A2-02/words/probleem.native.nl.mp3`  \r\nAproximacao inicial PT: `pro-BLEEM`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `probleem`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer problema.\r\n- EN: dizer problem.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGeen probleem.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nprobleem\r\nprobleem em bloco\r\nGeen probleem.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `probleem` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `probleem` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em tarefas praticas A2. O aluno deve reconhecer a forma em audio, usar em frase propria e adaptar a situacao:\r\n\r\n```text\r\nkunnen\r\nmoeten\r\nwillen\r\nhebben\r\nzijn\r\nbegrijpen\r\nherhalen\r\nbevestigen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`geen` nega substantivos indefinidos: `geen afspraak`, `geen DigiD`. `niet` nega verbos, adjetivos, frases ou informacao definida: `Ik begrijp het niet`, `Dat is niet goed`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik heb geen DigiD.`\r\n\r\nTraducao PT: Nao tenho DigiD.  \r\nTraducao EN: I do not have DigiD.  \r\nAudio nativo: `audio/A2-02/phrases/ik-heb-geen-digid.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nAdministracao digital.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk heb / geen DigiD.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk heb geen DigiD.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk heb geen DigiD.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Heb geen DigiD.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik heb geen DigiD.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer geen como quem.\r\n- EN: say gain.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk heb / geen DigiD.\r\nIk heb geen DigiD.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 2\r\n\r\nFrase: `Ik begrijp het niet.`\r\n\r\nTraducao PT: Nao entendo.  \r\nTraducao EN: I do not understand it.  \r\nAudio nativo: `audio/A2-02/phrases/ik-begrijp-het-niet.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir clarificacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk begrijp / het niet.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk begrijp het niet.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk begrijp ''t niet.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Begrijp ''t niet.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik begrijp het niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer be-RRAIP artificial como final.\r\n- EN: say understand rhythm.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk begrijp / het niet.\r\nIk begrijp het niet.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 3\r\n\r\nFrase: `Dat klopt niet.`\r\n\r\nTraducao PT: Isso nao esta certo.  \r\nTraducao EN: That is not correct.  \r\nAudio nativo: `audio/A2-02/phrases/dat-klopt-niet.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nCorrigir dados.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDat klopt / niet.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDat klopt niet.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDat klopt niet.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDa klopt niet.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Dat klopt niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: adicionar vogal final.\r\n- EN: say correct.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDat klopt / niet.\r\nDat klopt niet.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 4\r\n\r\nFrase: `Ik ben vandaag niet beschikbaar.`\r\n\r\nTraducao PT: Nao estou disponivel hoje.  \r\nTraducao EN: I am not available today.  \r\nAudio nativo: `audio/A2-02/phrases/ik-ben-vandaag-niet-beschikbaar.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nTrabalho/marcacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ben vandaag / niet beschikbaar.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ben vandaag niet beschikbaar.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ben vandaag niet beschikbaar.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ben vandaag niet beschikbaar.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ben vandaag niet beschikbaar.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer disponivel em PT.\r\n- EN: say available.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ben vandaag / niet beschikbaar.\r\nIk ben vandaag niet beschikbaar.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 5\r\n\r\nFrase: `Dat is geen probleem.`\r\n\r\nTraducao PT: Isso nao e problema.  \r\nTraducao EN: That is no problem.  \r\nAudio nativo: `audio/A2-02/phrases/dat-is-geen-probleem.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nResponder socialmente.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDat is / geen probleem.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDat is geen probleem.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDa''s geen probleem.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDa''s geen probleem.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Dat is geen probleem.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: usar niet probleem.\r\n- EN: say not problem.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDat is / geen probleem.\r\nDat is geen probleem.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir a ordem da frase diretamente do portugues.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos administrativos/profissionais em pronuncia inglesa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto continua essencial em A2, especialmente em palavras administrativas e profissionais.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e pode mudar significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`; combinacoes como `kunt u` podem soar ligadas. O aluno deve reconhecer antes de usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao; priorizar clareza antes de velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Em A2, deve tambem seguir uma pergunta de seguimento e manter a interacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk heb / geen DigiD.\r\nIk begrijp / het niet.\r\nDat klopt / niet.\r\nIk ben vandaag / niet beschikbaar.\r\nDat is / geen probleem.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, ligacoes com u, e reducoes funcionais quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Substituir uma informacao por dados proprios.\r\n\r\n```text\r\nIk heb geen DigiD. Ik begrijp het niet. Dat klopt niet.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder a uma pergunta de seguimento.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: quem, o que, quando, onde, motivo e proximo passo.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: perguntar, negar, confirmar, remarcar, pedir ajuda, explicar problema ou pedir documento.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Corrigir uma frase com ordem errada.\r\n5. Escrever uma resposta curta para uma situacao real.\r\n6. Escrever uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay com problema real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Ik heb geen DigiD.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Ik begrijp het niet.\r\nAluno: Dank u. Ik heb geen DigiD. Ik begrijp het niet. Dat klopt niet.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o motivo da interacao?\r\n- Que informacao especifica foi pedida?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno usa as frases da licao com funcionario, medico, senhorio, supervisor ou atendente.\r\n\r\n### Roleplay 2 - Contexto telefonico ou audio dificil\r\n\r\nO aluno pede repeticao, identifica palavras-chave e confirma informacao.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno explica a situacao, faz uma pergunta de seguimento e confirma o proximo passo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em perguntas neerlandesas.\r\n- Bloquear em vez de pedir repeticao ou clarificacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. Em A2, o aluno deve:\r\n\r\n```text\r\nA. repetir frases sem contexto\r\nB. adaptar frases a situacoes reais\r\nC. evitar perguntas\r\n```\r\n\r\nResposta: B\r\n\r\n4. Se nao entender uma informacao importante, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir repeticao ou explicacao\r\nC. responder em portugues\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais e roleplay\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nniet - nao - not\r\ngeen - nenhum/nao tenho - no/not any\r\nnee - nao - no\r\nklopt - esta correto/bate certo - is correct\r\nmogelijk - possivel - possible\r\nbeschikbaar - disponivel - available\r\nafspraak - marcacao - appointment\r\nprobleem - problema - problem\r\nIk heb geen DigiD. - Nao tenho DigiD. - I do not have DigiD.\r\nIk begrijp het niet. - Nao entendo. - I do not understand it.\r\nDat klopt niet. - Isso nao esta certo. - That is not correct.\r\nIk ben vandaag niet beschikbaar. - Nao estou disponivel hoje. - I am not available today.\r\nDat is geen probleem. - Isso nao e problema. - That is no problem.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. uma pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- responder oralmente a pergunta de seguimento\r\n- gravar a resposta oral final"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta, natural e uma reducao comum\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- confirmar informacao ou proximo passo\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk heb geen DigiD. Ik begrijp het niet. Dat klopt niet.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'niet', 'nao', 'not', 'Na palavra `niet`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik begrijp het niet.', 1 from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'geen', 'nenhum/nao tenho', 'no/not any', 'Na palavra `geen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb geen auto.', 2 from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'nee', 'nao', 'no', 'Na palavra `nee`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Nee, dat klopt niet.', 3 from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'klopt', 'esta correto/bate certo', 'is correct', 'Na palavra `klopt`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Dat klopt niet.', 4 from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'mogelijk', 'possivel', 'possible', 'Na palavra `mogelijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Dat is niet mogelijk.', 5 from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'beschikbaar', 'disponivel', 'available', 'Na palavra `beschikbaar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ben niet beschikbaar.', 6 from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'afspraak', 'marcacao', 'appointment', 'Na palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb geen afspraak.', 7 from lessons l where l.code = 'A2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'probleem', 'problema', 'problem', 'Na palavra `probleem`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Geen probleem.', 8 from lessons l where l.code = 'A2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik heb geen DigiD.', 'Nao tenho DigiD.', 'I do not have DigiD.', 'Ik heb / geen DigiD.', 'Ik heb geen DigiD.', 'Ik heb geen DigiD.', '''k Heb geen DigiD.', 'Na frase `Ik heb geen DigiD.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik begrijp het niet.', 'Nao entendo.', 'I do not understand it.', 'Ik begrijp / het niet.', 'Ik begrijp het niet.', 'Ik begrijp ''t niet.', '''k Begrijp ''t niet.', 'Na frase `Ik begrijp het niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Dat klopt niet.', 'Isso nao esta certo.', 'That is not correct.', 'Dat klopt / niet.', 'Dat klopt niet.', 'Dat klopt niet.', 'Da klopt niet.', 'Na frase `Dat klopt niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ben vandaag niet beschikbaar.', 'Nao estou disponivel hoje.', 'I am not available today.', 'Ik ben vandaag / niet beschikbaar.', 'Ik ben vandaag niet beschikbaar.', 'Ik ben vandaag niet beschikbaar.', '''k Ben vandaag niet beschikbaar.', 'Na frase `Ik ben vandaag niet beschikbaar.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Dat is geen probleem.', 'Isso nao e problema.', 'That is no problem.', 'Dat is / geen probleem.', 'Dat is geen probleem.', 'Da''s geen probleem.', 'Da''s geen probleem.', 'Na frase `Dat is geen probleem.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A2-02';
