insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-03', 'Marcacoes', 'marcar compromisso', 2, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Marcacoes aparecem em medico, gemeente, escola, entrevistas, reparacoes e servicos. A2 precisa permitir combinar horario, confirmar data e remarcar.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nAssistente: Wanneer kunt u komen?\r\nAluno: Ik kan maandag om tien uur komen. Kunt u de afspraak bevestigen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- marcar compromisso\r\n- confirmar data e hora\r\n- alterar marcacao\r\n- perguntar disponibilidade\r\n- entender confirmacao\r\n- usar `kunnen` em contexto pratico\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk wil een afspraak maken. Kan ik maandag komen? Kunt u de afspraak bevestigen?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk wil een afspraak maken.\r\nKan ik maandag komen?\r\nKunt u de afspraak bevestigen?\r\nIk wil de afspraak verzetten.\r\nWelk tijdstip is beschikbaar?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `afspraak`\r\n\r\nTraducao PT: marcacao  \r\nTraducao EN: appointment  \r\nAudio nativo: `audio/A2-03/words/afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: `AF-spraak`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer afspraak com e.\r\n- EN: say appointment.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een afspraak.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspraak\r\nafspraak em bloco\r\nIk heb een afspraak.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afspraak` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspraak` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `bevestigen`\r\n\r\nTraducao PT: confirmar  \r\nTraducao EN: to confirm  \r\nAudio nativo: `audio/A2-03/words/bevestigen.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-VES-ti-ghen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bevestigen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bevestigen sem g.\r\n- EN: say confirm.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nKunt u de afspraak bevestigen?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbevestigen\r\nbevestigen em bloco\r\nKunt u de afspraak bevestigen?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bevestigen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bevestigen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `verzetten`\r\n\r\nTraducao PT: alterar/remarcar  \r\nTraducao EN: to reschedule  \r\nAudio nativo: `audio/A2-03/words/verzetten.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-ZET-ten`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verzetten`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer versetten.\r\n- EN: say reset.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wil de afspraak verzetten.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverzetten\r\nverzetten em bloco\r\nIk wil de afspraak verzetten.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verzetten` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verzetten` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `beschikbaar`\r\n\r\nTraducao PT: disponivel  \r\nTraducao EN: available  \r\nAudio nativo: `audio/A2-03/words/beschikbaar.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-SKHI-kbaar`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `beschikbaar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer beschikbaar sem sch.\r\n- EN: say available.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBent u beschikbaar?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbeschikbaar\r\nbeschikbaar em bloco\r\nBent u beschikbaar?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `beschikbaar` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `beschikbaar` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `datum`\r\n\r\nTraducao PT: data  \r\nTraducao EN: date  \r\nAudio nativo: `audio/A2-03/words/datum.native.nl.mp3`  \r\nAproximacao inicial PT: `DAA-tum`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `datum`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer datum portugues.\r\n- EN: say date.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is de datum?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndatum\r\ndatum em bloco\r\nWat is de datum?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `datum` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `datum` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `tijdstip`\r\n\r\nTraducao PT: horario/momento  \r\nTraducao EN: time slot  \r\nAudio nativo: `audio/A2-03/words/tijdstip.native.nl.mp3`  \r\nAproximacao inicial PT: `TEIT-stip`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `tijdstip`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer tijdestip.\r\n- EN: say time.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWelk tijdstip past?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntijdstip\r\ntijdstip em bloco\r\nWelk tijdstip past?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `tijdstip` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `tijdstip` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `volgende`\r\n\r\nTraducao PT: proximo/seguinte  \r\nTraducao EN: next  \r\nAudio nativo: `audio/A2-03/words/volgende.native.nl.mp3`  \r\nAproximacao inicial PT: `VOL-ghen-duh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `volgende`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer volgende sem g.\r\n- EN: say following.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nVolgende week.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvolgende\r\nvolgende em bloco\r\nVolgende week.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `volgende` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `volgende` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `agenda`\r\n\r\nTraducao PT: agenda/calendario  \r\nTraducao EN: calendar  \r\nAudio nativo: `audio/A2-03/words/agenda.native.nl.mp3`  \r\nAproximacao inicial PT: `aa-GEN-da`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `agenda`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer agenda PT.\r\n- EN: say agenda English.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk kijk in mijn agenda.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nagenda\r\nagenda em bloco\r\nIk kijk in mijn agenda.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `agenda` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `agenda` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-03';
