select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`kunnen` para disponibilidade: `Ik kan maandag komen`, `Kunt u de afspraak bevestigen?`. Tempo com `op maandag`, `om tien uur`, `volgende week`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-03';
