insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-04', 'Saude e medico', 'nomear sintomas comuns', 3, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Saude e um dominio de alto impacto. O aluno A2 deve conseguir explicar sintomas comuns, marcar consulta, entender instrucoes simples e pedir clarificacao sem fingir que compreendeu.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nHuisarts: Wat zijn uw klachten?\r\nAluno: Ik heb hoofdpijn en koorts. Kunt u dat uitleggen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- nomear sintomas comuns\r\n- dizer ha quanto tempo tem sintomas\r\n- entender instrucoes simples\r\n- pedir explicacao\r\n- usar `pijn` e `koorts`\r\n- nao confundir linguagem medica critica\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk heb hoofdpijn en koorts. Wat moet ik doen? Kunt u dat uitleggen?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk heb hoofdpijn en koorts.\r\nSinds gisteren heb ik pijn.\r\nWat moet ik doen?\r\nKunt u dat uitleggen?\r\nIk begrijp de instructie niet.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `huisarts`\r\n\r\nTraducao PT: medico de familia  \r\nTraducao EN: GP/family doctor  \r\nAudio nativo: `audio/A2-04/words/huisarts.native.nl.mp3`  \r\nAproximacao inicial PT: `HUYS-aarts`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `huisarts`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer house-arts.\r\n- EN: say house arts.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk bel de huisarts.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhuisarts\r\nhuisarts em bloco\r\nIk bel de huisarts.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `huisarts` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `huisarts` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `klachten`\r\n\r\nTraducao PT: queixas/sintomas  \r\nTraducao EN: complaints/symptoms  \r\nAudio nativo: `audio/A2-04/words/klachten.native.nl.mp3`  \r\nAproximacao inicial PT: `KLAAKH-ten`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `klachten`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer klachten sem garganta.\r\n- EN: say complaints.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat zijn uw klachten?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nklachten\r\nklachten em bloco\r\nWat zijn uw klachten?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `klachten` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `klachten` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `hoofdpijn`\r\n\r\nTraducao PT: dor de cabeca  \r\nTraducao EN: headache  \r\nAudio nativo: `audio/A2-04/words/hoofdpijn.native.nl.mp3`  \r\nAproximacao inicial PT: `HOOFT-pein`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `hoofdpijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: say headache.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb hoofdpijn.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhoofdpijn\r\nhoofdpijn em bloco\r\nIk heb hoofdpijn.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `hoofdpijn` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `hoofdpijn` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `koorts`\r\n\r\nTraducao PT: febre  \r\nTraducao EN: fever  \r\nAudio nativo: `audio/A2-04/words/koorts.native.nl.mp3`  \r\nAproximacao inicial PT: `koorts`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `koorts`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer corte.\r\n- EN: say fever.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb koorts.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkoorts\r\nkoorts em bloco\r\nIk heb koorts.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `koorts` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `koorts` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `buikpijn`\r\n\r\nTraducao PT: dor de barriga  \r\nTraducao EN: stomach ache  \r\nAudio nativo: `audio/A2-04/words/buikpijn.native.nl.mp3`  \r\nAproximacao inicial PT: `BUIK-pein`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `buikpijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer buik como book.\r\n- EN: say stomach.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb buikpijn.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbuikpijn\r\nbuikpijn em bloco\r\nIk heb buikpijn.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `buikpijn` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `buikpijn` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `medicijn`\r\n\r\nTraducao PT: medicamento  \r\nTraducao EN: medicine  \r\nAudio nativo: `audio/A2-04/words/medicijn.native.nl.mp3`  \r\nAproximacao inicial PT: `me-di-SEIN`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `medicijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer medicina.\r\n- EN: say medicine.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHeeft u medicijn?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmedicijn\r\nmedicijn em bloco\r\nHeeft u medicijn?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `medicijn` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `medicijn` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `recept`\r\n\r\nTraducao PT: receita medica  \r\nTraducao EN: prescription  \r\nAudio nativo: `audio/A2-04/words/recept.native.nl.mp3`  \r\nAproximacao inicial PT: `ruh-SEPT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `recept`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer receita.\r\n- EN: say receipt.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een recept.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nrecept\r\nrecept em bloco\r\nIk heb een recept.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `recept` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `recept` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `uitleggen`\r\n\r\nTraducao PT: explicar  \r\nTraducao EN: to explain  \r\nAudio nativo: `audio/A2-04/words/uitleggen.native.nl.mp3`  \r\nAproximacao inicial PT: `UIT-le-ghen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `uitleggen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer uitleggen sem g.\r\n- EN: say explain.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nKunt u dat uitleggen?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nuitleggen\r\nuitleggen em bloco\r\nKunt u dat uitleggen?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `uitleggen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `uitleggen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-04';
