insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-05', 'Gemeente', 'explicar motivo da visita', 4, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"A gemeente e central para registo, morada, documentos, agendamentos e informacoes oficiais. O aluno precisa entender perguntas formais e responder com dados pessoais.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: Waarvoor komt u?\r\nAluno: Ik kom voor mijn inschrijving. Welke documenten heeft u nodig?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- explicar motivo da visita\r\n- falar de inscricao\r\n- entender pedido de documentos\r\n- confirmar morada\r\n- pedir instrucoes\r\n- usar linguagem formal\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk kom voor mijn inschrijving. Welke documenten heeft u nodig?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk kom voor mijn inschrijving.\r\nWelke documenten heeft u nodig?\r\nMijn adres is veranderd.\r\nKunt u mij uitleg geven?\r\nWaar moet ik tekenen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `gemeente`\r\n\r\nTraducao PT: municipio/camara  \r\nTraducao EN: municipality  \r\nAudio nativo: `audio/A2-05/words/gemeente.native.nl.mp3`  \r\nAproximacao inicial PT: `ghu-MEEN-tuh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `gemeente`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer gemeente com g portugues.\r\n- EN: say municipality.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ga naar de gemeente.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngemeente\r\ngemeente em bloco\r\nIk ga naar de gemeente.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `gemeente` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `gemeente` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `inschrijving`\r\n\r\nTraducao PT: inscricao/registo  \r\nTraducao EN: registration  \r\nAudio nativo: `audio/A2-05/words/inschrijving.native.nl.mp3`  \r\nAproximacao inicial PT: `IN-skhrei-ving`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `inschrijving`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer inscricao em PT.\r\n- EN: say registration.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk kom voor mijn inschrijving.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ninschrijving\r\ninschrijving em bloco\r\nIk kom voor mijn inschrijving.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `inschrijving` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `inschrijving` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `adres`\r\n\r\nTraducao PT: morada/endereco  \r\nTraducao EN: address  \r\nAudio nativo: `audio/A2-05/words/adres.native.nl.mp3`  \r\nAproximacao inicial PT: `a-DRES`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `adres`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer adresso.\r\n- EN: say address.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn adres is veranderd.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nadres\r\nadres em bloco\r\nMijn adres is veranderd.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `adres` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `adres` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `document`\r\n\r\nTraducao PT: documento  \r\nTraducao EN: document  \r\nAudio nativo: `audio/A2-05/words/document.native.nl.mp3`  \r\nAproximacao inicial PT: `do-ku-MENT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `document`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer documento.\r\n- EN: say document English.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHeeft u een document?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndocument\r\ndocument em bloco\r\nHeeft u een document?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `document` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `document` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `paspoort`\r\n\r\nTraducao PT: passaporte  \r\nTraducao EN: passport  \r\nAudio nativo: `audio/A2-05/words/paspoort.native.nl.mp3`  \r\nAproximacao inicial PT: `PAS-poort`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `paspoort`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer passaporte.\r\n- EN: say passport.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDit is mijn paspoort.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\npaspoort\r\npaspoort em bloco\r\nDit is mijn paspoort.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `paspoort` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `paspoort` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `identiteitskaart`\r\n\r\nTraducao PT: cartao de identificacao  \r\nTraducao EN: ID card  \r\nAudio nativo: `audio/A2-05/words/identiteitskaart.native.nl.mp3`  \r\nAproximacao inicial PT: `i-den-ti-TEITS-kaart`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `identiteitskaart`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer identidade.\r\n- EN: say ID card.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een identiteitskaart.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nidentiteitskaart\r\nidentiteitskaart em bloco\r\nIk heb een identiteitskaart.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `identiteitskaart` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `identiteitskaart` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `verhuizen`\r\n\r\nTraducao PT: mudar de casa  \r\nTraducao EN: to move house  \r\nAudio nativo: `audio/A2-05/words/verhuizen.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-HUI-zen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verhuizen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer verhuisen.\r\n- EN: say move.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ga verhuizen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverhuizen\r\nverhuizen em bloco\r\nIk ga verhuizen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verhuizen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verhuizen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `bewijs`\r\n\r\nTraducao PT: comprovativo/prova  \r\nTraducao EN: proof  \r\nAudio nativo: `audio/A2-05/words/bewijs.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-VEIS`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bewijs`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bewijs como bevis.\r\n- EN: say proof.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHeeft u een bewijs?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbewijs\r\nbewijs em bloco\r\nHeeft u een bewijs?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bewijs` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bewijs` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em tarefas praticas A2. O aluno deve reconhecer a forma em audio, usar em frase propria e adaptar a situacao:\r\n\r\n```text\r\nkunnen\r\nmoeten\r\nwillen\r\nhebben\r\nzijn\r\nbegrijpen\r\nherhalen\r\nbevestigen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`Ik kom voor + substantivo`: `Ik kom voor mijn inschrijving`. `Waarvoor` pergunta motivo. `nodig hebben` aparece como bloco: `Welke documenten heeft u nodig?`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik kom voor mijn inschrijving.`\r\n\r\nTraducao PT: Venho para a minha inscricao.  \r\nTraducao EN: I come for my registration.  \r\nAudio nativo: `audio/A2-05/phrases/ik-kom-voor-mijn-inschrijving.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nRececao gemeente.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk kom / voor mijn inschrijving.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk kom voor mijn inschrijving.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk kom voor m''n inschrijving.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Kom voor m''n inschrijving.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik kom voor mijn inschrijving.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer inscricao.\r\n- EN: say registration.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk kom / voor mijn inschrijving.\r\nIk kom voor mijn inschrijving.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 2\r\n\r\nFrase: `Welke documenten heeft u nodig?`\r\n\r\nTraducao PT: Que documentos precisa?  \r\nTraducao EN: Which documents do you need?  \r\nAudio nativo: `audio/A2-05/phrases/welke-documenten-heeft-u-nodig.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nLista de documentos.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWelke documenten / heeft u nodig?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWelke documenten heeft u nodig?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWelke documenten heeftu nodig?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWelke documenten heeft u nodig?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Welke documenten heeft u nodig?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer documentos PT.\r\n- EN: say documents.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWelke documenten / heeft u nodig?\r\nWelke documenten heeft u nodig?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 3\r\n\r\nFrase: `Mijn adres is veranderd.`\r\n\r\nTraducao PT: A minha morada mudou.  \r\nTraducao EN: My address has changed.  \r\nAudio nativo: `audio/A2-05/phrases/mijn-adres-is-veranderd.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nAlteracao morada.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMijn adres / is veranderd.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMijn adres is veranderd.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nM''n adres is veranderd.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nM''n adres is veranderd.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Mijn adres is veranderd.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer mudar em PT.\r\n- EN: say changed.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMijn adres / is veranderd.\r\nMijn adres is veranderd.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 4\r\n\r\nFrase: `Kunt u mij uitleg geven?`\r\n\r\nTraducao PT: Pode dar-me uma explicacao?  \r\nTraducao EN: Can you give me an explanation?  \r\nAudio nativo: `audio/A2-05/phrases/kunt-u-mij-uitleg-geven.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir orientacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u mij / uitleg geven?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u mij uitleg geven?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKuntu mij uitleg geven?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u mij uitleg geven?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u mij uitleg geven?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer uitleg sem g.\r\n- EN: say explanation.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u mij / uitleg geven?\r\nKunt u mij uitleg geven?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 5\r\n\r\nFrase: `Waar moet ik tekenen?`\r\n\r\nTraducao PT: Onde devo assinar?  \r\nTraducao EN: Where should I sign?  \r\nAudio nativo: `audio/A2-05/phrases/waar-moet-ik-tekenen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDocumentos.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWaar moet ik / tekenen?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWaar moet ik tekenen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWaar moet ik tekenen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWaar moet ''k tekenen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Waar moet ik tekenen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer assinar em PT.\r\n- EN: say sign.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWaar moet ik / tekenen?\r\nWaar moet ik tekenen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir a ordem da frase diretamente do portugues.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos administrativos/profissionais em pronuncia inglesa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto continua essencial em A2, especialmente em palavras administrativas e profissionais.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e pode mudar significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`; combinacoes como `kunt u` podem soar ligadas. O aluno deve reconhecer antes de usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao; priorizar clareza antes de velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Em A2, deve tambem seguir uma pergunta de seguimento e manter a interacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk kom / voor mijn inschrijving.\r\nWelke documenten / heeft u nodig?\r\nMijn adres / is veranderd.\r\nKunt u mij / uitleg geven?\r\nWaar moet ik / tekenen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, ligacoes com u, e reducoes funcionais quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Substituir uma informacao por dados proprios.\r\n\r\n```text\r\nIk kom voor mijn inschrijving. Welke documenten heeft u nodig?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder a uma pergunta de seguimento.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: quem, o que, quando, onde, motivo e proximo passo.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: perguntar, negar, confirmar, remarcar, pedir ajuda, explicar problema ou pedir documento.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Corrigir uma frase com ordem errada.\r\n5. Escrever uma resposta curta para uma situacao real.\r\n6. Escrever uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay com problema real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Ik kom voor mijn inschrijving.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Welke documenten heeft u nodig?\r\nAluno: Dank u. Ik kom voor mijn inschrijving. Welke documenten heeft u nodig?\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o motivo da interacao?\r\n- Que informacao especifica foi pedida?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno usa as frases da licao com funcionario, medico, senhorio, supervisor ou atendente.\r\n\r\n### Roleplay 2 - Contexto telefonico ou audio dificil\r\n\r\nO aluno pede repeticao, identifica palavras-chave e confirma informacao.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno explica a situacao, faz uma pergunta de seguimento e confirma o proximo passo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em perguntas neerlandesas.\r\n- Bloquear em vez de pedir repeticao ou clarificacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. Em A2, o aluno deve:\r\n\r\n```text\r\nA. repetir frases sem contexto\r\nB. adaptar frases a situacoes reais\r\nC. evitar perguntas\r\n```\r\n\r\nResposta: B\r\n\r\n4. Se nao entender uma informacao importante, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir repeticao ou explicacao\r\nC. responder em portugues\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais e roleplay\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\ngemeente - municipio/camara - municipality\r\ninschrijving - inscricao/registo - registration\r\nadres - morada/endereco - address\r\ndocument - documento - document\r\npaspoort - passaporte - passport\r\nidentiteitskaart - cartao de identificacao - ID card\r\nverhuizen - mudar de casa - to move house\r\nbewijs - comprovativo/prova - proof\r\nIk kom voor mijn inschrijving. - Venho para a minha inscricao. - I come for my registration.\r\nWelke documenten heeft u nodig? - Que documentos precisa? - Which documents do you need?\r\nMijn adres is veranderd. - A minha morada mudou. - My address has changed.\r\nKunt u mij uitleg geven? - Pode dar-me uma explicacao? - Can you give me an explanation?\r\nWaar moet ik tekenen? - Onde devo assinar? - Where should I sign?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. uma pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- responder oralmente a pergunta de seguimento\r\n- gravar a resposta oral final"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta, natural e uma reducao comum\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- confirmar informacao ou proximo passo\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk kom voor mijn inschrijving. Welke documenten heeft u nodig?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'gemeente', 'municipio/camara', 'municipality', 'Na palavra `gemeente`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ga naar de gemeente.', 1 from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'inschrijving', 'inscricao/registo', 'registration', 'Na palavra `inschrijving`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik kom voor mijn inschrijving.', 2 from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'adres', 'morada/endereco', 'address', 'Na palavra `adres`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn adres is veranderd.', 3 from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'document', 'documento', 'document', 'Na palavra `document`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Heeft u een document?', 4 from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'paspoort', 'passaporte', 'passport', 'Na palavra `paspoort`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Dit is mijn paspoort.', 5 from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'identiteitskaart', 'cartao de identificacao', 'ID card', 'Na palavra `identiteitskaart`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb een identiteitskaart.', 6 from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'verhuizen', 'mudar de casa', 'to move house', 'Na palavra `verhuizen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ga verhuizen.', 7 from lessons l where l.code = 'A2-05';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'bewijs', 'comprovativo/prova', 'proof', 'Na palavra `bewijs`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Heeft u een bewijs?', 8 from lessons l where l.code = 'A2-05';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik kom voor mijn inschrijving.', 'Venho para a minha inscricao.', 'I come for my registration.', 'Ik kom / voor mijn inschrijving.', 'Ik kom voor mijn inschrijving.', 'Ik kom voor m''n inschrijving.', '''k Kom voor m''n inschrijving.', 'Na frase `Ik kom voor mijn inschrijving.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A2-05';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Welke documenten heeft u nodig?', 'Que documentos precisa?', 'Which documents do you need?', 'Welke documenten / heeft u nodig?', 'Welke documenten heeft u nodig?', 'Welke documenten heeftu nodig?', 'Welke documenten heeft u nodig?', 'Na frase `Welke documenten heeft u nodig?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A2-05';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Mijn adres is veranderd.', 'A minha morada mudou.', 'My address has changed.', 'Mijn adres / is veranderd.', 'Mijn adres is veranderd.', 'M''n adres is veranderd.', 'M''n adres is veranderd.', 'Na frase `Mijn adres is veranderd.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A2-05';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u mij uitleg geven?', 'Pode dar-me uma explicacao?', 'Can you give me an explanation?', 'Kunt u mij / uitleg geven?', 'Kunt u mij uitleg geven?', 'Kuntu mij uitleg geven?', 'Kunt u mij uitleg geven?', 'Na frase `Kunt u mij uitleg geven?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A2-05';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Waar moet ik tekenen?', 'Onde devo assinar?', 'Where should I sign?', 'Waar moet ik / tekenen?', 'Waar moet ik tekenen?', 'Waar moet ik tekenen?', 'Waar moet ''k tekenen?', 'Na frase `Waar moet ik tekenen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A2-05';
