insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-06', 'BSN e DigiD', 'distinguir BSN e DigiD', 5, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"BSN e DigiD sao essenciais para trabalhar, tratar saude, impostos, subsidios e servicos publicos. O aluno precisa entender perguntas, proteger dados e pedir ajuda.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: Heeft u een BSN en DigiD?\r\nAluno: Ik heb een BSN, maar ik heb nog geen DigiD.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- distinguir BSN e DigiD\r\n- dizer que tem/nao tem\r\n- pedir ajuda com ativacao\r\n- entender seguranca basica\r\n- soletrar dados\r\n- evitar partilhar informacao sensivel indevidamente\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk heb een BSN, maar geen DigiD. Ik kan niet inloggen.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk heb een BSN, maar geen DigiD.\r\nIk wil DigiD aanvragen.\r\nIk kan niet inloggen.\r\nIs dit veilig?\r\nIk deel mijn wachtwoord niet.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `BSN`\r\n\r\nTraducao PT: numero de cidadao  \r\nTraducao EN: citizen service number  \r\nAudio nativo: `audio/A2-06/words/bsn.native.nl.mp3`  \r\nAproximacao inicial PT: `bee-es-en` audio-first  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `BSN`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar letras portuguesas.\r\n- EN: use English letters only.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een BSN.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nBSN\r\nBSN em bloco\r\nIk heb een BSN.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `BSN` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `BSN` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `DigiD`\r\n\r\nTraducao PT: identificacao digital  \r\nTraducao EN: digital ID  \r\nAudio nativo: `audio/A2-06/words/digid.native.nl.mp3`  \r\nAproximacao inicial PT: `DI-ghi-dee` audio-first  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `DigiD`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer digid portugues.\r\n- EN: say digital ID.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb geen DigiD.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDigiD\r\nDigiD em bloco\r\nIk heb geen DigiD.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `DigiD` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `DigiD` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `aanvragen`\r\n\r\nTraducao PT: pedir/requerer  \r\nTraducao EN: to apply for  \r\nAudio nativo: `audio/A2-06/words/aanvragen.native.nl.mp3`  \r\nAproximacao inicial PT: `AAN-vraa-ghen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `aanvragen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer aanvragen sem g.\r\n- EN: say request.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wil DigiD aanvragen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\naanvragen\r\naanvragen em bloco\r\nIk wil DigiD aanvragen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `aanvragen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `aanvragen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `activeren`\r\n\r\nTraducao PT: ativar  \r\nTraducao EN: to activate  \r\nAudio nativo: `audio/A2-06/words/activeren.native.nl.mp3`  \r\nAproximacao inicial PT: `ak-ti-VE-ren`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `activeren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ativar.\r\n- EN: say activate.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk moet mijn DigiD activeren.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nactiveren\r\nactiveren em bloco\r\nIk moet mijn DigiD activeren.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `activeren` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `activeren` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `inloggen`\r\n\r\nTraducao PT: iniciar sessao  \r\nTraducao EN: to log in  \r\nAudio nativo: `audio/A2-06/words/inloggen.native.nl.mp3`  \r\nAproximacao inicial PT: `IN-lo-ghen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `inloggen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer login.\r\n- EN: say log in.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk kan niet inloggen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ninloggen\r\ninloggen em bloco\r\nIk kan niet inloggen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `inloggen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `inloggen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `wachtwoord`\r\n\r\nTraducao PT: palavra-passe  \r\nTraducao EN: password  \r\nAudio nativo: `audio/A2-06/words/wachtwoord.native.nl.mp3`  \r\nAproximacao inicial PT: `VAKHT-voort`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `wachtwoord`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer password.\r\n- EN: say password.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk weet mijn wachtwoord niet.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwachtwoord\r\nwachtwoord em bloco\r\nIk weet mijn wachtwoord niet.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `wachtwoord` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `wachtwoord` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `veilig`\r\n\r\nTraducao PT: seguro  \r\nTraducao EN: safe/secure  \r\nAudio nativo: `audio/A2-06/words/veilig.native.nl.mp3`  \r\nAproximacao inicial PT: `VEI-lukh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `veilig`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer veilig sem g.\r\n- EN: say safe.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIs dat veilig?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nveilig\r\nveilig em bloco\r\nIs dat veilig?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `veilig` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `veilig` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `code`\r\n\r\nTraducao PT: codigo  \r\nTraducao EN: code  \r\nAudio nativo: `audio/A2-06/words/code.native.nl.mp3`  \r\nAproximacao inicial PT: `KOO-duh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `code`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer codigo.\r\n- EN: say code English.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een code ontvangen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ncode\r\ncode em bloco\r\nIk heb een code ontvangen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `code` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `code` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em tarefas praticas A2. O aluno deve reconhecer a forma em audio, usar em frase propria e adaptar a situacao:\r\n\r\n```text\r\nkunnen\r\nmoeten\r\nwillen\r\nhebben\r\nzijn\r\nbegrijpen\r\nherhalen\r\nbevestigen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`wel/nog geen`: `Ik heb wel een BSN, maar nog geen DigiD`. `maar` liga contraste. `nodig hebben` para necessidade: `Ik heb hulp nodig`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik heb een BSN, maar geen DigiD.`\r\n\r\nTraducao PT: Tenho BSN, mas nao tenho DigiD.  \r\nTraducao EN: I have a BSN but no DigiD.  \r\nAudio nativo: `audio/A2-06/phrases/ik-heb-een-bsn-maar-geen-digid.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nExplicar situacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk heb een BSN / maar geen DigiD.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk heb een BSN, maar geen DigiD.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk heb ''n BSN, maar geen DigiD.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Heb ''n BSN, maar geen DigiD.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik heb een BSN, maar geen DigiD.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: usar nao tenho sem geen.\r\n- EN: say no DigiD incorrectly.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk heb een BSN / maar geen DigiD.\r\nIk heb een BSN, maar geen DigiD.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 2\r\n\r\nFrase: `Ik wil DigiD aanvragen.`\r\n\r\nTraducao PT: Quero pedir DigiD.  \r\nTraducao EN: I want to apply for DigiD.  \r\nAudio nativo: `audio/A2-06/phrases/ik-wil-digid-aanvragen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedido digital.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk wil / DigiD aanvragen.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk wil DigiD aanvragen.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk wil DigiD aanvragen.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Wil DigiD aanvragen.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik wil DigiD aanvragen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer aanvraag sem g.\r\n- EN: say apply.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk wil / DigiD aanvragen.\r\nIk wil DigiD aanvragen.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 3\r\n\r\nFrase: `Ik kan niet inloggen.`\r\n\r\nTraducao PT: Nao consigo iniciar sessao.  \r\nTraducao EN: I cannot log in.  \r\nAudio nativo: `audio/A2-06/phrases/ik-kan-niet-inloggen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nProblema online.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk kan niet / inloggen.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk kan niet inloggen.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk kan niet inloggen.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Kan niet inloggen.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik kan niet inloggen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer login.\r\n- EN: say log in.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk kan niet / inloggen.\r\nIk kan niet inloggen.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 4\r\n\r\nFrase: `Is dit veilig?`\r\n\r\nTraducao PT: Isto e seguro?  \r\nTraducao EN: Is this secure?  \r\nAudio nativo: `audio/A2-06/phrases/is-dit-veilig.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nSeguranca.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIs dit / veilig?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIs dit veilig?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIs dit veilig?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIs dit veilig?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Is dit veilig?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer seguro em PT.\r\n- EN: say safe.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIs dit / veilig?\r\nIs dit veilig?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 5\r\n\r\nFrase: `Ik deel mijn wachtwoord niet.`\r\n\r\nTraducao PT: Nao partilho a minha palavra-passe.  \r\nTraducao EN: I do not share my password.  \r\nAudio nativo: `audio/A2-06/phrases/ik-deel-mijn-wachtwoord-niet.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPrivacidade.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk deel / mijn wachtwoord / niet.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk deel mijn wachtwoord niet.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk deel m''n wachtwoord niet.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIk deel m''n wachtwoord niet.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik deel mijn wachtwoord niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: partilhar palavra-passe em situacao errada.\r\n- EN: say password.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk deel / mijn wachtwoord / niet.\r\nIk deel mijn wachtwoord niet.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir a ordem da frase diretamente do portugues.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos administrativos/profissionais em pronuncia inglesa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto continua essencial em A2, especialmente em palavras administrativas e profissionais.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e pode mudar significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`; combinacoes como `kunt u` podem soar ligadas. O aluno deve reconhecer antes de usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao; priorizar clareza antes de velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Em A2, deve tambem seguir uma pergunta de seguimento e manter a interacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk heb een BSN / maar geen DigiD.\r\nIk wil / DigiD aanvragen.\r\nIk kan niet / inloggen.\r\nIs dit / veilig?\r\nIk deel / mijn wachtwoord / niet.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, ligacoes com u, e reducoes funcionais quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Substituir uma informacao por dados proprios.\r\n\r\n```text\r\nIk heb een BSN, maar geen DigiD. Ik kan niet inloggen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder a uma pergunta de seguimento.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: quem, o que, quando, onde, motivo e proximo passo.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: perguntar, negar, confirmar, remarcar, pedir ajuda, explicar problema ou pedir documento.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Corrigir uma frase com ordem errada.\r\n5. Escrever uma resposta curta para uma situacao real.\r\n6. Escrever uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay com problema real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Ik heb een BSN, maar geen DigiD.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Ik wil DigiD aanvragen.\r\nAluno: Dank u. Ik heb een BSN, maar geen DigiD. Ik kan niet inloggen.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o motivo da interacao?\r\n- Que informacao especifica foi pedida?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno usa as frases da licao com funcionario, medico, senhorio, supervisor ou atendente.\r\n\r\n### Roleplay 2 - Contexto telefonico ou audio dificil\r\n\r\nO aluno pede repeticao, identifica palavras-chave e confirma informacao.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno explica a situacao, faz uma pergunta de seguimento e confirma o proximo passo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em perguntas neerlandesas.\r\n- Bloquear em vez de pedir repeticao ou clarificacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. Em A2, o aluno deve:\r\n\r\n```text\r\nA. repetir frases sem contexto\r\nB. adaptar frases a situacoes reais\r\nC. evitar perguntas\r\n```\r\n\r\nResposta: B\r\n\r\n4. Se nao entender uma informacao importante, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir repeticao ou explicacao\r\nC. responder em portugues\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais e roleplay\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nBSN - numero de cidadao - citizen service number\r\nDigiD - identificacao digital - digital ID\r\naanvragen - pedir/requerer - to apply for\r\nactiveren - ativar - to activate\r\ninloggen - iniciar sessao - to log in\r\nwachtwoord - palavra-passe - password\r\nveilig - seguro - safe/secure\r\ncode - codigo - code\r\nIk heb een BSN, maar geen DigiD. - Tenho BSN, mas nao tenho DigiD. - I have a BSN but no DigiD.\r\nIk wil DigiD aanvragen. - Quero pedir DigiD. - I want to apply for DigiD.\r\nIk kan niet inloggen. - Nao consigo iniciar sessao. - I cannot log in.\r\nIs dit veilig? - Isto e seguro? - Is this secure?\r\nIk deel mijn wachtwoord niet. - Nao partilho a minha palavra-passe. - I do not share my password.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. uma pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- responder oralmente a pergunta de seguimento\r\n- gravar a resposta oral final"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta, natural e uma reducao comum\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- confirmar informacao ou proximo passo\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk heb een BSN, maar geen DigiD. Ik kan niet inloggen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'BSN', 'numero de cidadao', 'citizen service number', 'Na palavra `BSN`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb een BSN.', 1 from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'DigiD', 'identificacao digital', 'digital ID', 'Na palavra `DigiD`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb geen DigiD.', 2 from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'aanvragen', 'pedir/requerer', 'to apply for', 'Na palavra `aanvragen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik wil DigiD aanvragen.', 3 from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'activeren', 'ativar', 'to activate', 'Na palavra `activeren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik moet mijn DigiD activeren.', 4 from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'inloggen', 'iniciar sessao', 'to log in', 'Na palavra `inloggen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik kan niet inloggen.', 5 from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'wachtwoord', 'palavra-passe', 'password', 'Na palavra `wachtwoord`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik weet mijn wachtwoord niet.', 6 from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'veilig', 'seguro', 'safe/secure', 'Na palavra `veilig`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Is dat veilig?', 7 from lessons l where l.code = 'A2-06';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'code', 'codigo', 'code', 'Na palavra `code`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb een code ontvangen.', 8 from lessons l where l.code = 'A2-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik heb een BSN, maar geen DigiD.', 'Tenho BSN, mas nao tenho DigiD.', 'I have a BSN but no DigiD.', 'Ik heb een BSN / maar geen DigiD.', 'Ik heb een BSN, maar geen DigiD.', 'Ik heb ''n BSN, maar geen DigiD.', '''k Heb ''n BSN, maar geen DigiD.', 'Na frase `Ik heb een BSN, maar geen DigiD.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A2-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik wil DigiD aanvragen.', 'Quero pedir DigiD.', 'I want to apply for DigiD.', 'Ik wil / DigiD aanvragen.', 'Ik wil DigiD aanvragen.', 'Ik wil DigiD aanvragen.', '''k Wil DigiD aanvragen.', 'Na frase `Ik wil DigiD aanvragen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A2-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik kan niet inloggen.', 'Nao consigo iniciar sessao.', 'I cannot log in.', 'Ik kan niet / inloggen.', 'Ik kan niet inloggen.', 'Ik kan niet inloggen.', '''k Kan niet inloggen.', 'Na frase `Ik kan niet inloggen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A2-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Is dit veilig?', 'Isto e seguro?', 'Is this secure?', 'Is dit / veilig?', 'Is dit veilig?', 'Is dit veilig?', 'Is dit veilig?', 'Na frase `Is dit veilig?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A2-06';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik deel mijn wachtwoord niet.', 'Nao partilho a minha palavra-passe.', 'I do not share my password.', 'Ik deel / mijn wachtwoord / niet.', 'Ik deel mijn wachtwoord niet.', 'Ik deel m''n wachtwoord niet.', 'Ik deel m''n wachtwoord niet.', 'Na frase `Ik deel mijn wachtwoord niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A2-06';
