insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-07', 'Habitacao', 'nomear elementos da casa', 6, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Habitacao envolve contratos, renda, reparacoes e comunicacao com senhorio/agencia. O aluno A2 deve descrever problemas e pedir acao de forma clara.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nHuurder: De verwarming werkt niet.\r\nVerhuurder: Sinds wanneer?\r\nAluno: Sinds gisteren. Kunt u iemand sturen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- nomear elementos da casa\r\n- descrever problemas\r\n- pedir reparacao\r\n- falar de renda/contrato\r\n- usar `werkt niet`\r\n- entender perguntas do senhorio\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nDe verwarming werkt niet. Kunt u iemand sturen?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nDe verwarming werkt niet.\r\nSinds gisteren is er lekkage.\r\nKunt u iemand sturen?\r\nIk heb een huurcontract.\r\nWanneer kan de reparatie?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `huur`\r\n\r\nTraducao PT: renda/aluguer  \r\nTraducao EN: rent  \r\nAudio nativo: `audio/A2-07/words/huur.native.nl.mp3`  \r\nAproximacao inicial PT: `huur`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `huur`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ur.\r\n- EN: say hire.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe huur is hoog.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhuur\r\nhuur em bloco\r\nDe huur is hoog.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `huur` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `huur` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `contract`\r\n\r\nTraducao PT: contrato  \r\nTraducao EN: contract  \r\nAudio nativo: `audio/A2-07/words/contract.native.nl.mp3`  \r\nAproximacao inicial PT: `kon-TRAKT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `contract`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer contrato.\r\n- EN: say contract English.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een contract.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ncontract\r\ncontract em bloco\r\nIk heb een contract.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `contract` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `contract` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `verhuurder`\r\n\r\nTraducao PT: senhorio  \r\nTraducao EN: landlord  \r\nAudio nativo: `audio/A2-07/words/verhuurder.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-HUUR-der`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verhuurder`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer verhuurder sem h.\r\n- EN: say landlord.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk bel de verhuurder.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverhuurder\r\nverhuurder em bloco\r\nIk bel de verhuurder.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verhuurder` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verhuurder` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `woning`\r\n\r\nTraducao PT: habitacao/casa  \r\nTraducao EN: dwelling/home  \r\nAudio nativo: `audio/A2-07/words/woning.native.nl.mp3`  \r\nAproximacao inicial PT: `VOO-ning`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `woning`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer woning como wonning.\r\n- EN: say home.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe woning is klein.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwoning\r\nwoning em bloco\r\nDe woning is klein.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `woning` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `woning` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `verwarming`\r\n\r\nTraducao PT: aquecimento  \r\nTraducao EN: heating  \r\nAudio nativo: `audio/A2-07/words/verwarming.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-VAR-ming`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verwarming`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer aquecimento.\r\n- EN: say heating.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe verwarming werkt niet.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverwarming\r\nverwarming em bloco\r\nDe verwarming werkt niet.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verwarming` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verwarming` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `lekkage`\r\n\r\nTraducao PT: fuga/infiltracao  \r\nTraducao EN: leak  \r\nAudio nativo: `audio/A2-07/words/lekkage.native.nl.mp3`  \r\nAproximacao inicial PT: `lek-KAA-zhuh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `lekkage`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer leakage ingles.\r\n- EN: say leak.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nEr is lekkage.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nlekkage\r\nlekkage em bloco\r\nEr is lekkage.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `lekkage` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `lekkage` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `reparatie`\r\n\r\nTraducao PT: reparacao  \r\nTraducao EN: repair  \r\nAudio nativo: `audio/A2-07/words/reparatie.native.nl.mp3`  \r\nAproximacao inicial PT: `re-pa-RAA-tsie`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `reparatie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer reparacao.\r\n- EN: say repair.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWanneer is de reparatie?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nreparatie\r\nreparatie em bloco\r\nWanneer is de reparatie?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `reparatie` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `reparatie` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `sleutel`\r\n\r\nTraducao PT: chave  \r\nTraducao EN: key  \r\nAudio nativo: `audio/A2-07/words/sleutel.native.nl.mp3`  \r\nAproximacao inicial PT: `SLEU-tel`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `sleutel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer sletel.\r\n- EN: say key.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb de sleutel.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nsleutel\r\nsleutel em bloco\r\nIk heb de sleutel.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `sleutel` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `sleutel` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em tarefas praticas A2. O aluno deve reconhecer a forma em audio, usar em frase propria e adaptar a situacao:\r\n\r\n```text\r\nkunnen\r\nmoeten\r\nwillen\r\nhebben\r\nzijn\r\nbegrijpen\r\nherhalen\r\nbevestigen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`werken` para funcionamento: `De verwarming werkt niet`. Duracao com `sinds`. Pedido formal: `Kunt u iemand sturen?`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `De verwarming werkt niet.`\r\n\r\nTraducao PT: O aquecimento nao funciona.  \r\nTraducao EN: The heating does not work.  \r\nAudio nativo: `audio/A2-07/phrases/de-verwarming-werkt-niet.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nReportar problema.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDe verwarming / werkt niet.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDe verwarming werkt niet.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDe verwarming werkt niet.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDe verwarming werkt niet.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `De verwarming werkt niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer aquecimento.\r\n- EN: say heating works not.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDe verwarming / werkt niet.\r\nDe verwarming werkt niet.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 2\r\n\r\nFrase: `Sinds gisteren is er lekkage.`\r\n\r\nTraducao PT: Desde ontem ha uma fuga/infiltracao.  \r\nTraducao EN: There has been a leak since yesterday.  \r\nAudio nativo: `audio/A2-07/phrases/sinds-gisteren-is-er-lekkage.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nProblema urgente.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nSinds gisteren / is er lekkage.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nSinds gisteren is er lekkage.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nSinds gisteren is er lekkage.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nSinds gisteren is er lekkage.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Sinds gisteren is er lekkage.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer leakage ingles.\r\n- EN: say leak.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nSinds gisteren / is er lekkage.\r\nSinds gisteren is er lekkage.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 3\r\n\r\nFrase: `Kunt u iemand sturen?`\r\n\r\nTraducao PT: Pode enviar alguem?  \r\nTraducao EN: Can you send someone?  \r\nAudio nativo: `audio/A2-07/phrases/kunt-u-iemand-sturen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir reparacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u / iemand sturen?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u iemand sturen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKuntu iemand sturen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u iemand sturen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u iemand sturen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer mandar alguem.\r\n- EN: say send someone.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u / iemand sturen?\r\nKunt u iemand sturen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 4\r\n\r\nFrase: `Ik heb een huurcontract.`\r\n\r\nTraducao PT: Tenho um contrato de arrendamento.  \r\nTraducao EN: I have a rental contract.  \r\nAudio nativo: `audio/A2-07/phrases/ik-heb-een-huurcontract.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDocumentos habitacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk heb / een huurcontract.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk heb een huurcontract.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk heb ''n huurcontract.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Heb ''n huurcontract.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik heb een huurcontract.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer contrato PT.\r\n- EN: say contract.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk heb / een huurcontract.\r\nIk heb een huurcontract.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 5\r\n\r\nFrase: `Wanneer kan de reparatie?`\r\n\r\nTraducao PT: Quando pode ser a reparacao?  \r\nTraducao EN: When can the repair happen?  \r\nAudio nativo: `audio/A2-07/phrases/wanneer-kan-de-reparatie.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nAgendar reparacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWanneer kan / de reparatie?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWanneer kan de reparatie?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWanneer kan de reparatie?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWanneer kan de reparatie?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Wanneer kan de reparatie?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer reparacao.\r\n- EN: say repair.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWanneer kan / de reparatie?\r\nWanneer kan de reparatie?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir a ordem da frase diretamente do portugues.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos administrativos/profissionais em pronuncia inglesa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto continua essencial em A2, especialmente em palavras administrativas e profissionais.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e pode mudar significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`; combinacoes como `kunt u` podem soar ligadas. O aluno deve reconhecer antes de usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao; priorizar clareza antes de velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Em A2, deve tambem seguir uma pergunta de seguimento e manter a interacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nDe verwarming / werkt niet.\r\nSinds gisteren / is er lekkage.\r\nKunt u / iemand sturen?\r\nIk heb / een huurcontract.\r\nWanneer kan / de reparatie?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, ligacoes com u, e reducoes funcionais quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Substituir uma informacao por dados proprios.\r\n\r\n```text\r\nDe verwarming werkt niet. Kunt u iemand sturen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder a uma pergunta de seguimento.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: quem, o que, quando, onde, motivo e proximo passo.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: perguntar, negar, confirmar, remarcar, pedir ajuda, explicar problema ou pedir documento.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Corrigir uma frase com ordem errada.\r\n5. Escrever uma resposta curta para uma situacao real.\r\n6. Escrever uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay com problema real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: De verwarming werkt niet.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Sinds gisteren is er lekkage.\r\nAluno: Dank u. De verwarming werkt niet. Kunt u iemand sturen?\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o motivo da interacao?\r\n- Que informacao especifica foi pedida?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno usa as frases da licao com funcionario, medico, senhorio, supervisor ou atendente.\r\n\r\n### Roleplay 2 - Contexto telefonico ou audio dificil\r\n\r\nO aluno pede repeticao, identifica palavras-chave e confirma informacao.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno explica a situacao, faz uma pergunta de seguimento e confirma o proximo passo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em perguntas neerlandesas.\r\n- Bloquear em vez de pedir repeticao ou clarificacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. Em A2, o aluno deve:\r\n\r\n```text\r\nA. repetir frases sem contexto\r\nB. adaptar frases a situacoes reais\r\nC. evitar perguntas\r\n```\r\n\r\nResposta: B\r\n\r\n4. Se nao entender uma informacao importante, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir repeticao ou explicacao\r\nC. responder em portugues\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais e roleplay\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nhuur - renda/aluguer - rent\r\ncontract - contrato - contract\r\nverhuurder - senhorio - landlord\r\nwoning - habitacao/casa - dwelling/home\r\nverwarming - aquecimento - heating\r\nlekkage - fuga/infiltracao - leak\r\nreparatie - reparacao - repair\r\nsleutel - chave - key\r\nDe verwarming werkt niet. - O aquecimento nao funciona. - The heating does not work.\r\nSinds gisteren is er lekkage. - Desde ontem ha uma fuga/infiltracao. - There has been a leak since yesterday.\r\nKunt u iemand sturen? - Pode enviar alguem? - Can you send someone?\r\nIk heb een huurcontract. - Tenho um contrato de arrendamento. - I have a rental contract.\r\nWanneer kan de reparatie? - Quando pode ser a reparacao? - When can the repair happen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. uma pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- responder oralmente a pergunta de seguimento\r\n- gravar a resposta oral final"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta, natural e uma reducao comum\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- confirmar informacao ou proximo passo\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nDe verwarming werkt niet. Kunt u iemand sturen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'huur', 'renda/aluguer', 'rent', 'Na palavra `huur`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De huur is hoog.', 1 from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'contract', 'contrato', 'contract', 'Na palavra `contract`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb een contract.', 2 from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'verhuurder', 'senhorio', 'landlord', 'Na palavra `verhuurder`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik bel de verhuurder.', 3 from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'woning', 'habitacao/casa', 'dwelling/home', 'Na palavra `woning`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De woning is klein.', 4 from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'verwarming', 'aquecimento', 'heating', 'Na palavra `verwarming`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De verwarming werkt niet.', 5 from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'lekkage', 'fuga/infiltracao', 'leak', 'Na palavra `lekkage`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Er is lekkage.', 6 from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'reparatie', 'reparacao', 'repair', 'Na palavra `reparatie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Wanneer is de reparatie?', 7 from lessons l where l.code = 'A2-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'sleutel', 'chave', 'key', 'Na palavra `sleutel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb de sleutel.', 8 from lessons l where l.code = 'A2-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'De verwarming werkt niet.', 'O aquecimento nao funciona.', 'The heating does not work.', 'De verwarming / werkt niet.', 'De verwarming werkt niet.', 'De verwarming werkt niet.', 'De verwarming werkt niet.', 'Na frase `De verwarming werkt niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A2-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
