insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-08', 'Trabalho basico', 'entender instrucoes simples', 7, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"No trabalho, o aluno precisa entender instrucoes, dizer disponibilidade, comunicar atrasos, pedir ajuda e confirmar tarefas sem depender sempre de ingles.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nLeidinggevende: Kunt u vandaag om acht uur beginnen?\r\nAluno: Ja, dat kan. Welke taak moet ik eerst doen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- entender instrucoes simples\r\n- confirmar tarefa\r\n- dizer disponibilidade\r\n- comunicar atraso\r\n- pedir ajuda\r\n- usar linguagem profissional basica\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nWelke taak moet ik eerst doen? Kunt u de instructie herhalen?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nWelke taak moet ik eerst doen?\r\nIk ben vandaag te laat.\r\nKunt u de instructie herhalen?\r\nDat kan, geen probleem.\r\nDat kan ik vandaag niet doen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `werk`\r\n\r\nTraducao PT: trabalho  \r\nTraducao EN: work  \r\nAudio nativo: `audio/A2-08/words/werk.native.nl.mp3`  \r\nAproximacao inicial PT: `werk`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `werk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer werke.\r\n- EN: say work.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ga naar werk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwerk\r\nwerk em bloco\r\nIk ga naar werk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `werk` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `werk` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `taak`\r\n\r\nTraducao PT: tarefa  \r\nTraducao EN: task  \r\nAudio nativo: `audio/A2-08/words/taak.native.nl.mp3`  \r\nAproximacao inicial PT: `taak`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `taak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer taka.\r\n- EN: say task.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWelke taak?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntaak\r\ntaak em bloco\r\nWelke taak?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `taak` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `taak` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `ploeg`\r\n\r\nTraducao PT: turno/equipa  \r\nTraducao EN: shift/team  \r\nAudio nativo: `audio/A2-08/words/ploeg.native.nl.mp3`  \r\nAproximacao inicial PT: `ploogh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ploeg`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ploeg sem g.\r\n- EN: say shift.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn ploeg begint vroeg.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nploeg\r\nploeg em bloco\r\nMijn ploeg begint vroeg.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `ploeg` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `ploeg` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `pauze`\r\n\r\nTraducao PT: pausa  \r\nTraducao EN: break  \r\nAudio nativo: `audio/A2-08/words/pauze.native.nl.mp3`  \r\nAproximacao inicial PT: `PAU-zuh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `pauze`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer pausa PT.\r\n- EN: say pause.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb pauze.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\npauze\r\npauze em bloco\r\nIk heb pauze.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `pauze` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `pauze` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `te laat`\r\n\r\nTraducao PT: atrasado  \r\nTraducao EN: too late  \r\nAudio nativo: `audio/A2-08/words/te-laat.native.nl.mp3`  \r\nAproximacao inicial PT: `tuh laat`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `te laat`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer late.\r\n- EN: say late.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben te laat.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nte laat\r\nte laat em bloco\r\nIk ben te laat.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `te laat` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `te laat` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `leidinggevende`\r\n\r\nTraducao PT: supervisor/chefia  \r\nTraducao EN: supervisor  \r\nAudio nativo: `audio/A2-08/words/leidinggevende.native.nl.mp3`  \r\nAproximacao inicial PT: `LEI-ding-GHE-vun-duh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `leidinggevende`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer supervisor sempre.\r\n- EN: say manager.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn leidinggevende is hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nleidinggevende\r\nleidinggevende em bloco\r\nMijn leidinggevende is hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `leidinggevende` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `leidinggevende` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `veiligheid`\r\n\r\nTraducao PT: seguranca  \r\nTraducao EN: safety  \r\nAudio nativo: `audio/A2-08/words/veiligheid.native.nl.mp3`  \r\nAproximacao inicial PT: `VEI-lukh-heid`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `veiligheid`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer seguranca.\r\n- EN: say safety.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nVeiligheid is belangrijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nveiligheid\r\nveiligheid em bloco\r\nVeiligheid is belangrijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `veiligheid` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `veiligheid` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `instructie`\r\n\r\nTraducao PT: instrucao  \r\nTraducao EN: instruction  \r\nAudio nativo: `audio/A2-08/words/instructie.native.nl.mp3`  \r\nAproximacao inicial PT: `in-STRUK-tsie`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `instructie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer instrucao.\r\n- EN: say instruction.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk begrijp de instructie.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ninstructie\r\ninstructie em bloco\r\nIk begrijp de instructie.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `instructie` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `instructie` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-08';
