insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-09', 'Telefonemas', 'abrir chamada', 8, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Telefonemas sao dificeis porque nao ha apoio visual. O aluno A2 precisa identificar quem fala, motivo, dados, hora e proximo passo.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nTelefoniste: Waar belt u voor?\r\nAluno: Ik bel over mijn afspraak. Kunt u langzaam spreken?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- abrir chamada\r\n- dizer motivo\r\n- pedir fala lenta\r\n- soletrar dados\r\n- confirmar numero\r\n- fechar chamada educadamente\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk bel over mijn afspraak. Kunt u dat nummer herhalen?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk bel over mijn afspraak.\r\nMet wie spreek ik?\r\nDe verbinding is slecht.\r\nKunt u dat nummer herhalen?\r\nKunt u mij terugbellen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `bellen`\r\n\r\nTraducao PT: telefonar  \r\nTraducao EN: to call  \r\nAudio nativo: `audio/A2-09/words/bellen.native.nl.mp3`  \r\nAproximacao inicial PT: `BEL-len`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bellen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer belen.\r\n- EN: say bell.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk bel de huisarts.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbellen\r\nbellen em bloco\r\nIk bel de huisarts.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bellen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bellen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `telefoon`\r\n\r\nTraducao PT: telefone  \r\nTraducao EN: phone  \r\nAudio nativo: `audio/A2-09/words/telefoon.native.nl.mp3`  \r\nAproximacao inicial PT: `te-le-FOON`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `telefoon`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer telefone PT.\r\n- EN: say telephone.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn telefoonnummer is...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntelefoon\r\ntelefoon em bloco\r\nMijn telefoonnummer is...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `telefoon` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `telefoon` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `telefoonnummer`\r\n\r\nTraducao PT: numero de telefone  \r\nTraducao EN: phone number  \r\nAudio nativo: `audio/A2-09/words/telefoonnummer.native.nl.mp3`  \r\nAproximacao inicial PT: `te-le-FOON-nu-mer`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `telefoonnummer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer numero PT.\r\n- EN: say phone number.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is uw telefoonnummer?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntelefoonnummer\r\ntelefoonnummer em bloco\r\nWat is uw telefoonnummer?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `telefoonnummer` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `telefoonnummer` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `verbinding`\r\n\r\nTraducao PT: ligacao/conexao  \r\nTraducao EN: connection  \r\nAudio nativo: `audio/A2-09/words/verbinding.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-BIN-ding`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verbinding`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer conexao.\r\n- EN: say connection.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe verbinding is slecht.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverbinding\r\nverbinding em bloco\r\nDe verbinding is slecht.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verbinding` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verbinding` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `bericht`\r\n\r\nTraducao PT: mensagem  \r\nTraducao EN: message  \r\nAudio nativo: `audio/A2-09/words/bericht.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-RIKHT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bericht`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bericht sem garganta.\r\n- EN: say message.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk laat een bericht achter.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbericht\r\nbericht em bloco\r\nIk laat een bericht achter.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bericht` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bericht` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `terugbellen`\r\n\r\nTraducao PT: ligar de volta  \r\nTraducao EN: to call back  \r\nAudio nativo: `audio/A2-09/words/terugbellen.native.nl.mp3`  \r\nAproximacao inicial PT: `te-RUK-bel-len`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `terugbellen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer callback.\r\n- EN: say call back.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nKunt u terugbellen?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nterugbellen\r\nterugbellen em bloco\r\nKunt u terugbellen?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `terugbellen` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `terugbellen` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `spreken`\r\n\r\nTraducao PT: falar  \r\nTraducao EN: to speak  \r\nAudio nativo: `audio/A2-09/words/spreken.native.nl.mp3`  \r\nAproximacao inicial PT: `SPREE-ken`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `spreken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer espreken.\r\n- EN: say speak.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMet wie spreek ik?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nspreken\r\nspreken em bloco\r\nMet wie spreek ik?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `spreken` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `spreken` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `noteren`\r\n\r\nTraducao PT: anotar  \r\nTraducao EN: to note down  \r\nAudio nativo: `audio/A2-09/words/noteren.native.nl.mp3`  \r\nAproximacao inicial PT: `no-TE-ren`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `noteren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer notar.\r\n- EN: say note.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nKunt u dat noteren?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnoteren\r\nnoteren em bloco\r\nKunt u dat noteren?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `noteren` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `noteren` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em tarefas praticas A2. O aluno deve reconhecer a forma em audio, usar em frase propria e adaptar a situacao:\r\n\r\n```text\r\nkunnen\r\nmoeten\r\nwillen\r\nhebben\r\nzijn\r\nbegrijpen\r\nherhalen\r\nbevestigen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`Ik bel over + assunto`: `Ik bel over mijn afspraak`. Perguntas telefonicas comuns: `Waar belt u voor?`, `Kunt u dat herhalen?`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik bel over mijn afspraak.`\r\n\r\nTraducao PT: Estou a ligar sobre a minha marcacao.  \r\nTraducao EN: I am calling about my appointment.  \r\nAudio nativo: `audio/A2-09/phrases/ik-bel-over-mijn-afspraak.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nAbrir chamada.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk bel / over mijn afspraak.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk bel over mijn afspraak.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk bel over m''n afspraak.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Bel over m''n afspraak.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik bel over mijn afspraak.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir estou a ligar literal.\r\n- EN: say calling about.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk bel / over mijn afspraak.\r\nIk bel over mijn afspraak.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 2\r\n\r\nFrase: `Met wie spreek ik?`\r\n\r\nTraducao PT: Com quem estou a falar?  \r\nTraducao EN: Who am I speaking with?  \r\nAudio nativo: `audio/A2-09/phrases/met-wie-spreek-ik.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nIdentificar pessoa.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMet wie / spreek ik?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMet wie spreek ik?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nMet wie spreek ik?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nMet wie spreek ''k?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Met wie spreek ik?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer com quem em PT.\r\n- EN: say speaking with.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMet wie / spreek ik?\r\nMet wie spreek ik?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 3\r\n\r\nFrase: `De verbinding is slecht.`\r\n\r\nTraducao PT: A ligacao esta ma.  \r\nTraducao EN: The connection is bad.  \r\nAudio nativo: `audio/A2-09/phrases/de-verbinding-is-slecht.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nProblema audio.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDe verbinding / is slecht.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDe verbinding is slecht.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDe verbinding is slecht.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDe verbinding is slecht.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `De verbinding is slecht.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer conexao.\r\n- EN: say connection bad.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDe verbinding / is slecht.\r\nDe verbinding is slecht.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 4\r\n\r\nFrase: `Kunt u dat nummer herhalen?`\r\n\r\nTraducao PT: Pode repetir esse numero?  \r\nTraducao EN: Can you repeat that number?  \r\nAudio nativo: `audio/A2-09/phrases/kunt-u-dat-nummer-herhalen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nConfirmar dados.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u / dat nummer / herhalen?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u dat nummer herhalen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKuntu dat nummer herhalen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u dat nummer herhalen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u dat nummer herhalen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: say repeat number.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u / dat nummer / herhalen?\r\nKunt u dat nummer herhalen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento.\r\n\r\n### Frase 5\r\n\r\nFrase: `Kunt u mij terugbellen?`\r\n\r\nTraducao PT: Pode ligar-me de volta?  \r\nTraducao EN: Can you call me back?  \r\nAudio nativo: `audio/A2-09/phrases/kunt-u-mij-terugbellen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nEncaminhar chamada.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u mij / terugbellen?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em blocos, depois em fala natural. Em A2, o aluno tambem deve responder, pedir clarificacao e adaptar a frase com dados proprios.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u mij terugbellen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKuntu mij terugbellen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u mij terugbellen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u mij terugbellen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer callback.\r\n- EN: say call back.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u mij / terugbellen?\r\nKunt u mij terugbellen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir novamente mudando uma informacao.\r\n6. Gravar e comparar ritmo, reducoes, finais e sons dificeis.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em velocidade lenta, natural e dentro de um mini dialogo. Deve identificar palavras-chave, intencao comunicativa, informacao especifica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a uma situacao real e consegue responder a uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir a ordem da frase diretamente do portugues.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos administrativos/profissionais em pronuncia inglesa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto continua essencial em A2, especialmente em palavras administrativas e profissionais.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e pode mudar significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`; combinacoes como `kunt u` podem soar ligadas. O aluno deve reconhecer antes de usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao; priorizar clareza antes de velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Em A2, deve tambem seguir uma pergunta de seguimento e manter a interacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk bel / over mijn afspraak.\r\nMet wie / spreek ik?\r\nDe verbinding / is slecht.\r\nKunt u / dat nummer / herhalen?\r\nKunt u mij / terugbellen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, ligacoes com u, e reducoes funcionais quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Substituir uma informacao por dados proprios.\r\n\r\n```text\r\nIk bel over mijn afspraak. Kunt u dat nummer herhalen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder a uma pergunta de seguimento.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: quem, o que, quando, onde, motivo e proximo passo.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: perguntar, negar, confirmar, remarcar, pedir ajuda, explicar problema ou pedir documento.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Corrigir uma frase com ordem errada.\r\n5. Escrever uma resposta curta para uma situacao real.\r\n6. Escrever uma pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay com problema real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Ik bel over mijn afspraak.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Met wie spreek ik?\r\nAluno: Dank u. Ik bel over mijn afspraak. Kunt u dat nummer herhalen?\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o motivo da interacao?\r\n- Que informacao especifica foi pedida?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno usa as frases da licao com funcionario, medico, senhorio, supervisor ou atendente.\r\n\r\n### Roleplay 2 - Contexto telefonico ou audio dificil\r\n\r\nO aluno pede repeticao, identifica palavras-chave e confirma informacao.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno explica a situacao, faz uma pergunta de seguimento e confirma o proximo passo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em perguntas neerlandesas.\r\n- Bloquear em vez de pedir repeticao ou clarificacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. Em A2, o aluno deve:\r\n\r\n```text\r\nA. repetir frases sem contexto\r\nB. adaptar frases a situacoes reais\r\nC. evitar perguntas\r\n```\r\n\r\nResposta: B\r\n\r\n4. Se nao entender uma informacao importante, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir repeticao ou explicacao\r\nC. responder em portugues\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais e roleplay\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nbellen - telefonar - to call\r\ntelefoon - telefone - phone\r\ntelefoonnummer - numero de telefone - phone number\r\nverbinding - ligacao/conexao - connection\r\nbericht - mensagem - message\r\nterugbellen - ligar de volta - to call back\r\nspreken - falar - to speak\r\nnoteren - anotar - to note down\r\nIk bel over mijn afspraak. - Estou a ligar sobre a minha marcacao. - I am calling about my appointment.\r\nMet wie spreek ik? - Com quem estou a falar? - Who am I speaking with?\r\nDe verbinding is slecht. - A ligacao esta ma. - The connection is bad.\r\nKunt u dat nummer herhalen? - Pode repetir esse numero? - Can you repeat that number?\r\nKunt u mij terugbellen? - Pode ligar-me de volta? - Can you call me back?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. uma pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- responder oralmente a pergunta de seguimento\r\n- gravar a resposta oral final"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta, natural e uma reducao comum\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- confirmar informacao ou proximo passo\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk bel over mijn afspraak. Kunt u dat nummer herhalen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'bellen', 'telefonar', 'to call', 'Na palavra `bellen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik bel de huisarts.', 1 from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'telefoon', 'telefone', 'phone', 'Na palavra `telefoon`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn telefoonnummer is...', 2 from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'telefoonnummer', 'numero de telefone', 'phone number', 'Na palavra `telefoonnummer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Wat is uw telefoonnummer?', 3 from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'verbinding', 'ligacao/conexao', 'connection', 'Na palavra `verbinding`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De verbinding is slecht.', 4 from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'bericht', 'mensagem', 'message', 'Na palavra `bericht`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik laat een bericht achter.', 5 from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'terugbellen', 'ligar de volta', 'to call back', 'Na palavra `terugbellen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Kunt u terugbellen?', 6 from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'spreken', 'falar', 'to speak', 'Na palavra `spreken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Met wie spreek ik?', 7 from lessons l where l.code = 'A2-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'noteren', 'anotar', 'to note down', 'Na palavra `noteren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Kunt u dat noteren?', 8 from lessons l where l.code = 'A2-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik bel over mijn afspraak.', 'Estou a ligar sobre a minha marcacao.', 'I am calling about my appointment.', 'Ik bel / over mijn afspraak.', 'Ik bel over mijn afspraak.', 'Ik bel over m''n afspraak.', '''k Bel over m''n afspraak.', 'Na frase `Ik bel over mijn afspraak.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A2-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Met wie spreek ik?', 'Com quem estou a falar?', 'Who am I speaking with?', 'Met wie / spreek ik?', 'Met wie spreek ik?', 'Met wie spreek ik?', 'Met wie spreek ''k?', 'Na frase `Met wie spreek ik?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A2-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'De verbinding is slecht.', 'A ligacao esta ma.', 'The connection is bad.', 'De verbinding / is slecht.', 'De verbinding is slecht.', 'De verbinding is slecht.', 'De verbinding is slecht.', 'Na frase `De verbinding is slecht.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A2-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u dat nummer herhalen?', 'Pode repetir esse numero?', 'Can you repeat that number?', 'Kunt u / dat nummer / herhalen?', 'Kunt u dat nummer herhalen?', 'Kuntu dat nummer herhalen?', 'Kunt u dat nummer herhalen?', 'Na frase `Kunt u dat nummer herhalen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A2-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u mij terugbellen?', 'Pode ligar-me de volta?', 'Can you call me back?', 'Kunt u mij / terugbellen?', 'Kunt u mij terugbellen?', 'Kuntu mij terugbellen?', 'Kunt u mij terugbellen?', 'Na frase `Kunt u mij terugbellen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A2-09';
