insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-10', 'Emails simples', 'entender estrutura de email formal simples', 9, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Emails sao usados para marcacoes, trabalho, habitacao, escola e gemeente. O aluno A2 precisa escrever mensagens curtas com saudacao, objetivo, informacao e fecho.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nAluno escreve: Geachte heer/mevrouw, ik wil mijn afspraak verzetten. Met vriendelijke groet.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- entender estrutura de email formal simples\r\n- pedir informacao por escrito\r\n- remarcar por email\r\n- usar saudacao e fecho\r\n- evitar traducao direta\r\n- ler resposta curta\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nGeachte heer/mevrouw, ik wil graag mijn afspraak verzetten. Met vriendelijke groet,\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nGeachte heer/mevrouw,\r\nIk wil graag mijn afspraak verzetten.\r\nKunt u mij een nieuwe datum sturen?\r\nZie de bijlage.\r\nMet vriendelijke groet,\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `geachte`\r\n\r\nTraducao PT: estimado/a formal  \r\nTraducao EN: dear formal  \r\nAudio nativo: `audio/A2-10/words/geachte.native.nl.mp3`  \r\nAproximacao inicial PT: `ghu-AKH-tuh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `geachte`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer geachte sem garganta.\r\n- EN: say dear.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGeachte heer/mevrouw.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngeachte\r\ngeachte em bloco\r\nGeachte heer/mevrouw.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `geachte` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `geachte` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `heer`\r\n\r\nTraducao PT: senhor  \r\nTraducao EN: sir/mr  \r\nAudio nativo: `audio/A2-10/words/heer.native.nl.mp3`  \r\nAproximacao inicial PT: `heer`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `heer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer her.\r\n- EN: say here.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGeachte heer.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nheer\r\nheer em bloco\r\nGeachte heer.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `heer` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `heer` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `mevrouw`\r\n\r\nTraducao PT: senhora  \r\nTraducao EN: madam/ms  \r\nAudio nativo: `audio/A2-10/words/mevrouw.native.nl.mp3`  \r\nAproximacao inicial PT: `me-VRAU`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `mevrouw`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer mevrou.\r\n- EN: say madam.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGeachte mevrouw.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmevrouw\r\nmevrouw em bloco\r\nGeachte mevrouw.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `mevrouw` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `mevrouw` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `betreft`\r\n\r\nTraducao PT: assunto/refere-se a  \r\nTraducao EN: concerns  \r\nAudio nativo: `audio/A2-10/words/betreft.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-TREFT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `betreft`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer assunto.\r\n- EN: say subject.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBetreft: afspraak.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbetreft\r\nbetreft em bloco\r\nBetreft: afspraak.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `betreft` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `betreft` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `graag`\r\n\r\nTraducao PT: gostaria/de bom grado  \r\nTraducao EN: would like/please  \r\nAudio nativo: `audio/A2-10/words/graag.native.nl.mp3`  \r\nAproximacao inicial PT: `ghraakh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `graag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar g portugues.\r\n- EN: say grayg.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wil graag...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngraag\r\ngraag em bloco\r\nIk wil graag...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `graag` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `graag` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `verzetten`\r\n\r\nTraducao PT: remarcar  \r\nTraducao EN: reschedule  \r\nAudio nativo: `audio/A2-10/words/verzetten.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-ZET-ten`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verzetten`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer reset.\r\n- EN: say reset.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wil mijn afspraak verzetten.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverzetten\r\nverzetten em bloco\r\nIk wil mijn afspraak verzetten.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verzetten` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verzetten` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `bijlage`\r\n\r\nTraducao PT: anexo  \r\nTraducao EN: attachment  \r\nAudio nativo: `audio/A2-10/words/bijlage.native.nl.mp3`  \r\nAproximacao inicial PT: `BEI-la-ghuh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bijlage`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer anexo.\r\n- EN: say attachment.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nZie de bijlage.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbijlage\r\nbijlage em bloco\r\nZie de bijlage.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bijlage` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bijlage` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `groet`\r\n\r\nTraducao PT: cumprimento/saudacao final  \r\nTraducao EN: greeting/regards  \r\nAudio nativo: `audio/A2-10/words/groet.native.nl.mp3`  \r\nAproximacao inicial PT: `ghroot`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `groet`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer groete.\r\n- EN: say greet.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMet vriendelijke groet.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngroet\r\ngroet em bloco\r\nMet vriendelijke groet.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `groet` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `groet` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em tarefas praticas A2. O aluno deve reconhecer a forma em audio, usar em frase propria e adaptar a situacao:\r\n\r\n```text\r\nkunnen\r\nmoeten\r\nwillen\r\nhebben\r\nzijn\r\nbegrijpen\r\nherhalen\r\nbevestigen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-10';
