select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Email simples: saudacao + motivo + pedido + dados + fecho. Conectores basicos: `omdat`, `maar`, `daarom`. Pedido formal: `Kunt u...?`, `Ik wil graag...`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-10';
