insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-11', 'Cultura diaria', 'entender pontualidade', 10, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-11';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Integracao nao e so vocabulario. O aluno precisa entender pontualidade, comunicacao direta, marcacoes, vizinhos, filas, pagamentos e limites sociais.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nCollega: We beginnen om negen uur precies.\r\nAluno: Begrijp ik het goed? Moet ik om kwart voor negen aanwezig zijn?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-11';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- entender pontualidade\r\n- reconhecer comunicacao direta\r\n- falar com vizinhos/colegas\r\n- pedir confirmacao cultural\r\n- usar frases de clarificacao\r\n- evitar interpretar direto como rude automaticamente\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nBegrijp ik het goed? Wat is hier de regel?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nBegrijp ik het goed?\r\nBedoelt u dat ik op tijd moet zijn?\r\nAfspraak is afspraak.\r\nDat is gezellig.\r\nWat is hier de regel?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-11';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `op tijd`\r\n\r\nTraducao PT: a horas  \r\nTraducao EN: on time  \r\nAudio nativo: `audio/A2-11/words/op-tijd.native.nl.mp3`  \r\nAproximacao inicial PT: `op teit`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `op tijd`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer no tempo.\r\n- EN: say on time.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben op tijd.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nop tijd\r\nop tijd em bloco\r\nIk ben op tijd.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `op tijd` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `op tijd` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `precies`\r\n\r\nTraducao PT: exatamente  \r\nTraducao EN: exactly  \r\nAudio nativo: `audio/A2-11/words/precies.native.nl.mp3`  \r\nAproximacao inicial PT: `pre-SIS`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `precies`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer preciso PT.\r\n- EN: say precise.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nOm negen uur precies.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nprecies\r\nprecies em bloco\r\nOm negen uur precies.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `precies` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `precies` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `afspraak`\r\n\r\nTraducao PT: combinacao/marcacao  \r\nTraducao EN: appointment/agreement  \r\nAudio nativo: `audio/A2-11/words/afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: `AF-spraak`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer afspraak com e.\r\n- EN: say appointment only.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nAfspraak is afspraak.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspraak\r\nafspraak em bloco\r\nAfspraak is afspraak.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afspraak` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspraak` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `direct`\r\n\r\nTraducao PT: direto  \r\nTraducao EN: direct  \r\nAudio nativo: `audio/A2-11/words/direct.native.nl.mp3`  \r\nAproximacao inicial PT: `di-REKT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `direct`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer directo PT.\r\n- EN: say direct.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nNederlanders zijn direct.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndirect\r\ndirect em bloco\r\nNederlanders zijn direct.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `direct` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `direct` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `gezellig`\r\n\r\nTraducao PT: agradavel/convivial  \r\nTraducao EN: cozy/social  \r\nAudio nativo: `audio/A2-11/words/gezellig.native.nl.mp3`  \r\nAproximacao inicial PT: `ghu-ZEL-lukh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `gezellig`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer gezellig sem g.\r\n- EN: no exact English equivalent.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDat is gezellig.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngezellig\r\ngezellig em bloco\r\nDat is gezellig.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `gezellig` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `gezellig` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `buurman`\r\n\r\nTraducao PT: vizinho  \r\nTraducao EN: neighbor man  \r\nAudio nativo: `audio/A2-11/words/buurman.native.nl.mp3`  \r\nAproximacao inicial PT: `BUUR-man`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `buurman`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer burman.\r\n- EN: say neighbor.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn buurman is aardig.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbuurman\r\nbuurman em bloco\r\nMijn buurman is aardig.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `buurman` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `buurman` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `rekening`\r\n\r\nTraducao PT: conta/fatura  \r\nTraducao EN: bill  \r\nAudio nativo: `audio/A2-11/words/rekening.native.nl.mp3`  \r\nAproximacao inicial PT: `REE-kuh-ning`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `rekening`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer conta.\r\n- EN: say bill.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWe delen de rekening.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nrekening\r\nrekening em bloco\r\nWe delen de rekening.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `rekening` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `rekening` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `regel`\r\n\r\nTraducao PT: regra  \r\nTraducao EN: rule  \r\nAudio nativo: `audio/A2-11/words/regel.native.nl.mp3`  \r\nAproximacao inicial PT: `REE-ghul`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `regel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer regra.\r\n- EN: say rule.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is de regel?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nregel\r\nregel em bloco\r\nWat is de regel?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `regel` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `regel` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-11';
