insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A2-12', 'Revisao A2', 'integrar perguntas completas', 11, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar neerlandes real em situacoes praticas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-12';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"A revisao A2 testa se o aluno consegue funcionar em situacoes praticas sem depender de frases isoladas: perguntar, negar, confirmar, pedir ajuda, explicar problema e seguir instrucoes.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: Waar belt u voor?\r\nAluno: Ik bel over mijn afspraak. Ik kan maandag niet komen. Kunt u de afspraak verzetten?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-12';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- integrar perguntas completas\r\n- usar negacao corretamente\r\n- resolver marcacao\r\n- explicar problema simples\r\n- fazer telefonema\r\n- escrever pedido curto\r\n- participar em roleplay A2\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk kan maandag niet komen. Kunt u de afspraak verzetten? Kunt u mij een bevestiging sturen?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk kan maandag niet komen.\r\nKunt u de afspraak verzetten?\r\nWelke documenten moet ik meenemen?\r\nIk heb een probleem met mijn woning.\r\nKunt u mij een bevestiging sturen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-12';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `afspraak`\r\n\r\nTraducao PT: marcacao  \r\nTraducao EN: appointment  \r\nAudio nativo: `audio/A2-12/words/afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: `AF-spraak`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer afspraak com e.\r\n- EN: say appointment.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wil mijn afspraak verzetten.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspraak\r\nafspraak em bloco\r\nIk wil mijn afspraak verzetten.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afspraak` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspraak` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `documenten`\r\n\r\nTraducao PT: documentos  \r\nTraducao EN: documents  \r\nAudio nativo: `audio/A2-12/words/documenten.native.nl.mp3`  \r\nAproximacao inicial PT: `do-ku-MEN-ten`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `documenten`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer documentos PT.\r\n- EN: say documents.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWelke documenten heeft u nodig?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndocumenten\r\ndocumenten em bloco\r\nWelke documenten heeft u nodig?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `documenten` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `documenten` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `gezondheid`\r\n\r\nTraducao PT: saude  \r\nTraducao EN: health  \r\nAudio nativo: `audio/A2-12/words/gezondheid.native.nl.mp3`  \r\nAproximacao inicial PT: `ghu-ZONT-heid`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `gezondheid`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer saude em PT.\r\n- EN: say health.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGezondheid is belangrijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngezondheid\r\ngezondheid em bloco\r\nGezondheid is belangrijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `gezondheid` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `gezondheid` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `woning`\r\n\r\nTraducao PT: habitacao  \r\nTraducao EN: home/dwelling  \r\nAudio nativo: `audio/A2-12/words/woning.native.nl.mp3`  \r\nAproximacao inicial PT: `VOO-ning`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `woning`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer wonning.\r\n- EN: say home.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een probleem met mijn woning.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwoning\r\nwoning em bloco\r\nIk heb een probleem met mijn woning.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `woning` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `woning` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `werkgever`\r\n\r\nTraducao PT: empregador  \r\nTraducao EN: employer  \r\nAudio nativo: `audio/A2-12/words/werkgever.native.nl.mp3`  \r\nAproximacao inicial PT: `VERK-ghe-ver`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `werkgever`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer employer.\r\n- EN: say employer.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn werkgever belt mij.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwerkgever\r\nwerkgever em bloco\r\nMijn werkgever belt mij.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `werkgever` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `werkgever` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `telefoongesprek`\r\n\r\nTraducao PT: chamada telefonica  \r\nTraducao EN: phone call  \r\nAudio nativo: `audio/A2-12/words/telefoongesprek.native.nl.mp3`  \r\nAproximacao inicial PT: `te-le-FOON-ghesprek`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `telefoongesprek`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer telefone conversa.\r\n- EN: say phone call.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHet telefoongesprek is moeilijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntelefoongesprek\r\ntelefoongesprek em bloco\r\nHet telefoongesprek is moeilijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `telefoongesprek` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `telefoongesprek` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `email`\r\n\r\nTraducao PT: email  \r\nTraducao EN: email  \r\nAudio nativo: `audio/A2-12/words/email.native.nl.mp3`  \r\nAproximacao inicial PT: `EE-mail`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `email`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer email PT.\r\n- EN: say email English only.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk stuur een email.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nemail\r\nemail em bloco\r\nIk stuur een email.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `email` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `email` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `bevestiging`\r\n\r\nTraducao PT: confirmacao  \r\nTraducao EN: confirmation  \r\nAudio nativo: `audio/A2-12/words/bevestiging.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-VES-ti-ghing`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bevestiging`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer confirmacao.\r\n- EN: say confirmation.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een bevestiging nodig.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbevestiging\r\nbevestiging em bloco\r\nIk heb een bevestiging nodig.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bevestiging` isolado, numa frase lenta, numa frase natural e num mini dialogo. Deve reconhecer a palavra sem ler e indicar a funcao comunicativa.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bevestiging` em audio nativo, entende a funcao da palavra e usa-a numa frase A2 propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-12';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em tarefas praticas A2. O aluno deve reconhecer a forma em audio, usar em frase propria e adaptar a situacao:\r\n\r\n```text\r\nkunnen\r\nmoeten\r\nwillen\r\nhebben\r\nzijn\r\nbegrijpen\r\nherhalen\r\nbevestigen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A2-12';
