insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'B1-03', 'Futuro e planos', 'usar presente com tempo futuro', 2, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'B1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo B1 e compreender e produzir neerlandes funcional em textos, audios e interacoes mais longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"O aluno B1 precisa falar sobre planos de trabalho, consultas, estudo, familia e objetivos. O futuro em neerlandes e muitas vezes expresso com presente + tempo, `gaan` ou `zullen` em contextos especificos.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nDocent: Wat gaat u volgende maand doen?\r\nAluno: Ik ga meer Nederlands oefenen, omdat ik beter wil spreken.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- usar presente com tempo futuro\r\n- usar `gaan` para planos\r\n- usar `willen` para intencao\r\n- falar de objetivos\r\n- combinar compromissos futuros\r\n- entender diferenca basica entre `gaan` e `zullen`\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk ga meer Nederlands oefenen, omdat ik beter wil spreken.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nMorgen werk ik thuis.\r\nIk ga meer Nederlands oefenen.\r\nIk wil beter spreken.\r\nWe spreken volgende week af.\r\nIk zal u morgen bellen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `morgen`\r\n\r\nTraducao PT: amanha  \r\nTraducao EN: tomorrow  \r\nAudio nativo: `audio/B1-03/words/morgen.native.nl.mp3`  \r\nAproximacao inicial PT: `MOR-ghen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `morgen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer morgen como morning.\r\n- EN: say morning.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMorgen werk ik.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmorgen\r\nmorgen em bloco\r\nMorgen werk ik.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `morgen` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `morgen` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `volgende`\r\n\r\nTraducao PT: proximo/seguinte  \r\nTraducao EN: next  \r\nAudio nativo: `audio/B1-03/words/volgende.native.nl.mp3`  \r\nAproximacao inicial PT: `VOL-ghen-duh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `volgende`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer seguinte.\r\n- EN: say following.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nVolgende week.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvolgende\r\nvolgende em bloco\r\nVolgende week.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `volgende` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `volgende` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `plan`\r\n\r\nTraducao PT: plano  \r\nTraducao EN: plan  \r\nAudio nativo: `audio/B1-03/words/plan.native.nl.mp3`  \r\nAproximacao inicial PT: `plan`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `plan`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer plano.\r\n- EN: say plan English too long.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is uw plan?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nplan\r\nplan em bloco\r\nWat is uw plan?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `plan` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `plan` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `oefenen`\r\n\r\nTraducao PT: praticar  \r\nTraducao EN: to practice  \r\nAudio nativo: `audio/B1-03/words/oefenen.native.nl.mp3`  \r\nAproximacao inicial PT: `UU-fuh-nen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `oefenen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer oefenen sem arredondar.\r\n- EN: say often.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ga oefenen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\noefenen\r\noefenen em bloco\r\nIk ga oefenen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `oefenen` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `oefenen` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `verbeteren`\r\n\r\nTraducao PT: melhorar  \r\nTraducao EN: to improve  \r\nAudio nativo: `audio/B1-03/words/verbeteren.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-BEE-ter-en`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verbeteren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer melhorar.\r\n- EN: say improve.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wil mijn Nederlands verbeteren.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverbeteren\r\nverbeteren em bloco\r\nIk wil mijn Nederlands verbeteren.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verbeteren` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verbeteren` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `doel`\r\n\r\nTraducao PT: objetivo  \r\nTraducao EN: goal  \r\nAudio nativo: `audio/B1-03/words/doel.native.nl.mp3`  \r\nAproximacao inicial PT: `doel`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `doel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer doel como duel.\r\n- EN: say goal.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn doel is B1.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndoel\r\ndoel em bloco\r\nMijn doel is B1.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `doel` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `doel` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `afspreken`\r\n\r\nTraducao PT: combinar/marcar  \r\nTraducao EN: to arrange  \r\nAudio nativo: `audio/B1-03/words/afspreken.native.nl.mp3`  \r\nAproximacao inicial PT: `AF-spree-ken`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspreken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer marcar.\r\n- EN: say arrange.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWe spreken morgen af.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspreken\r\nafspreken em bloco\r\nWe spreken morgen af.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afspreken` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspreken` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `zal`\r\n\r\nTraducao PT: irei/vou em promessa  \r\nTraducao EN: will/shall  \r\nAudio nativo: `audio/B1-03/words/zal.native.nl.mp3`  \r\nAproximacao inicial PT: `zal`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `zal`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer sal.\r\n- EN: say shall.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk zal u bellen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nzal\r\nzal em bloco\r\nIk zal u bellen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `zal` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `zal` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em comunicacao B1: narrativa, explicacao, opiniao, pedido, consequencia e plano. O aluno deve usar os verbos em frases proprias e em respostas de varios turnos.\r\n\r\n```text\r\nhebben\r\nzijn\r\nworden\r\nkunnen\r\nmoeten\r\nwillen\r\ngaan\r\nuitleggen\r\nsamenvatten\r\nreageren\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Futuro funcional: `Morgen werk ik`, `Ik ga oefenen`, `Ik wil beter spreken`. `Zullen` aparece em promessas/propostas formais: `Ik zal u morgen bellen`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Morgen werk ik thuis.`\r\n\r\nTraducao PT: Amanha trabalho em casa.  \r\nTraducao EN: Tomorrow I work from home.  \r\nAudio nativo: `audio/B1-03/phrases/morgen-werk-ik-thuis.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPlano com presente.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMorgen / werk ik / thuis.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMorgen werk ik thuis.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nMorgen werk ik thuis.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nMorgen werk ''k thuis.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Morgen werk ik thuis.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer morgen ik werk.\r\n- EN: keep Tomorrow I work.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMorgen / werk ik / thuis.\r\nMorgen werk ik thuis.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 2\r\n\r\nFrase: `Ik ga meer Nederlands oefenen.`\r\n\r\nTraducao PT: Vou praticar mais neerlandes.  \r\nTraducao EN: I am going to practice more Dutch.  \r\nAudio nativo: `audio/B1-03/phrases/ik-ga-meer-nederlands-oefenen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPlano de estudo.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ga / meer Nederlands / oefenen.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ga meer Nederlands oefenen.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ga meer Nederlands oefenen.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ga meer Nederlands oefenen.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ga meer Nederlands oefenen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer praticar.\r\n- EN: say practice.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ga / meer Nederlands / oefenen.\r\nIk ga meer Nederlands oefenen.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 3\r\n\r\nFrase: `Ik wil beter spreken.`\r\n\r\nTraducao PT: Quero falar melhor.  \r\nTraducao EN: I want to speak better.  \r\nAudio nativo: `audio/B1-03/phrases/ik-wil-beter-spreken.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nObjetivo.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk wil / beter spreken.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk wil beter spreken.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk wil beter spreken.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Wil beter spreken.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik wil beter spreken.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer melhor falar ordem PT.\r\n- EN: say speak better.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk wil / beter spreken.\r\nIk wil beter spreken.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 4\r\n\r\nFrase: `We spreken volgende week af.`\r\n\r\nTraducao PT: Combinamos na proxima semana.  \r\nTraducao EN: We will meet/arrange next week.  \r\nAudio nativo: `audio/B1-03/phrases/we-spreken-volgende-week-af.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nCombinar encontro.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWe spreken / volgende week / af.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWe spreken volgende week af.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWe spreken volgende week af.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWe spreken volgende week af.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `We spreken volgende week af.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: esquecer af.\r\n- EN: say arrange.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWe spreken / volgende week / af.\r\nWe spreken volgende week af.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 5\r\n\r\nFrase: `Ik zal u morgen bellen.`\r\n\r\nTraducao PT: Ligo-lhe amanha.  \r\nTraducao EN: I will call you tomorrow.  \r\nAudio nativo: `audio/B1-03/phrases/ik-zal-u-morgen-bellen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPromessa formal.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk zal u / morgen bellen.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk zal u morgen bellen.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk zal u morgen bellen.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIk zal u morgen bellen.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik zal u morgen bellen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: usar zal para tudo.\r\n- EN: overuse will.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk zal u / morgen bellen.\r\nIk zal u morgen bellen.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir diretamente a ordem da frase portuguesa.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos profissionais ou academicos em pronuncia inglesa.\r\n- Evitar manter ordem inglesa em subordinadas neerlandesas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra, principalmente em verbos no passado, palavras profissionais e conectores.\r\n\r\n### Vogais longas e curtas\r\n\r\nManter contraste com apoio do audio nativo. Em B1, a fluencia nao pode apagar vogais importantes.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. Manter som claro, mas sem exagerar.\r\n\r\n### Reducoes naturais\r\n\r\nReconhecer reducoes em fala natural: `''t`, `''n`, `''k`, `d''r`, `z''n`, ligacoes com `u`, e formas fracas de palavras funcionais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao em respostas longas; respirar por blocos."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase natural, mini dialogo e resposta de 30-90 segundos. Em B1, a entoacao deve ajudar a organizar ideias: introducao, motivo, contraste, consequencia e conclusao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nMorgen / werk ik / thuis.\r\nIk ga / meer Nederlands / oefenen.\r\nIk wil / beter spreken.\r\nWe spreken / volgende week / af.\r\nIk zal u / morgen bellen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, d''r, z''n e ligacoes funcionais em fala natural.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Expandir a frase final com motivo, contraste ou consequencia.\r\n\r\n```text\r\nIk ga meer Nederlands oefenen, omdat ik beter wil spreken.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Falar a mesma ideia com informacao propria.\r\n8. Gravar uma resposta de 30-60 segundos e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave, reducoes e conectores.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: motivo, problema, consequencia, opiniao e proximo passo.\r\n\r\n### Excerto B1\r\n\r\nOuvir um excerto de 45-60 segundos e identificar ideia principal, dois detalhes e uma relacao logica.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar palavras funcionais, finais verbais e conectores depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ordenar palavras em frase principal e subordinada.\r\n3. Corrigir uma frase com ordem errada.\r\n4. Escrever um paragrafo de 5-6 linhas.\r\n5. Escrever uma resposta funcional: email, resumo, opiniao ou explicacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Resposta de 30-60 segundos com conectores.\r\n6. Mini roleplay com pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Kunt u uitleggen wat er aan de hand is?\r\nAluno: Morgen werk ik thuis.\r\nPessoa: Waarom is dat belangrijk?\r\nAluno: Ik ga meer Nederlands oefenen.\r\nPessoa: Wat gaat u nu doen?\r\nAluno: Ik ga meer Nederlands oefenen, omdat ik beter wil spreken.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o problema ou tema principal?\r\n- Que motivo ou consequencia foi explicado?\r\n- Que conector foi usado?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Trabalho ou servico formal\r\n\r\nO aluno explica a situacao, da motivo, pede informacao e confirma o proximo passo.\r\n\r\n### Roleplay 2 - Conversa social ou curso\r\n\r\nO aluno da opiniao, responde a pergunta de seguimento e reformula quando nao e entendido.\r\n\r\n### Roleplay 3 - Audio natural\r\n\r\nO aluno ouve uma resposta natural, resume o que entendeu e pede clarificacao de um detalhe."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em subordinadas.\r\n- Falar frases soltas sem conectores em tarefas B1."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. Em B1, o aluno deve:\r\n\r\n```text\r\nA. usar apenas frases memorizadas\r\nB. ligar ideias com conectores\r\nC. evitar textos e audios longos\r\n```\r\n\r\nResposta: B\r\n\r\n3. Numa subordinada com `omdat`, o verbo tende a:\r\n\r\n```text\r\nA. ficar no fim\r\nB. desaparecer\r\nC. ficar sempre no inicio\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender um detalhe em audio natural, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir clarificacao especifica\r\nC. mudar para portugues sempre\r\n```\r\n\r\nResposta: B\r\n\r\n5. O criterio oral B1 exige:\r\n\r\n```text\r\nA. resposta de uma palavra\r\nB. resposta organizada com motivo/consequencia\r\nC. apenas traducao\r\n```\r\n\r\nResposta: B"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nmorgen - amanha - tomorrow\r\nvolgende - proximo/seguinte - next\r\nplan - plano - plan\r\noefenen - praticar - to practice\r\nverbeteren - melhorar - to improve\r\ndoel - objetivo - goal\r\nafspreken - combinar/marcar - to arrange\r\nzal - irei/vou em promessa - will/shall\r\nMorgen werk ik thuis. - Amanha trabalho em casa. - Tomorrow I work from home.\r\nIk ga meer Nederlands oefenen. - Vou praticar mais neerlandes. - I am going to practice more Dutch.\r\nIk wil beter spreken. - Quero falar melhor. - I want to speak better.\r\nWe spreken volgende week af. - Combinamos na proxima semana. - We will meet/arrange next week.\r\nIk zal u morgen bellen. - Ligo-lhe amanha. - I will call you tomorrow.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases naturais\r\n3. mini dialogo\r\n4. excerto B1 de 45-60 segundos\r\n5. pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar ideia principal\r\n- identificar dois detalhes\r\n- reconhecer conector ou reducao\r\n- fazer shadowing de uma frase longa\r\n- responder oralmente a pergunta de seguimento\r\n- gravar resposta final de 30-60 segundos"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em frases proprias\r\n- ligar ideias com pelo menos dois conectores\r\n- compreender um mini dialogo natural\r\n- compreender a ideia principal de um excerto B1\r\n- escrever um paragrafo funcional curto\r\n- responder oralmente durante 30-60 segundos sem bloquear\r\n- fazer roleplay com pergunta de seguimento\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk ga meer Nederlands oefenen, omdat ik beter wil spreken.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'morgen', 'amanha', 'tomorrow', 'Na palavra `morgen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Morgen werk ik.', 1 from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'volgende', 'proximo/seguinte', 'next', 'Na palavra `volgende`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Volgende week.', 2 from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'plan', 'plano', 'plan', 'Na palavra `plan`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Wat is uw plan?', 3 from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'oefenen', 'praticar', 'to practice', 'Na palavra `oefenen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ga oefenen.', 4 from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'verbeteren', 'melhorar', 'to improve', 'Na palavra `verbeteren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik wil mijn Nederlands verbeteren.', 5 from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'doel', 'objetivo', 'goal', 'Na palavra `doel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn doel is B1.', 6 from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'afspreken', 'combinar/marcar', 'to arrange', 'Na palavra `afspreken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'We spreken morgen af.', 7 from lessons l where l.code = 'B1-03';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'zal', 'irei/vou em promessa', 'will/shall', 'Na palavra `zal`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik zal u bellen.', 8 from lessons l where l.code = 'B1-03';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Morgen werk ik thuis.', 'Amanha trabalho em casa.', 'Tomorrow I work from home.', 'Morgen / werk ik / thuis.', 'Morgen werk ik thuis.', 'Morgen werk ik thuis.', 'Morgen werk ''k thuis.', 'Na frase `Morgen werk ik thuis.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'B1-03';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ga meer Nederlands oefenen.', 'Vou praticar mais neerlandes.', 'I am going to practice more Dutch.', 'Ik ga / meer Nederlands / oefenen.', 'Ik ga meer Nederlands oefenen.', 'Ik ga meer Nederlands oefenen.', '''k Ga meer Nederlands oefenen.', 'Na frase `Ik ga meer Nederlands oefenen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'B1-03';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik wil beter spreken.', 'Quero falar melhor.', 'I want to speak better.', 'Ik wil / beter spreken.', 'Ik wil beter spreken.', 'Ik wil beter spreken.', '''k Wil beter spreken.', 'Na frase `Ik wil beter spreken.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'B1-03';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'We spreken volgende week af.', 'Combinamos na proxima semana.', 'We will meet/arrange next week.', 'We spreken / volgende week / af.', 'We spreken volgende week af.', 'We spreken volgende week af.', 'We spreken volgende week af.', 'Na frase `We spreken volgende week af.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'B1-03';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik zal u morgen bellen.', 'Ligo-lhe amanha.', 'I will call you tomorrow.', 'Ik zal u / morgen bellen.', 'Ik zal u morgen bellen.', 'Ik zal u morgen bellen.', 'Ik zal u morgen bellen.', 'Na frase `Ik zal u morgen bellen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'B1-03';
