insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'B1-04', 'Leitura pratica', 'identificar objetivo de um texto', 3, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'B1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo B1 e compreender e produzir neerlandes funcional em textos, audios e interacoes mais longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"B1 precisa ler emails, cartas, avisos, mensagens de escola/trabalho, instrucoes e informacao publica. O foco nao e literatura: e encontrar informacao, entender acao esperada e responder.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nBrief: U moet voor 15 juli reageren.\r\nAluno: Ik moet voor 15 juli reageren en een document meesturen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- identificar objetivo de um texto\r\n- encontrar datas e prazos\r\n- distinguir informacao principal e detalhe\r\n- entender instrucoes escritas\r\n- resumir texto curto\r\n- formular resposta simples\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nU moet voor 15 juli reageren en een kopie meesturen.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nU moet voor 15 juli reageren.\r\nStuur een kopie van uw document mee.\r\nIn deze brief staat belangrijke informatie.\r\nIk begrijp de belangrijkste punten.\r\nKunt u de brief samenvatten?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `brief`\r\n\r\nTraducao PT: carta  \r\nTraducao EN: letter  \r\nAudio nativo: `audio/B1-04/words/brief.native.nl.mp3`  \r\nAproximacao inicial PT: `brief`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `brief`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer briefe.\r\n- EN: say brief.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een brief ontvangen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbrief\r\nbrief em bloco\r\nIk heb een brief ontvangen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `brief` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `brief` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `bericht`\r\n\r\nTraducao PT: mensagem  \r\nTraducao EN: message  \r\nAudio nativo: `audio/B1-04/words/bericht.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-RIKHT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bericht`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bericht sem g.\r\n- EN: say message.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk lees het bericht.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbericht\r\nbericht em bloco\r\nIk lees het bericht.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bericht` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bericht` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `termijn`\r\n\r\nTraducao PT: prazo  \r\nTraducao EN: deadline/term  \r\nAudio nativo: `audio/B1-04/words/termijn.native.nl.mp3`  \r\nAproximacao inicial PT: `ter-MEIN`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `termijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer termino.\r\n- EN: say term.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe termijn is kort.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntermijn\r\ntermijn em bloco\r\nDe termijn is kort.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `termijn` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `termijn` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `reageren`\r\n\r\nTraducao PT: responder/reagir  \r\nTraducao EN: to respond  \r\nAudio nativo: `audio/B1-04/words/reageren.native.nl.mp3`  \r\nAproximacao inicial PT: `ree-aa-GHE-ren`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `reageren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer reagir.\r\n- EN: say react.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nU moet reageren.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nreageren\r\nreageren em bloco\r\nU moet reageren.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `reageren` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `reageren` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `meesturen`\r\n\r\nTraducao PT: enviar junto/anexar  \r\nTraducao EN: to send along  \r\nAudio nativo: `audio/B1-04/words/meesturen.native.nl.mp3`  \r\nAproximacao inicial PT: `MEE-stuu-ren`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `meesturen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer enviar junto literal.\r\n- EN: say send along.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nU moet een kopie meesturen.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmeesturen\r\nmeesturen em bloco\r\nU moet een kopie meesturen.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `meesturen` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `meesturen` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `kopie`\r\n\r\nTraducao PT: copia  \r\nTraducao EN: copy  \r\nAudio nativo: `audio/B1-04/words/kopie.native.nl.mp3`  \r\nAproximacao inicial PT: `KOO-pie`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kopie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer copia.\r\n- EN: say copy.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nStuur een kopie.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkopie\r\nkopie em bloco\r\nStuur een kopie.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kopie` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kopie` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `voor`\r\n\r\nTraducao PT: antes de/para  \r\nTraducao EN: before/for  \r\nAudio nativo: `audio/B1-04/words/voor.native.nl.mp3`  \r\nAproximacao inicial PT: `voor`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `voor`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer for.\r\n- EN: say for.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nVoor 15 juli.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvoor\r\nvoor em bloco\r\nVoor 15 juli.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `voor` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `voor` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `binnen`\r\n\r\nTraducao PT: dentro de  \r\nTraducao EN: within  \r\nAudio nativo: `audio/B1-04/words/binnen.native.nl.mp3`  \r\nAproximacao inicial PT: `BIN-nen`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `binnen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer binnen sem n.\r\n- EN: say within.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBinnen twee weken.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbinnen\r\nbinnen em bloco\r\nBinnen twee weken.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `binnen` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `binnen` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em comunicacao B1: narrativa, explicacao, opiniao, pedido, consequencia e plano. O aluno deve usar os verbos em frases proprias e em respostas de varios turnos.\r\n\r\n```text\r\nhebben\r\nzijn\r\nworden\r\nkunnen\r\nmoeten\r\nwillen\r\ngaan\r\nuitleggen\r\nsamenvatten\r\nreageren\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Leitura B1 usa conectores e instrucoes: `voor`, `na`, `binnen`, `omdat`, `daarom`, `u moet`, `wij vragen u`. O aluno aprende a mapear texto para acao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `U moet voor 15 juli reageren.`\r\n\r\nTraducao PT: Deve responder antes de 15 de julho.  \r\nTraducao EN: You must respond before July 15.  \r\nAudio nativo: `audio/B1-04/phrases/u-moet-voor-15-juli-reageren.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nLer prazo.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nU moet / voor 15 juli / reageren.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nU moet voor 15 juli reageren.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nU moet voor 15 juli reageren.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nU moet voor 15 juli reageren.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `U moet voor 15 juli reageren.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: confundir voor com por.\r\n- EN: say before.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nU moet / voor 15 juli / reageren.\r\nU moet voor 15 juli reageren.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 2\r\n\r\nFrase: `Stuur een kopie van uw document mee.`\r\n\r\nTraducao PT: Envie uma copia do seu documento junto.  \r\nTraducao EN: Send a copy of your document along.  \r\nAudio nativo: `audio/B1-04/phrases/stuur-een-kopie-van-uw-document-mee.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nInstrucao escrita.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nStuur / een kopie / van uw document / mee.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nStuur een kopie van uw document mee.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nStuur ''n kopie van uw document mee.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nStuur ''n kopie van uw document mee.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Stuur een kopie van uw document mee.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: esquecer mee.\r\n- EN: say send copy.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nStuur / een kopie / van uw document / mee.\r\nStuur een kopie van uw document mee.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 3\r\n\r\nFrase: `In deze brief staat belangrijke informatie.`\r\n\r\nTraducao PT: Nesta carta ha informacao importante.  \r\nTraducao EN: This letter contains important information.  \r\nAudio nativo: `audio/B1-04/phrases/in-deze-brief-staat-belangrijke-informatie.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nIdentificar funcao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIn deze brief / staat belangrijke informatie.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIn deze brief staat belangrijke informatie.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIn deze brief staat belangrijke informatie.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIn deze brief staat belangrijke informatie.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `In deze brief staat belangrijke informatie.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir esta carta esta.\r\n- EN: say contains.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIn deze brief / staat belangrijke informatie.\r\nIn deze brief staat belangrijke informatie.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 4\r\n\r\nFrase: `Ik begrijp de belangrijkste punten.`\r\n\r\nTraducao PT: Entendo os pontos principais.  \r\nTraducao EN: I understand the main points.  \r\nAudio nativo: `audio/B1-04/phrases/ik-begrijp-de-belangrijkste-punten.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nResumo.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk begrijp / de belangrijkste punten.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk begrijp de belangrijkste punten.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk begrijp de belangrijkste punten.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Begrijp de belangrijkste punten.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik begrijp de belangrijkste punten.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer pontos importante.\r\n- EN: say main points.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk begrijp / de belangrijkste punten.\r\nIk begrijp de belangrijkste punten.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 5\r\n\r\nFrase: `Kunt u de brief samenvatten?`\r\n\r\nTraducao PT: Pode resumir a carta?  \r\nTraducao EN: Can you summarize the letter?  \r\nAudio nativo: `audio/B1-04/phrases/kunt-u-de-brief-samenvatten.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir ajuda.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u / de brief / samenvatten?\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u de brief samenvatten?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKuntu de brief samenvatten?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u de brief samenvatten?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u de brief samenvatten?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer resumo.\r\n- EN: say summarize.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u / de brief / samenvatten?\r\nKunt u de brief samenvatten?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir diretamente a ordem da frase portuguesa.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos profissionais ou academicos em pronuncia inglesa.\r\n- Evitar manter ordem inglesa em subordinadas neerlandesas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra, principalmente em verbos no passado, palavras profissionais e conectores.\r\n\r\n### Vogais longas e curtas\r\n\r\nManter contraste com apoio do audio nativo. Em B1, a fluencia nao pode apagar vogais importantes.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. Manter som claro, mas sem exagerar.\r\n\r\n### Reducoes naturais\r\n\r\nReconhecer reducoes em fala natural: `''t`, `''n`, `''k`, `d''r`, `z''n`, ligacoes com `u`, e formas fracas de palavras funcionais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao em respostas longas; respirar por blocos."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase natural, mini dialogo e resposta de 30-90 segundos. Em B1, a entoacao deve ajudar a organizar ideias: introducao, motivo, contraste, consequencia e conclusao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nU moet / voor 15 juli / reageren.\r\nStuur / een kopie / van uw document / mee.\r\nIn deze brief / staat belangrijke informatie.\r\nIk begrijp / de belangrijkste punten.\r\nKunt u / de brief / samenvatten?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, d''r, z''n e ligacoes funcionais em fala natural.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Expandir a frase final com motivo, contraste ou consequencia.\r\n\r\n```text\r\nU moet voor 15 juli reageren en een kopie meesturen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Falar a mesma ideia com informacao propria.\r\n8. Gravar uma resposta de 30-60 segundos e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave, reducoes e conectores.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: motivo, problema, consequencia, opiniao e proximo passo.\r\n\r\n### Excerto B1\r\n\r\nOuvir um excerto de 45-60 segundos e identificar ideia principal, dois detalhes e uma relacao logica.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar palavras funcionais, finais verbais e conectores depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ordenar palavras em frase principal e subordinada.\r\n3. Corrigir uma frase com ordem errada.\r\n4. Escrever um paragrafo de 5-6 linhas.\r\n5. Escrever uma resposta funcional: email, resumo, opiniao ou explicacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Resposta de 30-60 segundos com conectores.\r\n6. Mini roleplay com pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Kunt u uitleggen wat er aan de hand is?\r\nAluno: U moet voor 15 juli reageren.\r\nPessoa: Waarom is dat belangrijk?\r\nAluno: Stuur een kopie van uw document mee.\r\nPessoa: Wat gaat u nu doen?\r\nAluno: U moet voor 15 juli reageren en een kopie meesturen.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o problema ou tema principal?\r\n- Que motivo ou consequencia foi explicado?\r\n- Que conector foi usado?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Trabalho ou servico formal\r\n\r\nO aluno explica a situacao, da motivo, pede informacao e confirma o proximo passo.\r\n\r\n### Roleplay 2 - Conversa social ou curso\r\n\r\nO aluno da opiniao, responde a pergunta de seguimento e reformula quando nao e entendido.\r\n\r\n### Roleplay 3 - Audio natural\r\n\r\nO aluno ouve uma resposta natural, resume o que entendeu e pede clarificacao de um detalhe."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em subordinadas.\r\n- Falar frases soltas sem conectores em tarefas B1."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. Em B1, o aluno deve:\r\n\r\n```text\r\nA. usar apenas frases memorizadas\r\nB. ligar ideias com conectores\r\nC. evitar textos e audios longos\r\n```\r\n\r\nResposta: B\r\n\r\n3. Numa subordinada com `omdat`, o verbo tende a:\r\n\r\n```text\r\nA. ficar no fim\r\nB. desaparecer\r\nC. ficar sempre no inicio\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender um detalhe em audio natural, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir clarificacao especifica\r\nC. mudar para portugues sempre\r\n```\r\n\r\nResposta: B\r\n\r\n5. O criterio oral B1 exige:\r\n\r\n```text\r\nA. resposta de uma palavra\r\nB. resposta organizada com motivo/consequencia\r\nC. apenas traducao\r\n```\r\n\r\nResposta: B"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nbrief - carta - letter\r\nbericht - mensagem - message\r\ntermijn - prazo - deadline/term\r\nreageren - responder/reagir - to respond\r\nmeesturen - enviar junto/anexar - to send along\r\nkopie - copia - copy\r\nvoor - antes de/para - before/for\r\nbinnen - dentro de - within\r\nU moet voor 15 juli reageren. - Deve responder antes de 15 de julho. - You must respond before July 15.\r\nStuur een kopie van uw document mee. - Envie uma copia do seu documento junto. - Send a copy of your document along.\r\nIn deze brief staat belangrijke informatie. - Nesta carta ha informacao importante. - This letter contains important information.\r\nIk begrijp de belangrijkste punten. - Entendo os pontos principais. - I understand the main points.\r\nKunt u de brief samenvatten? - Pode resumir a carta? - Can you summarize the letter?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases naturais\r\n3. mini dialogo\r\n4. excerto B1 de 45-60 segundos\r\n5. pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar ideia principal\r\n- identificar dois detalhes\r\n- reconhecer conector ou reducao\r\n- fazer shadowing de uma frase longa\r\n- responder oralmente a pergunta de seguimento\r\n- gravar resposta final de 30-60 segundos"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em frases proprias\r\n- ligar ideias com pelo menos dois conectores\r\n- compreender um mini dialogo natural\r\n- compreender a ideia principal de um excerto B1\r\n- escrever um paragrafo funcional curto\r\n- responder oralmente durante 30-60 segundos sem bloquear\r\n- fazer roleplay com pergunta de seguimento\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nU moet voor 15 juli reageren en een kopie meesturen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'brief', 'carta', 'letter', 'Na palavra `brief`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb een brief ontvangen.', 1 from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'bericht', 'mensagem', 'message', 'Na palavra `bericht`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik lees het bericht.', 2 from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'termijn', 'prazo', 'deadline/term', 'Na palavra `termijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De termijn is kort.', 3 from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'reageren', 'responder/reagir', 'to respond', 'Na palavra `reageren`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'U moet reageren.', 4 from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'meesturen', 'enviar junto/anexar', 'to send along', 'Na palavra `meesturen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'U moet een kopie meesturen.', 5 from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'kopie', 'copia', 'copy', 'Na palavra `kopie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Stuur een kopie.', 6 from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'voor', 'antes de/para', 'before/for', 'Na palavra `voor`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Voor 15 juli.', 7 from lessons l where l.code = 'B1-04';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'binnen', 'dentro de', 'within', 'Na palavra `binnen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Binnen twee weken.', 8 from lessons l where l.code = 'B1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'U moet voor 15 juli reageren.', 'Deve responder antes de 15 de julho.', 'You must respond before July 15.', 'U moet / voor 15 juli / reageren.', 'U moet voor 15 juli reageren.', 'U moet voor 15 juli reageren.', 'U moet voor 15 juli reageren.', 'Na frase `U moet voor 15 juli reageren.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'B1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Stuur een kopie van uw document mee.', 'Envie uma copia do seu documento junto.', 'Send a copy of your document along.', 'Stuur / een kopie / van uw document / mee.', 'Stuur een kopie van uw document mee.', 'Stuur ''n kopie van uw document mee.', 'Stuur ''n kopie van uw document mee.', 'Na frase `Stuur een kopie van uw document mee.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'B1-04';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'In deze brief staat belangrijke informatie.', 'Nesta carta ha informacao importante.', 'This letter contains important information.', 'In deze brief / staat belangrijke informatie.', 'In deze brief staat belangrijke informatie.', 'In deze brief staat belangrijke informatie.', 'In deze brief staat belangrijke informatie.', 'Na frase `In deze brief staat belangrijke informatie.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'B1-04';
