insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'B1-07', 'Comunicacao no trabalho', 'dar estado de uma tarefa', 6, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'B1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo B1 e compreender e produzir neerlandes funcional em textos, audios e interacoes mais longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"No trabalho, B1 significa entender instrucoes mais longas, explicar progresso, sinalizar problemas, pedir prioridade e comunicar disponibilidade de forma profissional.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nLeidinggevende: Hoe gaat het met de taak?\r\nAluno: Ik ben ermee bezig, maar ik heb nog informatie nodig.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- dar estado de uma tarefa\r\n- pedir prioridade\r\n- explicar problema\r\n- pedir informacao\r\n- participar em breve alinhamento\r\n- usar tom profissional\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk ben bezig met de taak, maar ik heb nog informatie nodig.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk ben bezig met de taak.\r\nIk heb nog informatie nodig.\r\nWat heeft prioriteit?\r\nIk kan dit vandaag afronden.\r\nEr is een probleem met de planning.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `taak`\r\n\r\nTraducao PT: tarefa  \r\nTraducao EN: task  \r\nAudio nativo: `audio/B1-07/words/taak.native.nl.mp3`  \r\nAproximacao inicial PT: `taak`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `taak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer taka.\r\n- EN: say task.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe taak is klaar.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntaak\r\ntaak em bloco\r\nDe taak is klaar.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `taak` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `taak` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `prioriteit`\r\n\r\nTraducao PT: prioridade  \r\nTraducao EN: priority  \r\nAudio nativo: `audio/B1-07/words/prioriteit.native.nl.mp3`  \r\nAproximacao inicial PT: `pri-o-ri-TEIT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `prioriteit`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer prioridade.\r\n- EN: say priority.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat heeft prioriteit?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nprioriteit\r\nprioriteit em bloco\r\nWat heeft prioriteit?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `prioriteit` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `prioriteit` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `informatie`\r\n\r\nTraducao PT: informacao  \r\nTraducao EN: information  \r\nAudio nativo: `audio/B1-07/words/informatie.native.nl.mp3`  \r\nAproximacao inicial PT: `in-for-MAA-tsie`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `informatie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer informacao.\r\n- EN: say information.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb informatie nodig.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ninformatie\r\ninformatie em bloco\r\nIk heb informatie nodig.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `informatie` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `informatie` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `afronden`\r\n\r\nTraducao PT: concluir/finalizar  \r\nTraducao EN: to finish  \r\nAudio nativo: `audio/B1-07/words/afronden.native.nl.mp3`  \r\nAproximacao inicial PT: `AF-ron-den`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afronden`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer finalizar.\r\n- EN: say round off.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk rond de taak af.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafronden\r\nafronden em bloco\r\nIk rond de taak af.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afronden` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afronden` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `overleg`\r\n\r\nTraducao PT: reuniao/alinhamento  \r\nTraducao EN: consultation/meeting  \r\nAudio nativo: `audio/B1-07/words/overleg.native.nl.mp3`  \r\nAproximacao inicial PT: `OO-ver-lekh`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `overleg`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer overleg sem g.\r\n- EN: say meeting.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWe hebben overleg.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\noverleg\r\noverleg em bloco\r\nWe hebben overleg.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `overleg` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `overleg` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `deadline`\r\n\r\nTraducao PT: prazo final  \r\nTraducao EN: deadline  \r\nAudio nativo: `audio/B1-07/words/deadline.native.nl.mp3`  \r\nAproximacao inicial PT: `DED-lain` audio-first  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `deadline`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer deadline ingles sempre.\r\n- EN: over-English.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe deadline is vrijdag.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndeadline\r\ndeadline em bloco\r\nDe deadline is vrijdag.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `deadline` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `deadline` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `beschikbaar`\r\n\r\nTraducao PT: disponivel  \r\nTraducao EN: available  \r\nAudio nativo: `audio/B1-07/words/beschikbaar.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-SKHI-kbaar`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `beschikbaar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer disponivel.\r\n- EN: say available.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben beschikbaar.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbeschikbaar\r\nbeschikbaar em bloco\r\nIk ben beschikbaar.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `beschikbaar` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `beschikbaar` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `probleem`\r\n\r\nTraducao PT: problema  \r\nTraducao EN: problem  \r\nAudio nativo: `audio/B1-07/words/probleem.native.nl.mp3`  \r\nAproximacao inicial PT: `pro-BLEEM`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `probleem`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer problema.\r\n- EN: say problem.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nEr is een probleem.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nprobleem\r\nprobleem em bloco\r\nEr is een probleem.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `probleem` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `probleem` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em comunicacao B1: narrativa, explicacao, opiniao, pedido, consequencia e plano. O aluno deve usar os verbos em frases proprias e em respostas de varios turnos.\r\n\r\n```text\r\nhebben\r\nzijn\r\nworden\r\nkunnen\r\nmoeten\r\nwillen\r\ngaan\r\nuitleggen\r\nsamenvatten\r\nreageren\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Estruturas de trabalho: `Ik ben bezig met...`, `Ik heb ... nodig`, `Wat heeft prioriteit?`, `Ik kan dit vandaag afronden`. Conectores: `maar`, `omdat`, `daarom`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik ben bezig met de taak.`\r\n\r\nTraducao PT: Estou a tratar da tarefa.  \r\nTraducao EN: I am working on the task.  \r\nAudio nativo: `audio/B1-07/phrases/ik-ben-bezig-met-de-taak.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nEstado tarefa.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ben bezig / met de taak.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ben bezig met de taak.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ben bezig met de taak.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ben bezig met de taak.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ben bezig met de taak.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ocupado literal.\r\n- EN: say busy with.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ben bezig / met de taak.\r\nIk ben bezig met de taak.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 2\r\n\r\nFrase: `Ik heb nog informatie nodig.`\r\n\r\nTraducao PT: Ainda preciso de informacao.  \r\nTraducao EN: I still need information.  \r\nAudio nativo: `audio/B1-07/phrases/ik-heb-nog-informatie-nodig.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir dados.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk heb nog / informatie nodig.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk heb nog informatie nodig.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk heb nog informatie nodig.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Heb nog informatie nodig.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik heb nog informatie nodig.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer preciso de.\r\n- EN: say need info.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk heb nog / informatie nodig.\r\nIk heb nog informatie nodig.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 3\r\n\r\nFrase: `Wat heeft prioriteit?`\r\n\r\nTraducao PT: O que tem prioridade?  \r\nTraducao EN: What has priority?  \r\nAudio nativo: `audio/B1-07/phrases/wat-heeft-prioriteit.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nOrganizar trabalho.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWat heeft / prioriteit?\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWat heeft prioriteit?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWat heeft prioriteit?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWat heeft prioriteit?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Wat heeft prioriteit?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer prioridade PT.\r\n- EN: say priority.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWat heeft / prioriteit?\r\nWat heeft prioriteit?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 4\r\n\r\nFrase: `Ik kan dit vandaag afronden.`\r\n\r\nTraducao PT: Posso concluir isto hoje.  \r\nTraducao EN: I can finish this today.  \r\nAudio nativo: `audio/B1-07/phrases/ik-kan-dit-vandaag-afronden.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nCompromisso.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk kan dit / vandaag afronden.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk kan dit vandaag afronden.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk kan dit vandaag afronden.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Kan dit vandaag afronden.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik kan dit vandaag afronden.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer finalizar.\r\n- EN: say finish.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk kan dit / vandaag afronden.\r\nIk kan dit vandaag afronden.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 5\r\n\r\nFrase: `Er is een probleem met de planning.`\r\n\r\nTraducao PT: Ha um problema com o planeamento.  \r\nTraducao EN: There is a problem with the planning.  \r\nAudio nativo: `audio/B1-07/phrases/er-is-een-probleem-met-de-planning.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nSinalizar problema.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nEr is een probleem / met de planning.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nEr is een probleem met de planning.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nEr is ''n probleem met de planning.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nEr is ''n probleem met de planning.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Er is een probleem met de planning.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer plano.\r\n- EN: say schedule.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nEr is een probleem / met de planning.\r\nEr is een probleem met de planning.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir diretamente a ordem da frase portuguesa.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos profissionais ou academicos em pronuncia inglesa.\r\n- Evitar manter ordem inglesa em subordinadas neerlandesas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra, principalmente em verbos no passado, palavras profissionais e conectores.\r\n\r\n### Vogais longas e curtas\r\n\r\nManter contraste com apoio do audio nativo. Em B1, a fluencia nao pode apagar vogais importantes.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. Manter som claro, mas sem exagerar.\r\n\r\n### Reducoes naturais\r\n\r\nReconhecer reducoes em fala natural: `''t`, `''n`, `''k`, `d''r`, `z''n`, ligacoes com `u`, e formas fracas de palavras funcionais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao em respostas longas; respirar por blocos."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase natural, mini dialogo e resposta de 30-90 segundos. Em B1, a entoacao deve ajudar a organizar ideias: introducao, motivo, contraste, consequencia e conclusao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk ben bezig / met de taak.\r\nIk heb nog / informatie nodig.\r\nWat heeft / prioriteit?\r\nIk kan dit / vandaag afronden.\r\nEr is een probleem / met de planning.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, d''r, z''n e ligacoes funcionais em fala natural.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Expandir a frase final com motivo, contraste ou consequencia.\r\n\r\n```text\r\nIk ben bezig met de taak, maar ik heb nog informatie nodig.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Falar a mesma ideia com informacao propria.\r\n8. Gravar uma resposta de 30-60 segundos e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave, reducoes e conectores.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: motivo, problema, consequencia, opiniao e proximo passo.\r\n\r\n### Excerto B1\r\n\r\nOuvir um excerto de 45-60 segundos e identificar ideia principal, dois detalhes e uma relacao logica.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar palavras funcionais, finais verbais e conectores depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ordenar palavras em frase principal e subordinada.\r\n3. Corrigir uma frase com ordem errada.\r\n4. Escrever um paragrafo de 5-6 linhas.\r\n5. Escrever uma resposta funcional: email, resumo, opiniao ou explicacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Resposta de 30-60 segundos com conectores.\r\n6. Mini roleplay com pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Kunt u uitleggen wat er aan de hand is?\r\nAluno: Ik ben bezig met de taak.\r\nPessoa: Waarom is dat belangrijk?\r\nAluno: Ik heb nog informatie nodig.\r\nPessoa: Wat gaat u nu doen?\r\nAluno: Ik ben bezig met de taak, maar ik heb nog informatie nodig.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o problema ou tema principal?\r\n- Que motivo ou consequencia foi explicado?\r\n- Que conector foi usado?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Trabalho ou servico formal\r\n\r\nO aluno explica a situacao, da motivo, pede informacao e confirma o proximo passo.\r\n\r\n### Roleplay 2 - Conversa social ou curso\r\n\r\nO aluno da opiniao, responde a pergunta de seguimento e reformula quando nao e entendido.\r\n\r\n### Roleplay 3 - Audio natural\r\n\r\nO aluno ouve uma resposta natural, resume o que entendeu e pede clarificacao de um detalhe."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em subordinadas.\r\n- Falar frases soltas sem conectores em tarefas B1."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. Em B1, o aluno deve:\r\n\r\n```text\r\nA. usar apenas frases memorizadas\r\nB. ligar ideias com conectores\r\nC. evitar textos e audios longos\r\n```\r\n\r\nResposta: B\r\n\r\n3. Numa subordinada com `omdat`, o verbo tende a:\r\n\r\n```text\r\nA. ficar no fim\r\nB. desaparecer\r\nC. ficar sempre no inicio\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender um detalhe em audio natural, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir clarificacao especifica\r\nC. mudar para portugues sempre\r\n```\r\n\r\nResposta: B\r\n\r\n5. O criterio oral B1 exige:\r\n\r\n```text\r\nA. resposta de uma palavra\r\nB. resposta organizada com motivo/consequencia\r\nC. apenas traducao\r\n```\r\n\r\nResposta: B"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\ntaak - tarefa - task\r\nprioriteit - prioridade - priority\r\ninformatie - informacao - information\r\nafronden - concluir/finalizar - to finish\r\noverleg - reuniao/alinhamento - consultation/meeting\r\ndeadline - prazo final - deadline\r\nbeschikbaar - disponivel - available\r\nprobleem - problema - problem\r\nIk ben bezig met de taak. - Estou a tratar da tarefa. - I am working on the task.\r\nIk heb nog informatie nodig. - Ainda preciso de informacao. - I still need information.\r\nWat heeft prioriteit? - O que tem prioridade? - What has priority?\r\nIk kan dit vandaag afronden. - Posso concluir isto hoje. - I can finish this today.\r\nEr is een probleem met de planning. - Ha um problema com o planeamento. - There is a problem with the planning.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases naturais\r\n3. mini dialogo\r\n4. excerto B1 de 45-60 segundos\r\n5. pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar ideia principal\r\n- identificar dois detalhes\r\n- reconhecer conector ou reducao\r\n- fazer shadowing de uma frase longa\r\n- responder oralmente a pergunta de seguimento\r\n- gravar resposta final de 30-60 segundos"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em frases proprias\r\n- ligar ideias com pelo menos dois conectores\r\n- compreender um mini dialogo natural\r\n- compreender a ideia principal de um excerto B1\r\n- escrever um paragrafo funcional curto\r\n- responder oralmente durante 30-60 segundos sem bloquear\r\n- fazer roleplay com pergunta de seguimento\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk ben bezig met de taak, maar ik heb nog informatie nodig.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'taak', 'tarefa', 'task', 'Na palavra `taak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De taak is klaar.', 1 from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'prioriteit', 'prioridade', 'priority', 'Na palavra `prioriteit`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Wat heeft prioriteit?', 2 from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'informatie', 'informacao', 'information', 'Na palavra `informatie`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik heb informatie nodig.', 3 from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'afronden', 'concluir/finalizar', 'to finish', 'Na palavra `afronden`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik rond de taak af.', 4 from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'overleg', 'reuniao/alinhamento', 'consultation/meeting', 'Na palavra `overleg`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'We hebben overleg.', 5 from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'deadline', 'prazo final', 'deadline', 'Na palavra `deadline`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De deadline is vrijdag.', 6 from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'beschikbaar', 'disponivel', 'available', 'Na palavra `beschikbaar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ben beschikbaar.', 7 from lessons l where l.code = 'B1-07';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'probleem', 'problema', 'problem', 'Na palavra `probleem`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Er is een probleem.', 8 from lessons l where l.code = 'B1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ben bezig met de taak.', 'Estou a tratar da tarefa.', 'I am working on the task.', 'Ik ben bezig / met de taak.', 'Ik ben bezig met de taak.', 'Ik ben bezig met de taak.', '''k Ben bezig met de taak.', 'Na frase `Ik ben bezig met de taak.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'B1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik heb nog informatie nodig.', 'Ainda preciso de informacao.', 'I still need information.', 'Ik heb nog / informatie nodig.', 'Ik heb nog informatie nodig.', 'Ik heb nog informatie nodig.', '''k Heb nog informatie nodig.', 'Na frase `Ik heb nog informatie nodig.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'B1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Wat heeft prioriteit?', 'O que tem prioridade?', 'What has priority?', 'Wat heeft / prioriteit?', 'Wat heeft prioriteit?', 'Wat heeft prioriteit?', 'Wat heeft prioriteit?', 'Na frase `Wat heeft prioriteit?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'B1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik kan dit vandaag afronden.', 'Posso concluir isto hoje.', 'I can finish this today.', 'Ik kan dit / vandaag afronden.', 'Ik kan dit vandaag afronden.', 'Ik kan dit vandaag afronden.', '''k Kan dit vandaag afronden.', 'Na frase `Ik kan dit vandaag afronden.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'B1-07';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Er is een probleem met de planning.', 'Ha um problema com o planeamento.', 'There is a problem with the planning.', 'Er is een probleem / met de planning.', 'Er is een probleem met de planning.', 'Er is ''n probleem met de planning.', 'Er is ''n probleem met de planning.', 'Na frase `Er is een probleem met de planning.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'B1-07';
