insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'B1-08', 'Opinioes e argumentos', 'dar opiniao com `ik vind`', 7, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'B1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo B1 e compreender e produzir neerlandes funcional em textos, audios e interacoes mais longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"B1 exige participar em conversas com opiniao: no trabalho, em cursos, em reunioes simples e em situacoes sociais. O aluno aprende a expressar posicao sem soar rude.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nCollega: Wat vindt u van dit plan?\r\nAluno: Ik vind het een goed plan, omdat het duidelijk is.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- dar opiniao com `ik vind`\r\n- justificar com `omdat`\r\n- concordar e discordar educadamente\r\n- comparar opcoes\r\n- usar conectores\r\n- responder a opiniao de outra pessoa\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk vind het een goed plan, omdat het duidelijk is.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk vind het een goed plan.\r\nIk ben het daarmee eens.\r\nIk ben het niet helemaal eens.\r\nEen voordeel is dat het duidelijk is.\r\nAan de andere kant kost het meer tijd.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `mening`\r\n\r\nTraducao PT: opiniao  \r\nTraducao EN: opinion  \r\nAudio nativo: `audio/B1-08/words/mening.native.nl.mp3`  \r\nAproximacao inicial PT: `MEE-ning`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `mening`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer opiniao.\r\n- EN: say meaning.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is uw mening?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmening\r\nmening em bloco\r\nWat is uw mening?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `mening` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `mening` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `eens`\r\n\r\nTraducao PT: de acordo  \r\nTraducao EN: agree  \r\nAudio nativo: `audio/B1-08/words/eens.native.nl.mp3`  \r\nAproximacao inicial PT: `eens`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `eens`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer eens como em.\r\n- EN: say once.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben het eens.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\neens\r\neens em bloco\r\nIk ben het eens.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `eens` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `eens` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `oneens`\r\n\r\nTraducao PT: em desacordo  \r\nTraducao EN: disagree  \r\nAudio nativo: `audio/B1-08/words/oneens.native.nl.mp3`  \r\nAproximacao inicial PT: `on-EENS`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `oneens`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer oneens errado.\r\n- EN: say one.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben het oneens.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\noneens\r\noneens em bloco\r\nIk ben het oneens.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `oneens` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `oneens` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `duidelijk`\r\n\r\nTraducao PT: claro  \r\nTraducao EN: clear  \r\nAudio nativo: `audio/B1-08/words/duidelijk.native.nl.mp3`  \r\nAproximacao inicial PT: `DUI-duh-luk`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `duidelijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer claro.\r\n- EN: say clearly.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHet plan is duidelijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nduidelijk\r\nduidelijk em bloco\r\nHet plan is duidelijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `duidelijk` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `duidelijk` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `voordeel`\r\n\r\nTraducao PT: vantagem  \r\nTraducao EN: advantage  \r\nAudio nativo: `audio/B1-08/words/voordeel.native.nl.mp3`  \r\nAproximacao inicial PT: `VOOR-deel`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `voordeel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer vantagem.\r\n- EN: say advantage.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nEen voordeel is...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvoordeel\r\nvoordeel em bloco\r\nEen voordeel is...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `voordeel` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `voordeel` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `nadeel`\r\n\r\nTraducao PT: desvantagem  \r\nTraducao EN: disadvantage  \r\nAudio nativo: `audio/B1-08/words/nadeel.native.nl.mp3`  \r\nAproximacao inicial PT: `NAA-deel`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `nadeel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer desvantagem.\r\n- EN: say disadvantage.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nEen nadeel is...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnadeel\r\nnadeel em bloco\r\nEen nadeel is...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `nadeel` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `nadeel` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `vergelijking`\r\n\r\nTraducao PT: comparacao  \r\nTraducao EN: comparison  \r\nAudio nativo: `audio/B1-08/words/vergelijking.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-GHE-lij-king`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vergelijking`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer comparacao.\r\n- EN: say comparison.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIn vergelijking met...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvergelijking\r\nvergelijking em bloco\r\nIn vergelijking met...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `vergelijking` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vergelijking` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `argument`\r\n\r\nTraducao PT: argumento  \r\nTraducao EN: argument  \r\nAudio nativo: `audio/B1-08/words/argument.native.nl.mp3`  \r\nAproximacao inicial PT: `ar-ghu-MENT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `argument`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer argumento.\r\n- EN: say argument.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn argument is...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nargument\r\nargument em bloco\r\nMijn argument is...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `argument` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `argument` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em comunicacao B1: narrativa, explicacao, opiniao, pedido, consequencia e plano. O aluno deve usar os verbos em frases proprias e em respostas de varios turnos.\r\n\r\n```text\r\nhebben\r\nzijn\r\nworden\r\nkunnen\r\nmoeten\r\nwillen\r\ngaan\r\nuitleggen\r\nsamenvatten\r\nreageren\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"`Ik vind dat...`; `Ik ben het eens met...`; `Ik ben het niet helemaal eens, omdat...`. Subordinada com `omdat` mantem verbo no fim."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik vind het een goed plan.`\r\n\r\nTraducao PT: Acho que e um bom plano.  \r\nTraducao EN: I think it is a good plan.  \r\nAudio nativo: `audio/B1-08/phrases/ik-vind-het-een-goed-plan.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDar opiniao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk vind / het een goed plan.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk vind het een goed plan.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk vind ''t een goed plan.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Vind ''t een goed plan.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik vind het een goed plan.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer eu acho literal com ordem errada.\r\n- EN: say I find.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk vind / het een goed plan.\r\nIk vind het een goed plan.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 2\r\n\r\nFrase: `Ik ben het daarmee eens.`\r\n\r\nTraducao PT: Estou de acordo com isso.  \r\nTraducao EN: I agree with that.  \r\nAudio nativo: `audio/B1-08/phrases/ik-ben-het-daarmee-eens.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nConcordar.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ben het / daarmee eens.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ben het daarmee eens.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ben ''t daarmee eens.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ben ''t daarmee eens.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ben het daarmee eens.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: usar concordo direto.\r\n- EN: say agree.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ben het / daarmee eens.\r\nIk ben het daarmee eens.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 3\r\n\r\nFrase: `Ik ben het niet helemaal eens.`\r\n\r\nTraducao PT: Nao concordo totalmente.  \r\nTraducao EN: I do not completely agree.  \r\nAudio nativo: `audio/B1-08/phrases/ik-ben-het-niet-helemaal-eens.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDiscordar educadamente.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ben het / niet helemaal eens.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ben het niet helemaal eens.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ben ''t niet helemaal eens.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ben ''t niet helemaal eens.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ben het niet helemaal eens.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: soar rude demais.\r\n- EN: say disagree bluntly.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ben het / niet helemaal eens.\r\nIk ben het niet helemaal eens.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 4\r\n\r\nFrase: `Een voordeel is dat het duidelijk is.`\r\n\r\nTraducao PT: Uma vantagem e que e claro.  \r\nTraducao EN: An advantage is that it is clear.  \r\nAudio nativo: `audio/B1-08/phrases/een-voordeel-is-dat-het-duidelijk-is.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nArgumentar.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nEen voordeel is / dat het duidelijk is.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nEen voordeel is dat het duidelijk is.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nEen voordeel is dat het duidelijk is.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''n Voordeel is dat ''t duidelijk is.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Een voordeel is dat het duidelijk is.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: ordem errada.\r\n- EN: keep English order.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nEen voordeel is / dat het duidelijk is.\r\nEen voordeel is dat het duidelijk is.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 5\r\n\r\nFrase: `Aan de andere kant kost het meer tijd.`\r\n\r\nTraducao PT: Por outro lado custa mais tempo.  \r\nTraducao EN: On the other hand it takes more time.  \r\nAudio nativo: `audio/B1-08/phrases/aan-de-andere-kant-kost-het-meer-tijd.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nContraste.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nAan de andere kant / kost het meer tijd.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nAan de andere kant kost het meer tijd.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nAan de andere kant kost ''t meer tijd.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nAan de andere kant kost ''t meer tijd.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Aan de andere kant kost het meer tijd.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir literalmente.\r\n- EN: say other hand.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nAan de andere kant / kost het meer tijd.\r\nAan de andere kant kost het meer tijd.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir diretamente a ordem da frase portuguesa.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos profissionais ou academicos em pronuncia inglesa.\r\n- Evitar manter ordem inglesa em subordinadas neerlandesas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra, principalmente em verbos no passado, palavras profissionais e conectores.\r\n\r\n### Vogais longas e curtas\r\n\r\nManter contraste com apoio do audio nativo. Em B1, a fluencia nao pode apagar vogais importantes.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. Manter som claro, mas sem exagerar.\r\n\r\n### Reducoes naturais\r\n\r\nReconhecer reducoes em fala natural: `''t`, `''n`, `''k`, `d''r`, `z''n`, ligacoes com `u`, e formas fracas de palavras funcionais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao em respostas longas; respirar por blocos."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase natural, mini dialogo e resposta de 30-90 segundos. Em B1, a entoacao deve ajudar a organizar ideias: introducao, motivo, contraste, consequencia e conclusao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk vind / het een goed plan.\r\nIk ben het / daarmee eens.\r\nIk ben het / niet helemaal eens.\r\nEen voordeel is / dat het duidelijk is.\r\nAan de andere kant / kost het meer tijd.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, d''r, z''n e ligacoes funcionais em fala natural.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Expandir a frase final com motivo, contraste ou consequencia.\r\n\r\n```text\r\nIk vind het een goed plan, omdat het duidelijk is.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Falar a mesma ideia com informacao propria.\r\n8. Gravar uma resposta de 30-60 segundos e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave, reducoes e conectores.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: motivo, problema, consequencia, opiniao e proximo passo.\r\n\r\n### Excerto B1\r\n\r\nOuvir um excerto de 45-60 segundos e identificar ideia principal, dois detalhes e uma relacao logica.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar palavras funcionais, finais verbais e conectores depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ordenar palavras em frase principal e subordinada.\r\n3. Corrigir uma frase com ordem errada.\r\n4. Escrever um paragrafo de 5-6 linhas.\r\n5. Escrever uma resposta funcional: email, resumo, opiniao ou explicacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Resposta de 30-60 segundos com conectores.\r\n6. Mini roleplay com pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Kunt u uitleggen wat er aan de hand is?\r\nAluno: Ik vind het een goed plan.\r\nPessoa: Waarom is dat belangrijk?\r\nAluno: Ik ben het daarmee eens.\r\nPessoa: Wat gaat u nu doen?\r\nAluno: Ik vind het een goed plan, omdat het duidelijk is.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o problema ou tema principal?\r\n- Que motivo ou consequencia foi explicado?\r\n- Que conector foi usado?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Trabalho ou servico formal\r\n\r\nO aluno explica a situacao, da motivo, pede informacao e confirma o proximo passo.\r\n\r\n### Roleplay 2 - Conversa social ou curso\r\n\r\nO aluno da opiniao, responde a pergunta de seguimento e reformula quando nao e entendido.\r\n\r\n### Roleplay 3 - Audio natural\r\n\r\nO aluno ouve uma resposta natural, resume o que entendeu e pede clarificacao de um detalhe."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em subordinadas.\r\n- Falar frases soltas sem conectores em tarefas B1."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. Em B1, o aluno deve:\r\n\r\n```text\r\nA. usar apenas frases memorizadas\r\nB. ligar ideias com conectores\r\nC. evitar textos e audios longos\r\n```\r\n\r\nResposta: B\r\n\r\n3. Numa subordinada com `omdat`, o verbo tende a:\r\n\r\n```text\r\nA. ficar no fim\r\nB. desaparecer\r\nC. ficar sempre no inicio\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender um detalhe em audio natural, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir clarificacao especifica\r\nC. mudar para portugues sempre\r\n```\r\n\r\nResposta: B\r\n\r\n5. O criterio oral B1 exige:\r\n\r\n```text\r\nA. resposta de uma palavra\r\nB. resposta organizada com motivo/consequencia\r\nC. apenas traducao\r\n```\r\n\r\nResposta: B"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nmening - opiniao - opinion\r\neens - de acordo - agree\r\noneens - em desacordo - disagree\r\nduidelijk - claro - clear\r\nvoordeel - vantagem - advantage\r\nnadeel - desvantagem - disadvantage\r\nvergelijking - comparacao - comparison\r\nargument - argumento - argument\r\nIk vind het een goed plan. - Acho que e um bom plano. - I think it is a good plan.\r\nIk ben het daarmee eens. - Estou de acordo com isso. - I agree with that.\r\nIk ben het niet helemaal eens. - Nao concordo totalmente. - I do not completely agree.\r\nEen voordeel is dat het duidelijk is. - Uma vantagem e que e claro. - An advantage is that it is clear.\r\nAan de andere kant kost het meer tijd. - Por outro lado custa mais tempo. - On the other hand it takes more time.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases naturais\r\n3. mini dialogo\r\n4. excerto B1 de 45-60 segundos\r\n5. pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar ideia principal\r\n- identificar dois detalhes\r\n- reconhecer conector ou reducao\r\n- fazer shadowing de uma frase longa\r\n- responder oralmente a pergunta de seguimento\r\n- gravar resposta final de 30-60 segundos"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em frases proprias\r\n- ligar ideias com pelo menos dois conectores\r\n- compreender um mini dialogo natural\r\n- compreender a ideia principal de um excerto B1\r\n- escrever um paragrafo funcional curto\r\n- responder oralmente durante 30-60 segundos sem bloquear\r\n- fazer roleplay com pergunta de seguimento\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk vind het een goed plan, omdat het duidelijk is.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'mening', 'opiniao', 'opinion', 'Na palavra `mening`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Wat is uw mening?', 1 from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'eens', 'de acordo', 'agree', 'Na palavra `eens`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ben het eens.', 2 from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'oneens', 'em desacordo', 'disagree', 'Na palavra `oneens`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ben het oneens.', 3 from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'duidelijk', 'claro', 'clear', 'Na palavra `duidelijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Het plan is duidelijk.', 4 from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'voordeel', 'vantagem', 'advantage', 'Na palavra `voordeel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Een voordeel is...', 5 from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'nadeel', 'desvantagem', 'disadvantage', 'Na palavra `nadeel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Een nadeel is...', 6 from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'vergelijking', 'comparacao', 'comparison', 'Na palavra `vergelijking`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'In vergelijking met...', 7 from lessons l where l.code = 'B1-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'argument', 'argumento', 'argument', 'Na palavra `argument`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn argument is...', 8 from lessons l where l.code = 'B1-08';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik vind het een goed plan.', 'Acho que e um bom plano.', 'I think it is a good plan.', 'Ik vind / het een goed plan.', 'Ik vind het een goed plan.', 'Ik vind ''t een goed plan.', '''k Vind ''t een goed plan.', 'Na frase `Ik vind het een goed plan.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'B1-08';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ben het daarmee eens.', 'Estou de acordo com isso.', 'I agree with that.', 'Ik ben het / daarmee eens.', 'Ik ben het daarmee eens.', 'Ik ben ''t daarmee eens.', '''k Ben ''t daarmee eens.', 'Na frase `Ik ben het daarmee eens.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'B1-08';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ben het niet helemaal eens.', 'Nao concordo totalmente.', 'I do not completely agree.', 'Ik ben het / niet helemaal eens.', 'Ik ben het niet helemaal eens.', 'Ik ben ''t niet helemaal eens.', '''k Ben ''t niet helemaal eens.', 'Na frase `Ik ben het niet helemaal eens.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'B1-08';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Een voordeel is dat het duidelijk is.', 'Uma vantagem e que e claro.', 'An advantage is that it is clear.', 'Een voordeel is / dat het duidelijk is.', 'Een voordeel is dat het duidelijk is.', 'Een voordeel is dat het duidelijk is.', '''n Voordeel is dat ''t duidelijk is.', 'Na frase `Een voordeel is dat het duidelijk is.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'B1-08';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Aan de andere kant kost het meer tijd.', 'Por outro lado custa mais tempo.', 'On the other hand it takes more time.', 'Aan de andere kant / kost het meer tijd.', 'Aan de andere kant kost het meer tijd.', 'Aan de andere kant kost ''t meer tijd.', 'Aan de andere kant kost ''t meer tijd.', 'Na frase `Aan de andere kant kost het meer tijd.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'B1-08';
