insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'B1-09', 'Cultura e sociedade', 'falar de sociedade local', 8, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'B1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo B1 e compreender e produzir neerlandes funcional em textos, audios e interacoes mais longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"B1 amplia cultura diaria para sociedade: voluntariado, vizinhanca, regras comuns, igualdade, pontualidade, comunicacao direta, participacao e convivencia.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nBuurman: We organiseren een buurtavond.\r\nAluno: Dat lijkt me interessant. Wat is de bedoeling?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- falar de sociedade local\r\n- pedir contexto cultural\r\n- expressar interesse\r\n- entender normas de convivencia\r\n- participar em conversas comunitarias\r\n- evitar generalizacoes absolutas\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nDat lijkt me interessant. Wat is de bedoeling?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nDat lijkt me interessant.\r\nWat is de bedoeling?\r\nVolgens mij is dat normaal.\r\nIn mijn ervaring werkt dat goed.\r\nIedereen moet de regels respecteren.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `samenleving`\r\n\r\nTraducao PT: sociedade  \r\nTraducao EN: society  \r\nAudio nativo: `audio/B1-09/words/samenleving.native.nl.mp3`  \r\nAproximacao inicial PT: `SAA-men-lee-ving`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `samenleving`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer sociedade.\r\n- EN: say society.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe samenleving verandert.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nsamenleving\r\nsamenleving em bloco\r\nDe samenleving verandert.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `samenleving` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `samenleving` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `buurt`\r\n\r\nTraducao PT: bairro/vizinhanca  \r\nTraducao EN: neighborhood  \r\nAudio nativo: `audio/B1-09/words/buurt.native.nl.mp3`  \r\nAproximacao inicial PT: `buurt`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `buurt`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer burte.\r\n- EN: say neighborhood.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk woon in deze buurt.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbuurt\r\nbuurt em bloco\r\nIk woon in deze buurt.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `buurt` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `buurt` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `vrijwilliger`\r\n\r\nTraducao PT: voluntario  \r\nTraducao EN: volunteer  \r\nAudio nativo: `audio/B1-09/words/vrijwilliger.native.nl.mp3`  \r\nAproximacao inicial PT: `VREI-vil-li-gher`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vrijwilliger`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer voluntario.\r\n- EN: say volunteer.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben vrijwilliger.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvrijwilliger\r\nvrijwilliger em bloco\r\nIk ben vrijwilliger.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `vrijwilliger` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vrijwilliger` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `regel`\r\n\r\nTraducao PT: regra  \r\nTraducao EN: rule  \r\nAudio nativo: `audio/B1-09/words/regel.native.nl.mp3`  \r\nAproximacao inicial PT: `REE-ghul`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `regel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer regra.\r\n- EN: say rule.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is de regel?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nregel\r\nregel em bloco\r\nWat is de regel?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `regel` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `regel` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `bedoeling`\r\n\r\nTraducao PT: intencao/objetivo  \r\nTraducao EN: intention/purpose  \r\nAudio nativo: `audio/B1-09/words/bedoeling.native.nl.mp3`  \r\nAproximacao inicial PT: `bu-DOO-ling`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bedoeling`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer intencao.\r\n- EN: say meaning.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is de bedoeling?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbedoeling\r\nbedoeling em bloco\r\nWat is de bedoeling?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bedoeling` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bedoeling` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `ervaring`\r\n\r\nTraducao PT: experiencia  \r\nTraducao EN: experience  \r\nAudio nativo: `audio/B1-09/words/ervaring.native.nl.mp3`  \r\nAproximacao inicial PT: `er-VAA-ring`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ervaring`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer experiencia.\r\n- EN: say experience.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIn mijn ervaring...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nervaring\r\nervaring em bloco\r\nIn mijn ervaring...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `ervaring` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `ervaring` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `gelijkheid`\r\n\r\nTraducao PT: igualdade  \r\nTraducao EN: equality  \r\nAudio nativo: `audio/B1-09/words/gelijkheid.native.nl.mp3`  \r\nAproximacao inicial PT: `ghe-LAIK-heid`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `gelijkheid`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer igualdade.\r\n- EN: say equality.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGelijkheid is belangrijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngelijkheid\r\ngelijkheid em bloco\r\nGelijkheid is belangrijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `gelijkheid` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `gelijkheid` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `respect`\r\n\r\nTraducao PT: respeito  \r\nTraducao EN: respect  \r\nAudio nativo: `audio/B1-09/words/respect.native.nl.mp3`  \r\nAproximacao inicial PT: `res-PEKT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `respect`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer respeito.\r\n- EN: say respect.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nRespect is belangrijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nrespect\r\nrespect em bloco\r\nRespect is belangrijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `respect` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `respect` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em comunicacao B1: narrativa, explicacao, opiniao, pedido, consequencia e plano. O aluno deve usar os verbos em frases proprias e em respostas de varios turnos.\r\n\r\n```text\r\nhebben\r\nzijn\r\nworden\r\nkunnen\r\nmoeten\r\nwillen\r\ngaan\r\nuitleggen\r\nsamenvatten\r\nreageren\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Estruturas: `Dat lijkt me...`, `Het is de bedoeling dat...`, `Volgens mij...`, `In mijn ervaring...`. O aluno aprende a falar de cultura como experiencia, nao como verdade absoluta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Dat lijkt me interessant.`\r\n\r\nTraducao PT: Isso parece-me interessante.  \r\nTraducao EN: That seems interesting to me.  \r\nAudio nativo: `audio/B1-09/phrases/dat-lijkt-me-interessant.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nMostrar interesse.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDat lijkt me / interessant.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDat lijkt me interessant.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDat lijkt me interessant.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDa lijkt me interessant.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Dat lijkt me interessant.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer parece interessante com ordem PT.\r\n- EN: say seems.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDat lijkt me / interessant.\r\nDat lijkt me interessant.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 2\r\n\r\nFrase: `Wat is de bedoeling?`\r\n\r\nTraducao PT: Qual e a intencao/o objetivo?  \r\nTraducao EN: What is the purpose?  \r\nAudio nativo: `audio/B1-09/phrases/wat-is-de-bedoeling.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir contexto.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWat is / de bedoeling?\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWat is de bedoeling?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWat is de bedoeling?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWat is de bedoeling?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Wat is de bedoeling?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir meaning sempre.\r\n- EN: say meaning.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWat is / de bedoeling?\r\nWat is de bedoeling?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 3\r\n\r\nFrase: `Volgens mij is dat normaal.`\r\n\r\nTraducao PT: Na minha opiniao isso e normal.  \r\nTraducao EN: In my view that is normal.  \r\nAudio nativo: `audio/B1-09/phrases/volgens-mij-is-dat-normaal.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nOpiniao cultural.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nVolgens mij / is dat normaal.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nVolgens mij is dat normaal.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nVolgens mij is dat normaal.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nVolgens mij is dat normaal.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Volgens mij is dat normaal.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer segundo mim literal.\r\n- EN: say according to me.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nVolgens mij / is dat normaal.\r\nVolgens mij is dat normaal.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 4\r\n\r\nFrase: `In mijn ervaring werkt dat goed.`\r\n\r\nTraducao PT: Na minha experiencia isso funciona bem.  \r\nTraducao EN: In my experience that works well.  \r\nAudio nativo: `audio/B1-09/phrases/in-mijn-ervaring-werkt-dat-goed.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPartilhar experiencia.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIn mijn ervaring / werkt dat goed.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIn mijn ervaring werkt dat goed.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIn m''n ervaring werkt dat goed.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIn m''n ervaring werkt dat goed.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `In mijn ervaring werkt dat goed.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer experiencia PT.\r\n- EN: say experience.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIn mijn ervaring / werkt dat goed.\r\nIn mijn ervaring werkt dat goed.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 5\r\n\r\nFrase: `Iedereen moet de regels respecteren.`\r\n\r\nTraducao PT: Todos devem respeitar as regras.  \r\nTraducao EN: Everyone must respect the rules.  \r\nAudio nativo: `audio/B1-09/phrases/iedereen-moet-de-regels-respecteren.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nConvivencia.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIedereen / moet de regels / respecteren.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIedereen moet de regels respecteren.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIedereen moet de regels respecteren.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIedereen moet de regels respecteren.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Iedereen moet de regels respecteren.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer regras PT.\r\n- EN: say rules.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIedereen / moet de regels / respecteren.\r\nIedereen moet de regels respecteren.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter diferenca entre vogais longas e curtas.\r\n- Evitar traduzir diretamente a ordem da frase portuguesa.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar cognatos profissionais ou academicos em pronuncia inglesa.\r\n- Evitar manter ordem inglesa em subordinadas neerlandesas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra, principalmente em verbos no passado, palavras profissionais e conectores.\r\n\r\n### Vogais longas e curtas\r\n\r\nManter contraste com apoio do audio nativo. Em B1, a fluencia nao pode apagar vogais importantes.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. Manter som claro, mas sem exagerar.\r\n\r\n### Reducoes naturais\r\n\r\nReconhecer reducoes em fala natural: `''t`, `''n`, `''k`, `d''r`, `z''n`, ligacoes com `u`, e formas fracas de palavras funcionais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve.\r\n- Mandibula: evitar tensao em respostas longas; respirar por blocos."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase natural, mini dialogo e resposta de 30-90 segundos. Em B1, a entoacao deve ajudar a organizar ideias: introducao, motivo, contraste, consequencia e conclusao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nDat lijkt me / interessant.\r\nWat is / de bedoeling?\r\nVolgens mij / is dat normaal.\r\nIn mijn ervaring / werkt dat goed.\r\nIedereen / moet de regels / respecteren.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes e manter ritmo neerlandes.\r\nReduzida: reconhecer ''t, ''n, ''k, d''r, z''n e ligacoes funcionais em fala natural.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n6. Expandir a frase final com motivo, contraste ou consequencia.\r\n\r\n```text\r\nDat lijkt me interessant. Wat is de bedoeling?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Falar a mesma ideia com informacao propria.\r\n8. Gravar uma resposta de 30-60 segundos e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave, reducoes e conectores.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao: motivo, problema, consequencia, opiniao e proximo passo.\r\n\r\n### Excerto B1\r\n\r\nOuvir um excerto de 45-60 segundos e identificar ideia principal, dois detalhes e uma relacao logica.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar palavras funcionais, finais verbais e conectores depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ordenar palavras em frase principal e subordinada.\r\n3. Corrigir uma frase com ordem errada.\r\n4. Escrever um paragrafo de 5-6 linhas.\r\n5. Escrever uma resposta funcional: email, resumo, opiniao ou explicacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Resposta de 30-60 segundos com conectores.\r\n6. Mini roleplay com pergunta de seguimento."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Kunt u uitleggen wat er aan de hand is?\r\nAluno: Dat lijkt me interessant.\r\nPessoa: Waarom is dat belangrijk?\r\nAluno: Wat is de bedoeling?\r\nPessoa: Wat gaat u nu doen?\r\nAluno: Dat lijkt me interessant. Wat is de bedoeling?\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi o problema ou tema principal?\r\n- Que motivo ou consequencia foi explicado?\r\n- Que conector foi usado?\r\n- Qual e o proximo passo?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Trabalho ou servico formal\r\n\r\nO aluno explica a situacao, da motivo, pede informacao e confirma o proximo passo.\r\n\r\n### Roleplay 2 - Conversa social ou curso\r\n\r\nO aluno da opiniao, responde a pergunta de seguimento e reformula quando nao e entendido.\r\n\r\n### Roleplay 3 - Audio natural\r\n\r\nO aluno ouve uma resposta natural, resume o que entendeu e pede clarificacao de um detalhe."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Usar ordem de frase portuguesa/inglesa em subordinadas.\r\n- Falar frases soltas sem conectores em tarefas B1."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. Em B1, o aluno deve:\r\n\r\n```text\r\nA. usar apenas frases memorizadas\r\nB. ligar ideias com conectores\r\nC. evitar textos e audios longos\r\n```\r\n\r\nResposta: B\r\n\r\n3. Numa subordinada com `omdat`, o verbo tende a:\r\n\r\n```text\r\nA. ficar no fim\r\nB. desaparecer\r\nC. ficar sempre no inicio\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender um detalhe em audio natural, deve:\r\n\r\n```text\r\nA. fingir que entendeu\r\nB. pedir clarificacao especifica\r\nC. mudar para portugues sempre\r\n```\r\n\r\nResposta: B\r\n\r\n5. O criterio oral B1 exige:\r\n\r\n```text\r\nA. resposta de uma palavra\r\nB. resposta organizada com motivo/consequencia\r\nC. apenas traducao\r\n```\r\n\r\nResposta: B"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nsamenleving - sociedade - society\r\nbuurt - bairro/vizinhanca - neighborhood\r\nvrijwilliger - voluntario - volunteer\r\nregel - regra - rule\r\nbedoeling - intencao/objetivo - intention/purpose\r\nervaring - experiencia - experience\r\ngelijkheid - igualdade - equality\r\nrespect - respeito - respect\r\nDat lijkt me interessant. - Isso parece-me interessante. - That seems interesting to me.\r\nWat is de bedoeling? - Qual e a intencao/o objetivo? - What is the purpose?\r\nVolgens mij is dat normaal. - Na minha opiniao isso e normal. - In my view that is normal.\r\nIn mijn ervaring werkt dat goed. - Na minha experiencia isso funciona bem. - In my experience that works well.\r\nIedereen moet de regels respecteren. - Todos devem respeitar as regras. - Everyone must respect the rules.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases naturais\r\n3. mini dialogo\r\n4. excerto B1 de 45-60 segundos\r\n5. pergunta de seguimento\r\n6. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar ideia principal\r\n- identificar dois detalhes\r\n- reconhecer conector ou reducao\r\n- fazer shadowing de uma frase longa\r\n- responder oralmente a pergunta de seguimento\r\n- gravar resposta final de 30-60 segundos"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em frases proprias\r\n- ligar ideias com pelo menos dois conectores\r\n- compreender um mini dialogo natural\r\n- compreender a ideia principal de um excerto B1\r\n- escrever um paragrafo funcional curto\r\n- responder oralmente durante 30-60 segundos sem bloquear\r\n- fazer roleplay com pergunta de seguimento\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nDat lijkt me interessant. Wat is de bedoeling?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'samenleving', 'sociedade', 'society', 'Na palavra `samenleving`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'De samenleving verandert.', 1 from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'buurt', 'bairro/vizinhanca', 'neighborhood', 'Na palavra `buurt`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik woon in deze buurt.', 2 from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'vrijwilliger', 'voluntario', 'volunteer', 'Na palavra `vrijwilliger`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik ben vrijwilliger.', 3 from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'regel', 'regra', 'rule', 'Na palavra `regel`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Wat is de regel?', 4 from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'bedoeling', 'intencao/objetivo', 'intention/purpose', 'Na palavra `bedoeling`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Wat is de bedoeling?', 5 from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'ervaring', 'experiencia', 'experience', 'Na palavra `ervaring`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'In mijn ervaring...', 6 from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'gelijkheid', 'igualdade', 'equality', 'Na palavra `gelijkheid`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Gelijkheid is belangrijk.', 7 from lessons l where l.code = 'B1-09';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'respect', 'respeito', 'respect', 'Na palavra `respect`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Respect is belangrijk.', 8 from lessons l where l.code = 'B1-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Dat lijkt me interessant.', 'Isso parece-me interessante.', 'That seems interesting to me.', 'Dat lijkt me / interessant.', 'Dat lijkt me interessant.', 'Dat lijkt me interessant.', 'Da lijkt me interessant.', 'Na frase `Dat lijkt me interessant.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'B1-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Wat is de bedoeling?', 'Qual e a intencao/o objetivo?', 'What is the purpose?', 'Wat is / de bedoeling?', 'Wat is de bedoeling?', 'Wat is de bedoeling?', 'Wat is de bedoeling?', 'Na frase `Wat is de bedoeling?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'B1-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Volgens mij is dat normaal.', 'Na minha opiniao isso e normal.', 'In my view that is normal.', 'Volgens mij / is dat normaal.', 'Volgens mij is dat normaal.', 'Volgens mij is dat normaal.', 'Volgens mij is dat normaal.', 'Na frase `Volgens mij is dat normaal.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'B1-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'In mijn ervaring werkt dat goed.', 'Na minha experiencia isso funciona bem.', 'In my experience that works well.', 'In mijn ervaring / werkt dat goed.', 'In mijn ervaring werkt dat goed.', 'In m''n ervaring werkt dat goed.', 'In m''n ervaring werkt dat goed.', 'Na frase `In mijn ervaring werkt dat goed.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'B1-09';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Iedereen moet de regels respecteren.', 'Todos devem respeitar as regras.', 'Everyone must respect the rules.', 'Iedereen / moet de regels / respecteren.', 'Iedereen moet de regels respecteren.', 'Iedereen moet de regels respecteren.', 'Iedereen moet de regels respecteren.', 'Na frase `Iedereen moet de regels respecteren.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'B1-09';
