insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'B1-10', 'Revisao B1', 'relatar evento passado', 9, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'B1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo B1 e compreender e produzir neerlandes funcional em textos, audios e interacoes mais longas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"A revisao B1 verifica se o aluno consegue explicar eventos, planos, opinioes, problemas e textos praticos em neerlandes funcional, mantendo conversa por varios turnos.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nDocent: Vertel wat er is gebeurd en wat u nu gaat doen.\r\nAluno: Gisteren had ik een probleem op het werk. Daarom ga ik vandaag mijn leidinggevende bellen.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- relatar evento passado\r\n- explicar consequencia\r\n- falar de plano futuro\r\n- resumir texto pratico\r\n- dar opiniao com argumento\r\n- participar em roleplay integrado\r\n- produzir resposta oral de 60-90 segundos\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nGisteren had ik een probleem op het werk. Daarom ga ik vandaag mijn leidinggevende bellen.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nGisteren had ik een probleem op het werk.\r\nDaarom ga ik vandaag mijn leidinggevende bellen.\r\nMijn mening is dat we meer tijd nodig hebben.\r\nDe belangrijkste informatie staat in de brief.\r\nKunt u kort samenvatten wat ik moet doen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `gebeurtenis`\r\n\r\nTraducao PT: acontecimento  \r\nTraducao EN: event  \r\nAudio nativo: `audio/B1-10/words/gebeurtenis.native.nl.mp3`  \r\nAproximacao inicial PT: `ghu-BEUR-tuh-nis`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `gebeurtenis`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer evento.\r\n- EN: say event.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBeschrijf de gebeurtenis.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngebeurtenis\r\ngebeurtenis em bloco\r\nBeschrijf de gebeurtenis.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `gebeurtenis` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `gebeurtenis` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `gevolg`\r\n\r\nTraducao PT: consequencia  \r\nTraducao EN: consequence  \r\nAudio nativo: `audio/B1-10/words/gevolg.native.nl.mp3`  \r\nAproximacao inicial PT: `ghu-VOLKH`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `gevolg`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer consequencia.\r\n- EN: say consequence.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWat is het gevolg?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngevolg\r\ngevolg em bloco\r\nWat is het gevolg?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `gevolg` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `gevolg` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `oplossing`\r\n\r\nTraducao PT: solucao  \r\nTraducao EN: solution  \r\nAudio nativo: `audio/B1-10/words/oplossing.native.nl.mp3`  \r\nAproximacao inicial PT: `OP-los-sing`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `oplossing`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer solucao.\r\n- EN: say solution.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk zoek een oplossing.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\noplossing\r\noplossing em bloco\r\nIk zoek een oplossing.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `oplossing` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `oplossing` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `samenvatting`\r\n\r\nTraducao PT: resumo  \r\nTraducao EN: summary  \r\nAudio nativo: `audio/B1-10/words/samenvatting.native.nl.mp3`  \r\nAproximacao inicial PT: `SAA-men-vat-ting`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `samenvatting`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer resumo.\r\n- EN: say summary.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGeef een samenvatting.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nsamenvatting\r\nsamenvatting em bloco\r\nGeef een samenvatting.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `samenvatting` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `samenvatting` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `argument`\r\n\r\nTraducao PT: argumento  \r\nTraducao EN: argument  \r\nAudio nativo: `audio/B1-10/words/argument.native.nl.mp3`  \r\nAproximacao inicial PT: `ar-ghu-MENT`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `argument`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer argumento.\r\n- EN: say argument.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGeef een argument.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nargument\r\nargument em bloco\r\nGeef een argument.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `argument` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `argument` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `ervaring`\r\n\r\nTraducao PT: experiencia  \r\nTraducao EN: experience  \r\nAudio nativo: `audio/B1-10/words/ervaring.native.nl.mp3`  \r\nAproximacao inicial PT: `er-VAA-ring`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ervaring`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer experiencia.\r\n- EN: say experience.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIn mijn ervaring...\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nervaring\r\nervaring em bloco\r\nIn mijn ervaring...\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `ervaring` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `ervaring` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `planning`\r\n\r\nTraducao PT: planeamento  \r\nTraducao EN: planning  \r\nAudio nativo: `audio/B1-10/words/planning.native.nl.mp3`  \r\nAproximacao inicial PT: `PLAN-ning`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `planning`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer planing.\r\n- EN: say planning English.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe planning is veranderd.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nplanning\r\nplanning em bloco\r\nDe planning is veranderd.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `planning` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `planning` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `ontwikkeling`\r\n\r\nTraducao PT: desenvolvimento  \r\nTraducao EN: development  \r\nAudio nativo: `audio/B1-10/words/ontwikkeling.native.nl.mp3`  \r\nAproximacao inicial PT: `ont-VIK-ke-ling`  \r\nAproximacao inicial EN: initial support only; native audio remains primary\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ontwikkeling`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer desenvolvimento.\r\n- EN: say development.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn ontwikkeling gaat goed.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nontwikkeling\r\nontwikkeling em bloco\r\nMijn ontwikkeling gaat goed.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `ontwikkeling` isolado, dentro de uma frase natural e dentro de um excerto B1 mais longo. Deve identificar a palavra, a funcao e a informacao que ela acrescenta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `ontwikkeling` em audio nativo, usa a palavra numa frase propria e entende a palavra num pequeno paragrafo oral."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em comunicacao B1: narrativa, explicacao, opiniao, pedido, consequencia e plano. O aluno deve usar os verbos em frases proprias e em respostas de varios turnos.\r\n\r\n```text\r\nhebben\r\nzijn\r\nworden\r\nkunnen\r\nmoeten\r\nwillen\r\ngaan\r\nuitleggen\r\nsamenvatten\r\nreageren\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Revisao integrada: ordem da frase, passado funcional, futuro/planos, conectores, opiniao, subordinadas com verbo final, escrita funcional e compreensao auditiva natural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-10';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Gisteren had ik een probleem op het werk.`\r\n\r\nTraducao PT: Ontem tive um problema no trabalho.  \r\nTraducao EN: Yesterday I had a problem at work.  \r\nAudio nativo: `audio/B1-10/phrases/gisteren-had-ik-een-probleem-op-het-werk.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nNarrativa.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nGisteren / had ik / een probleem / op het werk.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nGisteren had ik een probleem op het werk.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nGisteren had ik ''n probleem op ''t werk.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nGisteren had ''k ''n probleem op ''t werk.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Gisteren had ik een probleem op het werk.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: ordem portuguesa.\r\n- EN: keep English order.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nGisteren / had ik / een probleem / op het werk.\r\nGisteren had ik een probleem op het werk.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 2\r\n\r\nFrase: `Daarom ga ik vandaag mijn leidinggevende bellen.`\r\n\r\nTraducao PT: Por isso vou ligar hoje ao meu supervisor.  \r\nTraducao EN: That is why I am going to call my supervisor today.  \r\nAudio nativo: `audio/B1-10/phrases/daarom-ga-ik-vandaag-mijn-leidinggevende-bellen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nConsequencia/plano.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDaarom / ga ik vandaag / mijn leidinggevende bellen.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDaarom ga ik vandaag mijn leidinggevende bellen.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDaarom ga ik vandaag m''n leidinggevende bellen.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDaarom ga ''k vandaag m''n leidinggevende bellen.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Daarom ga ik vandaag mijn leidinggevende bellen.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: esquecer inversao.\r\n- EN: say therefore I.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDaarom / ga ik vandaag / mijn leidinggevende bellen.\r\nDaarom ga ik vandaag mijn leidinggevende bellen.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 3\r\n\r\nFrase: `Mijn mening is dat we meer tijd nodig hebben.`\r\n\r\nTraducao PT: A minha opiniao e que precisamos de mais tempo.  \r\nTraducao EN: My opinion is that we need more time.  \r\nAudio nativo: `audio/B1-10/phrases/mijn-mening-is-dat-we-meer-tijd-nodig-hebben.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nOpiniao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMijn mening is / dat we meer tijd / nodig hebben.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMijn mening is dat we meer tijd nodig hebben.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nMijn mening is dat we meer tijd nodig hebben.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nM''n mening is dat we meer tijd nodig hebben.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Mijn mening is dat we meer tijd nodig hebben.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: ordem errada.\r\n- EN: keep English order.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMijn mening is / dat we meer tijd / nodig hebben.\r\nMijn mening is dat we meer tijd nodig hebben.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 4\r\n\r\nFrase: `De belangrijkste informatie staat in de brief.`\r\n\r\nTraducao PT: A informacao mais importante esta na carta.  \r\nTraducao EN: The most important information is in the letter.  \r\nAudio nativo: `audio/B1-10/phrases/de-belangrijkste-informatie-staat-in-de-brief.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nLeitura.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDe belangrijkste informatie / staat in de brief.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDe belangrijkste informatie staat in de brief.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDe belangrijkste informatie staat in de brief.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDe belangrijkste informatie staat in de brief.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `De belangrijkste informatie staat in de brief.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir esta em.\r\n- EN: say important info.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDe belangrijkste informatie / staat in de brief.\r\nDe belangrijkste informatie staat in de brief.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta.\r\n\r\n### Frase 5\r\n\r\nFrase: `Kunt u kort samenvatten wat ik moet doen?`\r\n\r\nTraducao PT: Pode resumir brevemente o que devo fazer?  \r\nTraducao EN: Can you briefly summarize what I should do?  \r\nAudio nativo: `audio/B1-10/phrases/kunt-u-kort-samenvatten-wat-ik-moet-doen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir confirmacao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u / kort samenvatten / wat ik moet doen?\r\n```\r\n\r\nRitmo:\r\n\r\nEm B1, a frase deve ser treinada como parte de uma resposta maior: primeiro por blocos, depois como frase natural, depois dentro de uma explicacao curta com duas ou tres frases.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u kort samenvatten wat ik moet doen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKuntu kort samenvatten wat ik moet doen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u kort samenvatten wat ''k moet doen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u kort samenvatten wat ik moet doen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer resumo.\r\n- EN: say summarize.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u / kort samenvatten / wat ik moet doen?\r\nKunt u kort samenvatten wat ik moet doen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Repetir a frase dentro de uma resposta de 2-3 frases.\r\n6. Gravar e comparar ritmo, reducoes, finais e ligacoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural e depois num mini dialogo. Deve identificar a intencao, a informacao principal, a relacao logica e uma reducao natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em fala natural, adapta-a a um contexto novo e usa-a dentro de uma resposta B1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B1-10';
