insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'B2-02', 'Comunicacao formal', 'distinguir formal e informal', 1, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'B2'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 1, '{"title":"Contexto real de utilizacao","body":"Em B2, o aluno deve escrever e falar com educacao, distancia profissional e clareza. A prioridade e conseguir pedir, recusar, justificar e acompanhar assuntos sem parecer rude ou demasiado informal.\r\n\r\nSituacao real:\r\n\r\n```text\r\nAluno envia um pedido formal a uma entidade: `Graag ontvang ik nadere informatie over de procedure.`\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 2, '{"title":"Objetivos da licao","body":"- distinguir formal e informal\r\n- usar `u` e formas indiretas\r\n- formular pedidos educados\r\n- fazer seguimento de um assunto\r\n- expressar desacordo diplomaticamente\r\n- entender linguagem formal em respostas oficiais"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 3, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `betreft`\r\n\r\nTraducao PT: refere-se a/diz respeito a  \r\nTraducao EN: concerns  \r\nAudio nativo: `audio/B2-02/words/betreft.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `betreft`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar como `sobre` em todo lado.\r\n- EN: overuse concerns literally.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDeze vraag betreft mijn aanvraag.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbetreft\r\nbetreft em frase\r\nDeze vraag betreft mijn aanvraag.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `betreft` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `betreft` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 2\r\n\r\nPalavra: `aanvraag`\r\n\r\nTraducao PT: pedido/requerimento  \r\nTraducao EN: application/request  \r\nAudio nativo: `audio/B2-02/words/aanvraag.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `aanvraag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer aplicacao.\r\n- EN: say application only.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn aanvraag is nog in behandeling.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\naanvraag\r\naanvraag em frase\r\nMijn aanvraag is nog in behandeling.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `aanvraag` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `aanvraag` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 3\r\n\r\nPalavra: `procedure`\r\n\r\nTraducao PT: procedimento  \r\nTraducao EN: procedure  \r\nAudio nativo: `audio/B2-02/words/procedure.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `procedure`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: pronunciar como portugues.\r\n- EN: English stress pattern.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nKunt u de procedure uitleggen?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nprocedure\r\nprocedure em frase\r\nKunt u de procedure uitleggen?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `procedure` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `procedure` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 4\r\n\r\nPalavra: `nadere`\r\n\r\nTraducao PT: mais detalhada/adicional  \r\nTraducao EN: further  \r\nAudio nativo: `audio/B2-02/words/nadere.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `nadere`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: confundir com `andere`.\r\n- EN: say nearer.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nGraag ontvang ik nadere informatie.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnadere\r\nnadere em frase\r\nGraag ontvang ik nadere informatie.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `nadere` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `nadere` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 5\r\n\r\nPalavra: `verzoek`\r\n\r\nTraducao PT: pedido formal  \r\nTraducao EN: request  \r\nAudio nativo: `audio/B2-02/words/verzoek.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `verzoek`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar sempre `vraag`.\r\n- EN: use question instead of request.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk dien een verzoek in.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nverzoek\r\nverzoek em frase\r\nIk dien een verzoek in.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `verzoek` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `verzoek` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 6\r\n\r\nPalavra: `bevestiging`\r\n\r\nTraducao PT: confirmacao  \r\nTraducao EN: confirmation  \r\nAudio nativo: `audio/B2-02/words/bevestiging.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bevestiging`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer confirmacao.\r\n- EN: say confirmation.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk wacht op uw bevestiging.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbevestiging\r\nbevestiging em frase\r\nIk wacht op uw bevestiging.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bevestiging` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bevestiging` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 7\r\n\r\nPalavra: `termijn`\r\n\r\nTraducao PT: prazo  \r\nTraducao EN: deadline/term  \r\nAudio nativo: `audio/B2-02/words/termijn.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `termijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: confundir com terminal.\r\n- EN: say term only.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBinnen welke termijn?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntermijn\r\ntermijn em frase\r\nBinnen welke termijn?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `termijn` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `termijn` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 8\r\n\r\nPalavra: `hoogachtend`\r\n\r\nTraducao PT: com os melhores cumprimentos formal  \r\nTraducao EN: yours faithfully  \r\nAudio nativo: `audio/B2-02/words/hoogachtend.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `hoogachtend`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar em emails normais demais.\r\n- EN: use in casual emails.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHoogachtend,\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhoogachtend\r\nhoogachtend em frase\r\nHoogachtend,\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `hoogachtend` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `hoogachtend` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 4, '{"title":"Verbos principais","body":"- `kunnen`: expressar capacidade, pedido educado e possibilidade.\r\n- `moeten`: indicar obrigacao, requisito ou necessidade profissional.\r\n- `zullen`: proposta, expectativa, compromisso ou futuro formal.\r\n- `worden`: passiva e desenvolvimento de situacoes.\r\n- `bespreken`: discutir tema em contexto profissional.\r\n- `toelichten`: explicar ponto com detalhe e clareza.\r\n- `onderbouwen`: fundamentar com razoes, dados ou exemplos.\r\n- `aanpassen`: adaptar linguagem, plano ou comportamento ao contexto."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 5, '{"title":"Gramatica necessaria","body":"Comunicacao formal usa estruturas indiretas: `Zou u kunnen...`, `Graag ontvang ik...`, `Ik verzoek u...`. O verbo continua a seguir regras normais, mas o tom muda pela escolha lexical e pela distancia.\r\n\r\nMini regra pratica:\r\n\r\n```text\r\nideia principal + conector + detalhe/condicao + consequencia\r\n```\r\n\r\nO aluno deve produzir frases mais longas apenas quando consegue manter verbo, sujeito, pronome e final de palavra sob controlo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 6, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Graag ontvang ik nadere informatie over de procedure.`\r\n\r\nTraducao PT: Gostaria de receber informacao adicional sobre o procedimento.  \r\nTraducao EN: I would like to receive further information about the procedure.  \r\nAudio nativo: `audio/B2-02/phrases/graag-ontvang-ik-nadere-informatie-over-de-procedure.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedido formal.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nGraag ontvang ik / nadere informatie / over de procedure.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nGraag ontvang ik nadere informatie over de procedure.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nGraag ontvang ik nadere informatie over de procedure.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nGraag ontvang ''k nadere informatie over de procedure.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Graag ontvang ik nadere informatie over de procedure.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir `eu quero receber`.\r\n- EN: sound too direct: I want.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nGraag ontvang ik / nadere informatie / over de procedure.\r\nGraag ontvang ik nadere informatie over de procedure.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 2\r\n\r\nFrase: `Zou u kunnen bevestigen dat mijn aanvraag is ontvangen?`\r\n\r\nTraducao PT: Poderia confirmar que o meu pedido foi recebido?  \r\nTraducao EN: Could you confirm that my application has been received?  \r\nAudio nativo: `audio/B2-02/phrases/zou-u-kunnen-bevestigen-dat-mijn-aanvraag-is-ontvangen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nConfirmar rececao.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nZou u kunnen bevestigen / dat mijn aanvraag / is ontvangen?\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nZou u kunnen bevestigen dat mijn aanvraag is ontvangen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nZou u kunnen bevestigen dat mijn aanvraag is ontvangen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nZou u kunnen bevestigen dat m''n aanvraag is ontvangen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Zou u kunnen bevestigen dat mijn aanvraag is ontvangen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer `kan jij` para entidade.\r\n- EN: use can you in too casual tone.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nZou u kunnen bevestigen / dat mijn aanvraag / is ontvangen?\r\nZou u kunnen bevestigen dat mijn aanvraag is ontvangen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 3\r\n\r\nFrase: `Ik verzoek u vriendelijk om binnen twee weken te reageren.`\r\n\r\nTraducao PT: Solicito gentilmente que responda dentro de duas semanas.  \r\nTraducao EN: I kindly request that you respond within two weeks.  \r\nAudio nativo: `audio/B2-02/phrases/ik-verzoek-u-vriendelijk-om-binnen-twee-weken-te-reageren.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedido com prazo.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk verzoek u vriendelijk / om binnen twee weken / te reageren.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk verzoek u vriendelijk om binnen twee weken te reageren.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk verzoek u vriendelijk om binnen twee weken te reageren.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Verzoek u vriendelijk om binnen twee weken te reageren.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik verzoek u vriendelijk om binnen twee weken te reageren.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: soar agressivo por entoacao.\r\n- EN: sound legalistic too sharply.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk verzoek u vriendelijk / om binnen twee weken / te reageren.\r\nIk verzoek u vriendelijk om binnen twee weken te reageren.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 4\r\n\r\nFrase: `Met betrekking tot uw bericht heb ik nog een vraag.`\r\n\r\nTraducao PT: Relativamente a sua mensagem, ainda tenho uma pergunta.  \r\nTraducao EN: Regarding your message, I still have a question.  \r\nAudio nativo: `audio/B2-02/phrases/met-betrekking-tot-uw-bericht-heb-ik-nog-een-vraag.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nSeguimento formal.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMet betrekking tot uw bericht / heb ik / nog een vraag.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMet betrekking tot uw bericht heb ik nog een vraag.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nMet betrekking tot uw bericht heb ik nog een vraag.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nMet betrekking tot uw bericht heb ''k nog een vraag.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Met betrekking tot uw bericht heb ik nog een vraag.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: traducao literal pesada.\r\n- EN: avoid phrase because it feels long.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMet betrekking tot uw bericht / heb ik / nog een vraag.\r\nMet betrekking tot uw bericht heb ik nog een vraag.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 5\r\n\r\nFrase: `Ik begrijp uw standpunt, maar ik zie dat anders.`\r\n\r\nTraducao PT: Compreendo o seu ponto de vista, mas vejo isso de outra forma.  \r\nTraducao EN: I understand your position, but I see it differently.  \r\nAudio nativo: `audio/B2-02/phrases/ik-begrijp-uw-standpunt-maar-ik-zie-dat-anders.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDiscordancia diplomatica.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk begrijp uw standpunt / maar / ik zie dat anders.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk begrijp uw standpunt, maar ik zie dat anders.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk begrijp uw standpunt, maar ik zie dat anders.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Begrijp uw standpunt, maar ik zie dat anders.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik begrijp uw standpunt, maar ik zie dat anders.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: discordar de forma brusca.\r\n- EN: sound confrontational.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk begrijp uw standpunt / maar / ik zie dat anders.\r\nIk begrijp uw standpunt, maar ik zie dat anders.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'pronuncia-pt-nl', 7, '{"title":"Pronuncia PT -> NL","body":"A aproximacao escrita para falantes de portugues e apenas apoio inicial. O aluno deve ouvir primeiro o audio nativo, observar boca/lingua/garganta e so depois usar a aproximacao como ponte temporaria.\r\n\r\nFocos PT:\r\n\r\n- Evitar adicionar vogal no fim de palavras com consoante final: `besluit`, `akkoord`, `veranderd`.\r\n- Nao transformar `g/ch` em `r` portugues.\r\n- Manter contraste entre `ui`, `ij/ei`, `oe`, `aa`, `ee`.\r\n- Reduzir ritmo silabico portugues e treinar grupos de sentido neerlandeses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'pronuncia-en-nl', 8, '{"title":"Pronuncia EN -> NL","body":"A aproximacao escrita para falantes de ingles e apenas apoio inicial. O aluno deve evitar transferir ritmo, stress e vogais do ingles para neerlandes.\r\n\r\nFocos EN:\r\n\r\n- Nao substituir `g/ch` por `h` ingles.\r\n- Evitar stress ingles em palavras internacionais.\r\n- Fechar finais `d/t/k/p` sem adicionar som extra.\r\n- Treinar `ui` e `ij/ei` com audio nativo, nao com equivalentes ingleses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 9, '{"title":"Explicacao fisica dos sons dificeis","body":"### Audio nativo como referencia principal\r\n\r\nO audio nativo e sempre a referencia. A aproximacao escrita PT/EN aparece apenas como apoio inicial e nunca como forma correta.\r\n\r\n### Boca, lingua e garganta\r\n\r\n- Boca: abrir apenas o necessario para manter contraste entre vogais longas, curtas e ditongos.\r\n- Lingua: manter ponta da lingua leve atras dos dentes superiores para `t/d/n/l`; recuar a parte posterior para `g/ch/sch`.\r\n- Garganta: `g/ch` devem criar friccao atras da boca, sem transformar o som num `r` portugues nem num `h` ingles.\r\n\r\n### Ritmo B2\r\n\r\nO neerlandes B2 usa grupos de sentido, reducoes naturais e palavras funcionais fracas. O aluno deve entender a frase inteira, nao palavra por palavra.\r\n\r\n### Reducoes naturais\r\n\r\nTreinar formas como `''k`, `''t`, `''n`, `m''n`, `z''n`, `d''r`, ligacoes com `u/ik/het` e finais que soam como `t`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'posicao-da-boca', 10, '{"title":"Posicao da boca","body":"- Vogais longas: boca estavel, sem exagerar abertura.\r\n- `ui`: labios arredondam e movem; nao e `ai`, nao e `oi`.\r\n- `ij/ei`: som frontal com movimento controlado; confirmar sempre no audio.\r\n- Frases longas: boca relaxada, evitar articular cada palavra como se fosse isolada."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'posicao-da-lingua', 11, '{"title":"Posicao da lingua","body":"- `t/d/n/l`: ponta da lingua perto dos dentes superiores.\r\n- `r`: leve e contextual; nao forcar vibracao portuguesa.\r\n- `g/ch/sch`: parte posterior da lingua aproxima-se do palato mole, criando friccao.\r\n- Em fala rapida, lingua deve acompanhar blocos, nao soletrar palavra por palavra."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'sons-de-garganta-quando-aplicavel', 12, '{"title":"Sons de garganta quando aplicavel","body":"`g`, `ch` e `sch` aparecem frequentemente nesta licao. Produzir friccao atras da boca, com ar continuo. Nao bloquear como `k` e nao transformar em `h` ingles.\r\n\r\nTreino:\r\n\r\n```text\r\ngoed\r\ngraag\r\nbegrijp\r\nvergadering\r\nvoorzichtig\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 13, '{"title":"Ritmo e entoacao","body":"Treinar ritmo por blocos:\r\n\r\n```text\r\nGraag ontvang ik nadere informatie over de procedure en de termijn waarbinnen ik een reactie kan verwachten.\r\n```\r\n\r\nPalavras de conteudo recebem mais peso; artigos, pronomes e auxiliares podem ficar fracos. A entoacao deve manter profissionalismo: clara, calma e sem subida exagerada no fim de cada frase."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 14, '{"title":"Blocos sonoros","body":"```text\r\nbloco 1: contexto ou posicao\r\nbloco 2: informacao principal\r\nbloco 3: justificacao ou condicao\r\nbloco 4: consequencia ou pedido\r\n```\r\n\r\nExemplo da licao:\r\n\r\n```text\r\nGraag ontvang ik nadere informatie over de procedure en de termijn waarbinnen ik een reactie kan verwachten.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 15, '{"title":"Exercicios de shadowing","body":"1. Ouvir o audio nativo completo sem falar.\r\n2. Ouvir novamente e marcar palavras fortes.\r\n3. Repetir so o primeiro bloco.\r\n4. Repetir a frase completa em forma lenta.\r\n5. Falar junto com a forma natural.\r\n6. Repetir com reducoes naturais.\r\n7. Gravar uma resposta propria de 45-60 segundos usando pelo menos tres estruturas da licao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 16, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nOuvir 10 palavras B2 da licao e escrever a palavra-chave reconhecida.\r\n\r\n### Frase lenta\r\n\r\nOuvir 5 frases lentas e identificar verbo principal, conector e informacao nova.\r\n\r\n### Frase natural\r\n\r\nOuvir as mesmas frases em velocidade natural e responder: qual e a intencao do falante?\r\n\r\n### Mini dialogo\r\n\r\nOuvir um dialogo B2 de 60-90 segundos com duas vozes. Identificar situacao, problema, decisao e proxima acao.\r\n\r\n### Identificacao de palavras-chave\r\n\r\nMarcar palavras que indicam contraste, causa, prazo, obrigacao, opiniao ou decisao.\r\n\r\n### Escolha multipla auditiva\r\n\r\nEscolher a opcao que melhor resume o audio. As respostas erradas devem ser plausiveis, nao obvias.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar lacunas com conectores, verbos no fim e palavras reduzidas.\r\n\r\n### Compreensao do dialogo\r\n\r\nResponder em PT/EN no inicio e depois em neerlandes simples: o que aconteceu e o que deve ser feito?\r\n\r\n### Teste final auditivo\r\n\r\nOuvir audio novo sem transcricao. O aluno deve produzir um resumo oral de 45 segundos e uma nota escrita curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 17, '{"title":"Exercicios escritos","body":"1. Escrever 5 frases com estruturas da licao.\r\n2. Reescrever uma frase direta numa forma mais formal ou mais precisa.\r\n3. Corrigir ordem verbal em 6 frases.\r\n4. Escrever um paragrafo de 90-120 palavras sobre a situacao da licao.\r\n5. Rever o texto usando checklist: verbo, conector, registo, clareza e final de palavra."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 18, '{"title":"Exercicios orais","body":"1. Ler as frases uteis em voz alta com audio nativo.\r\n2. Responder oralmente a 5 perguntas inesperadas.\r\n3. Explicar a situacao da licao em 60 segundos.\r\n4. Defender uma escolha com razao e exemplo.\r\n5. Gravar e comparar: ritmo, reducoes, `g/ch`, vogais dificeis e pausas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 19, '{"title":"Mini dialogo realista","body":"```text\r\nA: Kunt u kort uitleggen wat het belangrijkste punt is?\r\nB: Ja. Graag ontvang ik nadere informatie over de procedure en de termijn waarbinnen ik een reactie kan verwachten.\r\nA: Begrijp ik goed dat er nog een actie nodig is?\r\nB: Ja, ik zal dat vandaag nog opvolgen en u uiterlijk morgen informeren.\r\nA: Prima, dan zetten we dat in de notulen.\r\nB: Akkoord. Ik stuur daarna ook een korte samenvatting.\r\n```\r\n\r\nTarefa:\r\n\r\n- Ouvir o dialogo em forma lenta.\r\n- Ouvir em forma natural.\r\n- Marcar palavras-chave.\r\n- Fazer shadowing da fala B.\r\n- Substituir uma frase por uma resposta propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 20, '{"title":"Roleplay","body":"### Papel A\r\n\r\nVoce e um colega, entrevistador, funcionario ou contacto profissional. Faca perguntas naturais, peca exemplos e interrompa uma vez de forma educada.\r\n\r\n### Papel B\r\n\r\nVoce e o aluno. Deve responder com clareza, usar pelo menos tres palavras da licao, uma estrutura complexa e uma frase de clarificacao.\r\n\r\n### Criterio do roleplay\r\n\r\nO roleplay so fica concluido quando o aluno consegue manter interacao durante 4-6 minutos sem voltar a frases A1/A2 e sem depender de traducao literal."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 21, '{"title":"Erros comuns","body":"- Tratar aproximacao escrita como pronuncia real.\r\n- Falar palavra por palavra, sem blocos de sentido.\r\n- Usar ingles para preencher palavras profissionais.\r\n- Usar ordem inglesa/portuguesa depois de conectores.\r\n- Evitar estruturas complexas por medo de errar.\r\n- Soar demasiado direto em contexto formal.\r\n- Confundir fluencia com velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 22, '{"title":"Quiz","body":"1. Qual e a funcao principal desta licao?\r\n2. Que frase mostra registo profissional adequado?\r\n3. Onde deve ficar o verbo numa subordinada com `omdat` ou `hoewel`?\r\n4. Qual palavra indica contraste?\r\n5. Qual e o erro de pronuncia mais comum para falantes PT?\r\n6. Qual e o erro de pronuncia mais comum para falantes EN?\r\n7. O que deve ser identificado num audio B2 alem das palavras?\r\n8. Quando se usa uma reducao natural?\r\n9. Que criterio mostra dominio oral?\r\n10. Escreva uma resposta B2 curta usando duas estruturas da licao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 23, '{"title":"Flashcards","body":"Criar flashcards para:\r\n\r\n- 8 palavras principais com audio nativo.\r\n- 5 frases principais com forma lenta, natural e reduzida.\r\n- 5 conectores ou marcadores de registo.\r\n- 5 erros comuns.\r\n- 3 criterios de dominio.\r\n\r\nFormato:\r\n\r\n```text\r\nFrente: audio nativo + frase em neerlandes\r\nVerso: traducao PT/EN + funcao + nota fisica de pronuncia\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'tarefa-final-da-licao', 24, '{"title":"Tarefa final da licao","body":"O aluno recebe um input novo relacionado com a licao: um audio, email, excerto de reuniao ou pergunta profissional. Deve:\r\n\r\n1. identificar informacao principal;\r\n2. responder oralmente;\r\n3. escrever um resumo curto;\r\n4. usar vocabulario e gramatica da licao;\r\n5. autoavaliar pronuncia e clareza.\r\n\r\nResposta-modelo esperada:\r\n\r\n```text\r\nGraag ontvang ik nadere informatie over de procedure en de termijn waarbinnen ik een reactie kan verwachten.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 25, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- entender audio nativo da licao em forma lenta e natural;\r\n- reconhecer reducoes e palavras-chave em contexto;\r\n- produzir as frases principais com ritmo natural;\r\n- explicar a situacao em 60 segundos;\r\n- escrever uma resposta coerente de 90-120 palavras;\r\n- participar num roleplay de 4-6 minutos;\r\n- usar a aproximacao escrita apenas como apoio inicial;\r\n- adaptar linguagem a contexto B2 sem transformar a resposta num phrasebook."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'nota-de-revisao-pedagogica', 26, '{"title":"Nota de revisao pedagogica","body":"B2-02 exige revisao pedagogica especial: registo formal depende muito de pragmatica, contexto institucional e tom; precisa de QA nativo para evitar frases demasiado duras ou antiquadas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'betreft', 'refere-se a/diz respeito a', 'concerns', 'Na palavra `betreft`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Deze vraag betreft mijn aanvraag.', 1 from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'aanvraag', 'pedido/requerimento', 'application/request', 'Na palavra `aanvraag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn aanvraag is nog in behandeling.', 2 from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'procedure', 'procedimento', 'procedure', 'Na palavra `procedure`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Kunt u de procedure uitleggen?', 3 from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'nadere', 'mais detalhada/adicional', 'further', 'Na palavra `nadere`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Graag ontvang ik nadere informatie.', 4 from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'verzoek', 'pedido formal', 'request', 'Na palavra `verzoek`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik dien een verzoek in.', 5 from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'bevestiging', 'confirmacao', 'confirmation', 'Na palavra `bevestiging`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik wacht op uw bevestiging.', 6 from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'termijn', 'prazo', 'deadline/term', 'Na palavra `termijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Binnen welke termijn?', 7 from lessons l where l.code = 'B2-02';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'hoogachtend', 'com os melhores cumprimentos formal', 'yours faithfully', 'Na palavra `hoogachtend`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Hoogachtend,', 8 from lessons l where l.code = 'B2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Graag ontvang ik nadere informatie over de procedure.', 'Gostaria de receber informacao adicional sobre o procedimento.', 'I would like to receive further information about the procedure.', 'Graag ontvang ik / nadere informatie / over de procedure.', 'Graag ontvang ik nadere informatie over de procedure.', 'Graag ontvang ik nadere informatie over de procedure.', 'Graag ontvang ''k nadere informatie over de procedure.', 'Na frase `Graag ontvang ik nadere informatie over de procedure.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'B2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Zou u kunnen bevestigen dat mijn aanvraag is ontvangen?', 'Poderia confirmar que o meu pedido foi recebido?', 'Could you confirm that my application has been received?', 'Zou u kunnen bevestigen / dat mijn aanvraag / is ontvangen?', 'Zou u kunnen bevestigen dat mijn aanvraag is ontvangen?', 'Zou u kunnen bevestigen dat mijn aanvraag is ontvangen?', 'Zou u kunnen bevestigen dat m''n aanvraag is ontvangen?', 'Na frase `Zou u kunnen bevestigen dat mijn aanvraag is ontvangen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'B2-02';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik verzoek u vriendelijk om binnen twee weken te reageren.', 'Solicito gentilmente que responda dentro de duas semanas.', 'I kindly request that you respond within two weeks.', 'Ik verzoek u vriendelijk / om binnen twee weken / te reageren.', 'Ik verzoek u vriendelijk om binnen twee weken te reageren.', 'Ik verzoek u vriendelijk om binnen twee weken te reageren.', '''k Verzoek u vriendelijk om binnen twee weken te reageren.', 'Na frase `Ik verzoek u vriendelijk om binnen twee weken te reageren.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'B2-02';
