insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 1, '{"title":"Contexto real de utilizacao","body":"B2 exige ouvir neerlandes real: chamadas, reunioes, anuncios, colegas, podcasts curtos e conversas com ruido. O aluno deve captar o essencial mesmo sem entender cada palavra.\r\n\r\nSituacao real:\r\n\r\n```text\r\nO aluno ouve dois colegas discutir uma mudanca de horario e precisa identificar decisao, motivo e proxima acao.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 2, '{"title":"Objetivos da licao","body":"- identificar palavras-chave em fala rapida\r\n- reconhecer reducoes\r\n- entender varias vozes\r\n- inferir atitude\r\n- tomar notas durante audio\r\n- responder oralmente ao que ouviu"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 3, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `waarschijnlijk`\r\n\r\nTraducao PT: provavelmente  \r\nTraducao EN: probably  \r\nAudio nativo: `audio/B2-08/words/waarschijnlijk.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `waarschijnlijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer palavra longa sem ritmo.\r\n- EN: English probably.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWaarschijnlijk begint de vergadering later.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nwaarschijnlijk\r\nwaarschijnlijk em frase\r\nWaarschijnlijk begint de vergadering later.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `waarschijnlijk` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `waarschijnlijk` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 2\r\n\r\nPalavra: `blijkbaar`\r\n\r\nTraducao PT: aparentemente  \r\nTraducao EN: apparently  \r\nAudio nativo: `audio/B2-08/words/blijkbaar.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `blijkbaar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: confundir com claro.\r\n- EN: apparently tone.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBlijkbaar is de planning veranderd.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nblijkbaar\r\nblijkbaar em frase\r\nBlijkbaar is de planning veranderd.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `blijkbaar` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `blijkbaar` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 3\r\n\r\nPalavra: `ondertussen`\r\n\r\nTraducao PT: entretanto  \r\nTraducao EN: meanwhile  \r\nAudio nativo: `audio/B2-08/words/ondertussen.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ondertussen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir palavra por palavra.\r\n- EN: meanwhile only.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nOndertussen regelen wij de ruimte.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nondertussen\r\nondertussen em frase\r\nOndertussen regelen wij de ruimte.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `ondertussen` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `ondertussen` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 4\r\n\r\nPalavra: `afgesproken`\r\n\r\nTraducao PT: combinado/acordado  \r\nTraducao EN: agreed  \r\nAudio nativo: `audio/B2-08/words/afgesproken.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afgesproken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: perder prefixo `af`.\r\n- EN: miss prefix.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDat is afgesproken.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafgesproken\r\nafgesproken em frase\r\nDat is afgesproken.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afgesproken` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afgesproken` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 5\r\n\r\nPalavra: `kennelijk`\r\n\r\nTraducao PT: pelos vistos/ao que parece  \r\nTraducao EN: apparently/evidently  \r\nAudio nativo: `audio/B2-08/words/kennelijk.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kennelijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar como certeza absoluta.\r\n- EN: use evidently too strong.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nKennelijk was er miscommunicatie.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkennelijk\r\nkennelijk em frase\r\nKennelijk was er miscommunicatie.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kennelijk` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kennelijk` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 6\r\n\r\nPalavra: `misverstand`\r\n\r\nTraducao PT: mal-entendido  \r\nTraducao EN: misunderstanding  \r\nAudio nativo: `audio/B2-08/words/misverstand.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `misverstand`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar misunderstanding em ingles.\r\n- EN: English rhythm.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nEr was een misverstand.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmisverstand\r\nmisverstand em frase\r\nEr was een misverstand.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `misverstand` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `misverstand` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 7\r\n\r\nPalavra: `achteraf`\r\n\r\nTraducao PT: depois/no fim  \r\nTraducao EN: afterwards/in retrospect  \r\nAudio nativo: `audio/B2-08/words/achteraf.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `achteraf`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: confundir com atras.\r\n- EN: say after all.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nAchteraf was dat duidelijk.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nachteraf\r\nachteraf em frase\r\nAchteraf was dat duidelijk.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `achteraf` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `achteraf` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal.\r\n\r\n\r\n### Palavra 8\r\n\r\nPalavra: `tussen haakjes`\r\n\r\nTraducao PT: entre parentesis/a proposito  \r\nTraducao EN: by the way  \r\nAudio nativo: `audio/B2-08/words/tussen-haakjes.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial apenas; confirmar sempre com audio nativo  \r\nAproximacao inicial EN: initial support only; always confirm with native audio\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `tussen haakjes`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: traduzir literalmente sempre.\r\n- EN: literal brackets.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nTussen haakjes, de locatie is veranderd.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntussen haakjes\r\ntussen haakjes em frase\r\nTussen haakjes, de locatie is veranderd.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `tussen haakjes` isolado, numa frase natural e num excerto B2 com informacao implicita. Deve identificar significado, funcao comunicativa e nuance de registo.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `tussen haakjes` em audio nativo, explica a nuance em PT ou EN e usa a palavra numa resposta B2 propria sem depender da traducao literal."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 4, '{"title":"Verbos principais","body":"- `kunnen`: expressar capacidade, pedido educado e possibilidade.\r\n- `moeten`: indicar obrigacao, requisito ou necessidade profissional.\r\n- `zullen`: proposta, expectativa, compromisso ou futuro formal.\r\n- `worden`: passiva e desenvolvimento de situacoes.\r\n- `bespreken`: discutir tema em contexto profissional.\r\n- `toelichten`: explicar ponto com detalhe e clareza.\r\n- `onderbouwen`: fundamentar com razoes, dados ou exemplos.\r\n- `aanpassen`: adaptar linguagem, plano ou comportamento ao contexto."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 5, '{"title":"Gramatica necessaria","body":"A audicao avancada trabalha gramatica em tempo real: reducoes de pronomes/artigos, verbos no fim que chegam tarde, conectores fracos e mudanca de sujeito.\r\n\r\nMini regra pratica:\r\n\r\n```text\r\nideia principal + conector + detalhe/condicao + consequencia\r\n```\r\n\r\nO aluno deve produzir frases mais longas apenas quando consegue manter verbo, sujeito, pronome e final de palavra sob controlo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 6, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Waarschijnlijk begint de vergadering een kwartier later.`\r\n\r\nTraducao PT: Provavelmente a reuniao comeca quinze minutos mais tarde.  \r\nTraducao EN: The meeting will probably start fifteen minutes later.  \r\nAudio nativo: `audio/B2-08/phrases/waarschijnlijk-begint-de-vergadering-een-kwartier-later.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nEntender mudanca.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWaarschijnlijk / begint de vergadering / een kwartier later.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWaarschijnlijk begint de vergadering een kwartier later.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWaarschijnlijk begint de vergadering een kwartier later.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWaarschijnlijk begint de vergadering ''n kwartier later.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Waarschijnlijk begint de vergadering een kwartier later.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: perder palavra-chave por ser longa.\r\n- EN: miss probably.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWaarschijnlijk / begint de vergadering / een kwartier later.\r\nWaarschijnlijk begint de vergadering een kwartier later.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 2\r\n\r\nFrase: `Blijkbaar is er een misverstand ontstaan.`\r\n\r\nTraducao PT: Pelos vistos surgiu um mal-entendido.  \r\nTraducao EN: Apparently a misunderstanding has arisen.  \r\nAudio nativo: `audio/B2-08/phrases/blijkbaar-is-er-een-misverstand-ontstaan.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nInferir problema.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nBlijkbaar / is er / een misverstand ontstaan.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nBlijkbaar is er een misverstand ontstaan.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nBlijkbaar is er een misverstand ontstaan.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nBlijkbaar is''r ''n misverstand ontstaan.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Blijkbaar is er een misverstand ontstaan.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: nao ouvir reducao.\r\n- EN: miss reduced is there.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nBlijkbaar / is er / een misverstand ontstaan.\r\nBlijkbaar is er een misverstand ontstaan.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 3\r\n\r\nFrase: `Dat hadden we anders afgesproken.`\r\n\r\nTraducao PT: Tinhamos combinado isso de outra forma.  \r\nTraducao EN: We had agreed that differently.  \r\nAudio nativo: `audio/B2-08/phrases/dat-hadden-we-anders-afgesproken.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nContraste.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nDat hadden we / anders / afgesproken.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nDat hadden we anders afgesproken.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nDat hadden we anders afgesproken.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nDat hadden we anders afgesproken.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Dat hadden we anders afgesproken.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: confundir passado.\r\n- EN: miss past perfect-like meaning.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nDat hadden we / anders / afgesproken.\r\nDat hadden we anders afgesproken.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 4\r\n\r\nFrase: `Kunt u de belangrijkste punten herhalen?`\r\n\r\nTraducao PT: Pode repetir os pontos principais?  \r\nTraducao EN: Could you repeat the most important points?  \r\nAudio nativo: `audio/B2-08/phrases/kunt-u-de-belangrijkste-punten-herhalen.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPedir resumo.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u / de belangrijkste punten / herhalen?\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u de belangrijkste punten herhalen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKunt u de belangrijkste punten herhalen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nKunt u de belangrijkste punten herhalen?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u de belangrijkste punten herhalen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: pedir tudo em vez do essencial.\r\n- EN: ask repeat all.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nKunt u / de belangrijkste punten / herhalen?\r\nKunt u de belangrijkste punten herhalen?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo.\r\n\r\n\r\n### Frase 5\r\n\r\nFrase: `Ik heb niet alles verstaan, maar de beslissing is duidelijk.`\r\n\r\nTraducao PT: Nao percebi tudo, mas a decisao esta clara.  \r\nTraducao EN: I did not understand everything, but the decision is clear.  \r\nAudio nativo: `audio/B2-08/phrases/ik-heb-niet-alles-verstaan-maar-de-beslissing-is-duidelijk.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nAudicao realista.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk heb niet alles verstaan / maar / de beslissing is duidelijk.\r\n```\r\n\r\nRitmo:\r\n\r\nEm B2, a frase deve soar como parte de discurso continuo. Treinar primeiro por blocos, depois com foco nas palavras fortes, depois em fala natural com reducoes controladas.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; nao e pronuncia correta\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; not the correct pronunciation\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk heb niet alles verstaan, maar de beslissing is duidelijk.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk heb niet alles verstaan, maar de beslissing is duidelijk.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Heb niet alles verstaan, maar de beslissing is duidelijk.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik heb niet alles verstaan, maar de beslissing is duidelijk.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: achar que tem de entender cada palavra.\r\n- EN: think full comprehension required.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk heb niet alles verstaan / maar / de beslissing is duidelijk.\r\nIk heb niet alles verstaan, maar de beslissing is duidelijk.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir a forma lenta uma vez sem falar.\r\n2. Repetir por blocos e marcar as palavras fortes.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo, mantendo ritmo e entoacao.\r\n5. Repetir dentro de uma resposta de 4-6 frases.\r\n6. Gravar, comparar reducoes, finais de palavra e fluidez.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve a frase em fala natural, depois dentro de um mini dialogo B2. Deve identificar intencao, registo, palavra-chave, reducao natural e informacao implicita.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em velocidade natural, reproduz o ritmo sem portuguesizar/inglesar a pronuncia e adapta a frase a um contexto novo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'pronuncia-pt-nl', 7, '{"title":"Pronuncia PT -> NL","body":"A aproximacao escrita para falantes de portugues e apenas apoio inicial. O aluno deve ouvir primeiro o audio nativo, observar boca/lingua/garganta e so depois usar a aproximacao como ponte temporaria.\r\n\r\nFocos PT:\r\n\r\n- Evitar adicionar vogal no fim de palavras com consoante final: `besluit`, `akkoord`, `veranderd`.\r\n- Nao transformar `g/ch` em `r` portugues.\r\n- Manter contraste entre `ui`, `ij/ei`, `oe`, `aa`, `ee`.\r\n- Reduzir ritmo silabico portugues e treinar grupos de sentido neerlandeses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'pronuncia-en-nl', 8, '{"title":"Pronuncia EN -> NL","body":"A aproximacao escrita para falantes de ingles e apenas apoio inicial. O aluno deve evitar transferir ritmo, stress e vogais do ingles para neerlandes.\r\n\r\nFocos EN:\r\n\r\n- Nao substituir `g/ch` por `h` ingles.\r\n- Evitar stress ingles em palavras internacionais.\r\n- Fechar finais `d/t/k/p` sem adicionar som extra.\r\n- Treinar `ui` e `ij/ei` com audio nativo, nao com equivalentes ingleses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 9, '{"title":"Explicacao fisica dos sons dificeis","body":"### Audio nativo como referencia principal\r\n\r\nO audio nativo e sempre a referencia. A aproximacao escrita PT/EN aparece apenas como apoio inicial e nunca como forma correta.\r\n\r\n### Boca, lingua e garganta\r\n\r\n- Boca: abrir apenas o necessario para manter contraste entre vogais longas, curtas e ditongos.\r\n- Lingua: manter ponta da lingua leve atras dos dentes superiores para `t/d/n/l`; recuar a parte posterior para `g/ch/sch`.\r\n- Garganta: `g/ch` devem criar friccao atras da boca, sem transformar o som num `r` portugues nem num `h` ingles.\r\n\r\n### Ritmo B2\r\n\r\nO neerlandes B2 usa grupos de sentido, reducoes naturais e palavras funcionais fracas. O aluno deve entender a frase inteira, nao palavra por palavra.\r\n\r\n### Reducoes naturais\r\n\r\nTreinar formas como `''k`, `''t`, `''n`, `m''n`, `z''n`, `d''r`, ligacoes com `u/ik/het` e finais que soam como `t`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'posicao-da-boca', 10, '{"title":"Posicao da boca","body":"- Vogais longas: boca estavel, sem exagerar abertura.\r\n- `ui`: labios arredondam e movem; nao e `ai`, nao e `oi`.\r\n- `ij/ei`: som frontal com movimento controlado; confirmar sempre no audio.\r\n- Frases longas: boca relaxada, evitar articular cada palavra como se fosse isolada."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'posicao-da-lingua', 11, '{"title":"Posicao da lingua","body":"- `t/d/n/l`: ponta da lingua perto dos dentes superiores.\r\n- `r`: leve e contextual; nao forcar vibracao portuguesa.\r\n- `g/ch/sch`: parte posterior da lingua aproxima-se do palato mole, criando friccao.\r\n- Em fala rapida, lingua deve acompanhar blocos, nao soletrar palavra por palavra."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'sons-de-garganta-quando-aplicavel', 12, '{"title":"Sons de garganta quando aplicavel","body":"`g`, `ch` e `sch` aparecem frequentemente nesta licao. Produzir friccao atras da boca, com ar continuo. Nao bloquear como `k` e nao transformar em `h` ingles.\r\n\r\nTreino:\r\n\r\n```text\r\ngoed\r\ngraag\r\nbegrijp\r\nvergadering\r\nvoorzichtig\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 13, '{"title":"Ritmo e entoacao","body":"Treinar ritmo por blocos:\r\n\r\n```text\r\nIk heb niet alles verstaan, maar ik begrijp dat de vergadering waarschijnlijk later begint.\r\n```\r\n\r\nPalavras de conteudo recebem mais peso; artigos, pronomes e auxiliares podem ficar fracos. A entoacao deve manter profissionalismo: clara, calma e sem subida exagerada no fim de cada frase."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 14, '{"title":"Blocos sonoros","body":"```text\r\nbloco 1: contexto ou posicao\r\nbloco 2: informacao principal\r\nbloco 3: justificacao ou condicao\r\nbloco 4: consequencia ou pedido\r\n```\r\n\r\nExemplo da licao:\r\n\r\n```text\r\nIk heb niet alles verstaan, maar ik begrijp dat de vergadering waarschijnlijk later begint.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 15, '{"title":"Exercicios de shadowing","body":"1. Ouvir o audio nativo completo sem falar.\r\n2. Ouvir novamente e marcar palavras fortes.\r\n3. Repetir so o primeiro bloco.\r\n4. Repetir a frase completa em forma lenta.\r\n5. Falar junto com a forma natural.\r\n6. Repetir com reducoes naturais.\r\n7. Gravar uma resposta propria de 45-60 segundos usando pelo menos tres estruturas da licao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 16, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nOuvir 10 palavras B2 da licao e escrever a palavra-chave reconhecida.\r\n\r\n### Frase lenta\r\n\r\nOuvir 5 frases lentas e identificar verbo principal, conector e informacao nova.\r\n\r\n### Frase natural\r\n\r\nOuvir as mesmas frases em velocidade natural e responder: qual e a intencao do falante?\r\n\r\n### Mini dialogo\r\n\r\nOuvir um dialogo B2 de 60-90 segundos com duas vozes. Identificar situacao, problema, decisao e proxima acao.\r\n\r\n### Identificacao de palavras-chave\r\n\r\nMarcar palavras que indicam contraste, causa, prazo, obrigacao, opiniao ou decisao.\r\n\r\n### Escolha multipla auditiva\r\n\r\nEscolher a opcao que melhor resume o audio. As respostas erradas devem ser plausiveis, nao obvias.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar lacunas com conectores, verbos no fim e palavras reduzidas.\r\n\r\n### Compreensao do dialogo\r\n\r\nResponder em PT/EN no inicio e depois em neerlandes simples: o que aconteceu e o que deve ser feito?\r\n\r\n### Teste final auditivo\r\n\r\nOuvir audio novo sem transcricao. O aluno deve produzir um resumo oral de 45 segundos e uma nota escrita curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 17, '{"title":"Exercicios escritos","body":"1. Escrever 5 frases com estruturas da licao.\r\n2. Reescrever uma frase direta numa forma mais formal ou mais precisa.\r\n3. Corrigir ordem verbal em 6 frases.\r\n4. Escrever um paragrafo de 90-120 palavras sobre a situacao da licao.\r\n5. Rever o texto usando checklist: verbo, conector, registo, clareza e final de palavra."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 18, '{"title":"Exercicios orais","body":"1. Ler as frases uteis em voz alta com audio nativo.\r\n2. Responder oralmente a 5 perguntas inesperadas.\r\n3. Explicar a situacao da licao em 60 segundos.\r\n4. Defender uma escolha com razao e exemplo.\r\n5. Gravar e comparar: ritmo, reducoes, `g/ch`, vogais dificeis e pausas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 19, '{"title":"Mini dialogo realista","body":"```text\r\nA: Kunt u kort uitleggen wat het belangrijkste punt is?\r\nB: Ja. Ik heb niet alles verstaan, maar ik begrijp dat de vergadering waarschijnlijk later begint.\r\nA: Begrijp ik goed dat er nog een actie nodig is?\r\nB: Ja, ik zal dat vandaag nog opvolgen en u uiterlijk morgen informeren.\r\nA: Prima, dan zetten we dat in de notulen.\r\nB: Akkoord. Ik stuur daarna ook een korte samenvatting.\r\n```\r\n\r\nTarefa:\r\n\r\n- Ouvir o dialogo em forma lenta.\r\n- Ouvir em forma natural.\r\n- Marcar palavras-chave.\r\n- Fazer shadowing da fala B.\r\n- Substituir uma frase por uma resposta propria."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 20, '{"title":"Roleplay","body":"### Papel A\r\n\r\nVoce e um colega, entrevistador, funcionario ou contacto profissional. Faca perguntas naturais, peca exemplos e interrompa uma vez de forma educada.\r\n\r\n### Papel B\r\n\r\nVoce e o aluno. Deve responder com clareza, usar pelo menos tres palavras da licao, uma estrutura complexa e uma frase de clarificacao.\r\n\r\n### Criterio do roleplay\r\n\r\nO roleplay so fica concluido quando o aluno consegue manter interacao durante 4-6 minutos sem voltar a frases A1/A2 e sem depender de traducao literal."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 21, '{"title":"Erros comuns","body":"- Tratar aproximacao escrita como pronuncia real.\r\n- Falar palavra por palavra, sem blocos de sentido.\r\n- Usar ingles para preencher palavras profissionais.\r\n- Usar ordem inglesa/portuguesa depois de conectores.\r\n- Evitar estruturas complexas por medo de errar.\r\n- Soar demasiado direto em contexto formal.\r\n- Confundir fluencia com velocidade."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 22, '{"title":"Quiz","body":"1. Qual e a funcao principal desta licao?\r\n2. Que frase mostra registo profissional adequado?\r\n3. Onde deve ficar o verbo numa subordinada com `omdat` ou `hoewel`?\r\n4. Qual palavra indica contraste?\r\n5. Qual e o erro de pronuncia mais comum para falantes PT?\r\n6. Qual e o erro de pronuncia mais comum para falantes EN?\r\n7. O que deve ser identificado num audio B2 alem das palavras?\r\n8. Quando se usa uma reducao natural?\r\n9. Que criterio mostra dominio oral?\r\n10. Escreva uma resposta B2 curta usando duas estruturas da licao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 23, '{"title":"Flashcards","body":"Criar flashcards para:\r\n\r\n- 8 palavras principais com audio nativo.\r\n- 5 frases principais com forma lenta, natural e reduzida.\r\n- 5 conectores ou marcadores de registo.\r\n- 5 erros comuns.\r\n- 3 criterios de dominio.\r\n\r\nFormato:\r\n\r\n```text\r\nFrente: audio nativo + frase em neerlandes\r\nVerso: traducao PT/EN + funcao + nota fisica de pronuncia\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'tarefa-final-da-licao', 24, '{"title":"Tarefa final da licao","body":"O aluno recebe um input novo relacionado com a licao: um audio, email, excerto de reuniao ou pergunta profissional. Deve:\r\n\r\n1. identificar informacao principal;\r\n2. responder oralmente;\r\n3. escrever um resumo curto;\r\n4. usar vocabulario e gramatica da licao;\r\n5. autoavaliar pronuncia e clareza.\r\n\r\nResposta-modelo esperada:\r\n\r\n```text\r\nIk heb niet alles verstaan, maar ik begrijp dat de vergadering waarschijnlijk later begint.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 25, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- entender audio nativo da licao em forma lenta e natural;\r\n- reconhecer reducoes e palavras-chave em contexto;\r\n- produzir as frases principais com ritmo natural;\r\n- explicar a situacao em 60 segundos;\r\n- escrever uma resposta coerente de 90-120 palavras;\r\n- participar num roleplay de 4-6 minutos;\r\n- usar a aproximacao escrita apenas como apoio inicial;\r\n- adaptar linguagem a contexto B2 sem transformar a resposta num phrasebook."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'nota-de-revisao-pedagogica', 26, '{"title":"Nota de revisao pedagogica","body":"B2-08 exige revisao pedagogica especial: sem audio nativo real com varias vozes, ruido e velocidades, a licao nao valida competencia auditiva B2."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'waarschijnlijk', 'provavelmente', 'probably', 'Na palavra `waarschijnlijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Waarschijnlijk begint de vergadering later.', 1 from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'blijkbaar', 'aparentemente', 'apparently', 'Na palavra `blijkbaar`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Blijkbaar is de planning veranderd.', 2 from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'ondertussen', 'entretanto', 'meanwhile', 'Na palavra `ondertussen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ondertussen regelen wij de ruimte.', 3 from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'afgesproken', 'combinado/acordado', 'agreed', 'Na palavra `afgesproken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Dat is afgesproken.', 4 from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'kennelijk', 'pelos vistos/ao que parece', 'apparently/evidently', 'Na palavra `kennelijk`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Kennelijk was er miscommunicatie.', 5 from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'misverstand', 'mal-entendido', 'misunderstanding', 'Na palavra `misverstand`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Er was een misverstand.', 6 from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'achteraf', 'depois/no fim', 'afterwards/in retrospect', 'Na palavra `achteraf`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Achteraf was dat duidelijk.', 7 from lessons l where l.code = 'B2-08';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'tussen haakjes', 'entre parentesis/a proposito', 'by the way', 'Na palavra `tussen haakjes`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Tussen haakjes, de locatie is veranderd.', 8 from lessons l where l.code = 'B2-08';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Waarschijnlijk begint de vergadering een kwartier later.', 'Provavelmente a reuniao comeca quinze minutos mais tarde.', 'The meeting will probably start fifteen minutes later.', 'Waarschijnlijk / begint de vergadering / een kwartier later.', 'Waarschijnlijk begint de vergadering een kwartier later.', 'Waarschijnlijk begint de vergadering een kwartier later.', 'Waarschijnlijk begint de vergadering ''n kwartier later.', 'Na frase `Waarschijnlijk begint de vergadering een kwartier later.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'B2-08';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
